"""真机抓取：把桌上那只棕色盒子夹起来、抬到搬运高度。

**阶段顺序照 `skills/pick.py`，判据一条都不留。** 仿真那边每一步都靠真值判：指垫
接触点数（`finger_cube_contacts`）、方块实时坐标（`cube_pos`）、撞没撞到别的方块
（`bump_scan`）。真机上这三样**物理上就没有** —— 不是缺个 shim 能补齐的，所以这一支
换成真机读得到的三样：

    腕相机 + 标定   画面里那只盒子反推成基座系坐标（`real/perception.py`）
    夹爪舵机角度    合爪压不动了 = 到位置了；角度大 = 嘴里有东西（`grasp_check.py`）
    关节读数        正解出 TCP 和工具轴（`real/arm.py`）

**夹在哪儿。** 仿真的落点是「固定爪面贴着盒子侧面、留 `FIX_CLEAR` 的缝」
（`pick.py:679-697`）。真机取不到那两个函数读的指垫球（nexus 建场景时**加进去**的
`sph_tip` geom，`SO-ARM100/Simulation/SO101/so101_new_calib.xml` 里没有），但算式本身
只用得上三样：固定爪尖在哪、开合轴朝哪、盒子沿那个方向鼓出多少 —— 这三样真机都有。
所以落点照抄那一套：**盒子中心 + side·(半边长 + 缝)·开合轴**（`FIX_CLEAR_REAL` 那一段
记了缝为什么是 5mm 不是仿真那 1mm）。

**TCP 口径 = 固定爪尖**（2026-10-14 用户定，`real/arm.py` 的 `TCP_DELTA_BODY`）。以前
报的是仿真那套「两爪正中」，比爪尖多伸出去 13.7mm。直接拿它对盒子中心，等于让固定爪
插进盒子轮廓里：张着爪往下走是从盒子顶面捅进去的，`out/run_real_22.log` 三趟里盒子
每趟被推走几十毫米，合爪时嘴里是空的。

**不合爪到死、不预演。** 下探路上没有指垫接触守卫（仿真那个只记录不截断的 `bump`，
真机没得记）；合爪前也没有「验算」可做（`dry_run` 要模型副本，而模型里只有臂、没有
桌上那件东西的几何）。

**防撞在 `real/anti_jam.py`。** 走到一段的半路顶住了东西（推不动），就沿来路退回
5mm、重新规划再走一次；再顶就认了，那一段不走完，把失败交回上层。**它管的是「顶住了
推不动」，不是「轻轻碰上了」** —— 后者还是要接触传感，真机没有。`_goto`（进场、纠位、
退回）和下探那一段都挂了这层。

**形状和尺寸从画面估，不认配置里写死的那一行。** 看一眼的时候 `real/perception.py`
拿候选形状各投一遍剪影，谁跟画面里这块对得上是谁，估出来的那个往下用（进场高度、
转正朝向、下探终点）。估不出来才退回配置里那行，并把两边并排打出来。

**原地那一眼不成，分两段找**（`_sweep`）。第 1 段**前后左右**：在原地铺四个点，格子
边长 = 腕相机当前在盒子那个高度能看清的圆的内切半径（现算），走 `follow`。第 2 段
**原地抬个头**：回到中心，4 号腕关节掰到底（角度还是 `real/sweep_look.py` 那张表里
最远的那档），走关节空间、不走逆解。两段都是认出目标就停；都没认出来就收工，不在原地
重试。仿真扫完还会「换俯视相机再看一眼」，真机这一轮只有腕机这一路，那半截跳过。

**留在这一版外面的**：`pick.py` 的绕中立位、掉落之后回来重抓（`retry`）。第一条真机
不需要（进场本来就直奔上方 80mm），第二条要等这一版在现场跑通再说。
"""

from __future__ import annotations

import sys
from pathlib import Path

import numpy as np

_ROOT = Path(__file__).resolve().parent.parent
if str(_ROOT) not in sys.path:
    sys.path.insert(0, str(_ROOT))

from core import follow, geom, shapes, vision                     # noqa: E402
from core.follow import POS_SLEW, ROT_SLEW                        # noqa: E402
from core.interfaces import Skill                                 # noqa: E402
from core.params import (ALIGN_CHUNK, ALIGN_MAX_STEPS,            # noqa: E402
                         ALIGN_ROT_SLEW, ALIGN_TOL_DEG, CARRY,
                         GENTLE, GRIP_BIAS, GRIP_K, GRIP_RATE,
                         GRIP_SLACK, LIFT_Z, POS_SCALE,
                         SLOW, SPEED, STUCK_TOL,
                         acc_amax, speed_vmax)
from core.registry import register                                # noqa: E402
from core.round_state import RoundState                           # noqa: E402
from real import anti_jam                                         # noqa: E402

# 合爪最多走多少步（一步 ≈ 读 66ms + 写 21ms）。**这只是兜底** —— 正常合到盒子
# 或者合到底，`STUCK_TOL` 那 25 步就先把它收住了。真走到 300 步说明夹爪一直没停过：
# 那是故障（卡住了？没使能？），不是「盒子特别硬」，所以让它撞上限、如实报出来。
CLOSE_MAX_STEPS = 300

# `_goto` 最多解几趟。舵机在重力负载下会停在指令角之前（实测 3 号欠 1.9°、4 号欠 1.3°），
# 而 `goto_q` 收尾只把同一个目标角连发几遍、补不上这一截。从**走到的**姿态重解一次同一个
# 点就能补一点，几趟进 `tol`。3 是「够用又不至于在那儿来回蹭」的数，不是调出来的。
REAL_GOTO_TRIES = 3

# **走不到的，下一趟把指令放大补回来。** 一趟走完逐关节量一下「实际走了 ÷ 要求走了」，
# 下一趟就按这个比例的倒数放大。实测（COM10 从臂，2026-10-15，`out/probe_settle.log`）：
# 往「TCP 下降」那一侧走跟到 88~101%，往「上升」那一侧只跟 38~48%（2 号要动 −2.00° 只走
# 了 −0.97°、3 号 −3.67° 只走了 −1.41°）—— **每趟都只走掉一小半，方向是对的。**
#
# 放大对两种可能的原因都管用，所以不用先分辨是哪一种：是比例静差，放大直接把差补回来；
# 是死区，放大把误差推到死区外面去。
#
# `GAIN_MAX` 是**安全上限，不是调出来的数**。响应比本身会给出负值（实测 3 号要动 −0.26°、
# 实际走了 +0.62°），倒数就成了负的、或者除出个二十倍 —— 那会变成一次十几度的猛拽。夹在
# 1~3：最多放大三倍，方向永远跟逆解一致。
GAIN_MAX = 3.0
# 指令小于这个角度的关节，响应比是噪声（走位本身就停在限位外、读数也在抖），不参与放大。
# 0.3° ≈ 3.4 个刻度。
GAIN_MIN_ASK_DEG = 0.3

# 下探那一列点每隔多少米取一个。5mm 一个点：50mm 的下探 = 11 个点。太密没用（舵机分辨
# 率 0.088°/刻度，臂长 200mm 上一刻度约 0.3mm），太疏中间那段就成了一条弦、不是竖直线。
DESCEND_STEP = 0.005

# 下探落点里「固定爪面离盒子侧面留多少」的缝。仿真是 `core.params.FIX_CLEAR` = 1mm
# （`pick.py:694` 那一段用它），这里照抄。
#
# 这个数曾经按「下探落点差 3.2~3.8mm」放大到 5mm（`out/run_real_22.log`）。那会儿落点
# 还以**两爪开口中心**为基准，5mm 是补落点误差的；现在落点改成以**固定爪尖**为基准、
# 且把爪面探出的部分（`pad`）单算，缝就退化成「盒子的近侧面离固定爪面多远」这一个意思 ——
# 5mm 太大：`_probe_jawbox.py` 按 run_25 第 1 趟的真实姿态量，动爪合到底时爪尖落在
# 离固定爪尖 8.0mm 处，而 5mm 的缝把盒子近侧面正好放到同一点上，等于零余量、合爪时
# 爪尖擦着盒子侧面过去。1mm 时近侧面落在 4mm 上下，离固定爪面 2mm、离动爪合到底 4mm，
# 前后都留得下（run_25 三趟落点误差 3.7~4.2mm 里沿开合轴的那一份也在窗口内）。
#
# **2026-10-17 用户改口径：把画面那条带 `[20, 70]` 像素换算成毫米，1mm 太小。**
# 换算系数是**从日志里量出来的**，不是估的：`_probe_pxmm.py` 拿「相邻两眼的 TCP 实际位移
# （`走到 [x y z]mm` 读回来的真值）」配「方块中心像素位移」，80 份 `out/run_real_*.log`
# 共 171 组，**中位 6.06 px/mm**（四分位 4.96~6.98）。于是
#   `CLEAR_BAND_LO_PX = 20` → **3.3mm**，带中值 `45` → **7.4mm**，`HI = 70` → **11.6mm**。
# **取的是下限 3.3mm，不是带中值** —— 理由是下面那条老记录：`_probe_jawbox.py` 按 run_25
# 的真实姿态量过「动爪合到底时爪尖落在离固定爪尖 8.0mm 处，而 5mm 的缝正好把盒子近侧面
# 放到同一点上，等于零余量」。**缝一大，盒子就被推向动爪那一侧，那一侧的余量只有这么多。**
# 带中值 7.4mm 会越过它；下限 3.3mm 留在里面（这条尺子自己的容差是 ±5mm，等于窗口
# [−1.7, 8.3]mm，两头都不越界）。**要带中值就改这一个数。**
# 顺带记着这对不上的地方：那条像素带 20~70 是 3.5 倍宽，换算成毫米是 3.3~11.6mm；而按
# jawbox 量出来的可用窗口只有 1~4mm 那一段 —— 这也是「画面那条尺子斜着看不准」的一条旁证。
FIX_CLEAR_REAL = 0.0033

# 下探终点在「方块中心高度」之上再抬多少（米）。**2026-10-16 用户定：25mm（上一版 15mm）。**
# 之前下探终点 = 中心高度，实测爪尖落在估计上表面之下 7mm；用户判定爪尖戳在方块上、
# 横向让开时把方块一起带走了，先要求留 10mm 余量，`out/run_real_40.log` 那一趟量到固定爪
# 轮廓还是跟红区贴上了（缝 −3 像素），用户 2026-10-15 再抬到 15mm。
#
# **2026-10-16 再留 10mm。** 起因是「横移完高度掉了 → 抬回来」那一步从 run 70/71 起就不
# 收敛：第一趟不管要抬多少都往下掉约 1.1mm，放大后 3 号顶到 10° 以上就变成重摆整条臂
# （竖着冲 11~16mm、横着甩 25~34mm），冲上去又受重力落回来，循环不断。用户定：不修那一步，
# 改成**下探时就多留 10mm**，横向让开时爪尖本来就碰不到方块顶面，那一步从此不需要。
GRASP_Z_MARGIN_REAL = 0.025

# **上面那条余量是从「盒子中心」量的，盒子一高就不够。** 爪尖要越过的不是中心、是**顶面**：
# 18mm 的盒子（半高 9mm）中心 +25mm 之后离顶面还有 16mm；边长翻一倍到 36mm（半高 18mm）
# 就只剩 7mm —— 而 `out/run_real_36.log` 那次「爪尖戳在方块上、把方块推走」实测的偏差
# 量就是 7mm。所以再加一条**离顶面**的下限，两条取大的：
#
#   `余量 = max(GRASP_Z_MARGIN_REAL, sh.rest_z + GRASP_Z_OVER_TOP_REAL)`
#
# **16mm 是这么来的：**
# 让 18mm 那个盒子（现在唯一跑通的那件）算出来跟改之前**一模一样** ——
# `9 + 16 = 25`，正好等于 `GRASP_Z_MARGIN_REAL`，两条同时触底。所以这一改对 18mm 盒子
# **数值上零变化**，只对更高的物体抬高下探终点。
GRASP_Z_OVER_TOP_REAL = 0.016

# 转正那一段**不设步数上限**（用户 2026-10-17：「转正不搞步数限制」）。原来卡在
# `ALIGN_MAX_STEPS = 200`，上一趟正好被掐在 200 步、读数还差 26.5°。现在只按「有没有
# 进展」停：连续这么多段（每段 `ALIGN_CHUNK` 步）都没把最好的那一档再压低 0.5°，
# 就算转不动了。一段约 10 步，20 段 ≈ 200 步没进展 —— 卡死才停，转得动就一直转。
ALIGN_STALL_CHUNKS = 20

# 转正改成**关节空间纯旋转 + 模型闭环**（见 `_align` 的 docstring）。先拧这么多度看
# 那条尺子是涨是落 —— 方向当场量，不假设。之后每趟按剩的度数一次拧到位，单次夹在 ±45°，
# 最多拧这么多趟。
ALIGN_PROBE_DEG = 3.0
ALIGN_MAX_MOVES = 8

# **微调进带之后、合爪之前，再竖直下去这一截**（用户 2026-10-16：「微调结束后加一个垂直
# 下探，然后再合爪」）。下探终点只到「中心 + 25mm」就停了、微调全程 z 钉死，爪尖就停在
# 方块顶面上方 —— `out/run_real_74.log` 就是在这儿空抓的（微调进带了，6 号舵机还是走到
# 36.7° 全闭、爪里没东西）。这一截从那儿**只降 z、x/y 一点不动**地走到「中心 + 这个余量」。
# 0 = 走到方块中心那一档（方块 18mm 高，爪尖落在方块腰部，离桌面还有 8mm）。
# **0 → +5mm**（用户 2026-10-16 定：「下探离地高度 +5mm」）：终点从「方块中心那一档」
# 抬到方块中心上方 5mm —— 扎得浅一点。
# **+5mm → +2mm**（2026-10-16 第二次跑之前：「下落高度降低 3mm」）：再往下扎 3mm，
# 终点 = 方块中心上方 2mm。
GRASP_Z_FINAL_REAL = 0.002
# **这一截的验收只看 z**（用户 2026-10-16：「飘 <20mm 都没事」）。原来的验收直接吃
# `_goto` 那个三维误差，而这一段刻意只放 2、3 号 + 姿态权重 0（`FREE_DESCENT`），臂一斜
# TCP 横着必然跟着漂 —— `out/run_real_1x.log` 实测：到底了（z 走到 −15.9mm），横着漂
# 8.5mm，三维误差 9.4mm > 4mm，判 stall，退回去不合爪。现在横向单独给一条上限：
# z 到底（± `DESCEND_Z_TOL_MM`）+ 横漂 < `DESCEND_XY_TOL_MM` 就认这一截走成了。
DESCEND_XY_TOL_MM = 20.0
# **4 → 10mm**（用户 2026-10-16 定）。起因：这一截实测 z 差 3.9mm、判据 4mm，只赢 0.1mm，
# 用户看到就说「Z 余量改为 10mm」。这条只在这个验收里用，`_goto` 自己的 4mm 没动。
DESCEND_Z_TOL_MM = 10.0

# ---- 合爪前的轮廓检查（用户 2026-10-15 定的口径）----
# 两条判据，全在画面里量（`_jaw_check`）：
#   · `gap`  红区外沿离**整圈爪子轮廓**（固定爪 + 动爪张到底 / 合到底，见 `JAW_SHAPE_JSON`）
#            的距离要落在 `[CLEAR_BAND_LO_PX, CLEAR_BAND_HI_PX]` 这条带里（见下面那段；
#            `CLEAR_BAND_ON = False` 时退回「至少 `CLEAR_TARGET_PX` 像素」）。
#            **正 = 留了缝，负 = 红区探进爪子轮廓里（压上了）**；
#            `_gap_px` 给的是 `pointPolygonTest` 原值，`_jaw_check` 里取负翻过来。
#   · `axis` 目标中心离合爪轴不超过 `AXIS_TOL_PX` 像素。
# 不达标就照画面里的偏差挪一步（`_set_clearance`，z 不动、爪保持张着），**挪一眼量一眼**，
# 直到两条都进带里 —— 次数和步长都不写死，见下面 `CLEAR_GAIN` 那一节。
# **往哪挪（2026-10-15 用户定）：把「方块顶面中心」挪回描轮廓时点的那一点
# （`axis_ref_px`，「方块该被夹住的那个中心」），沿合爪轴那一段就是让爪子朝画面右边退。**
# **挪不进带里就不合爪，这一趟判失败**（2026-10-15 用户定：「一直调不进带里先判失败」）——
# 原来那版是纠不动也照常往下走，等于明知爪尖压在方块上还是合了。
#
# **准星那一套（固定爪尖那个像素、`_crosshair` / `_tip_px`）2026-10-15 用户要求删掉。**
# 它量的是「爪尖这一个点离红区多远」—— 一个点飘在两个爪子中间，量不出「爪面压没压到
# 方块」。现在只剩上面两条，量的是**整圈轮廓**。**尺子没换**：`CLEAR_TARGET_PX` 还是
# 准星当年那个「让开量该到 8 像素」（`out/run_real_37.log` 里那句）。
# **缝的下限 8 → 20 像素**（用户 2026-10-16 定）。量的是**沿合爪轴的净空**（`_gap_axis_px`），
# 不是「红区到爪轮廓的最近距离」—— 爪子跑到方块上方时后者会报出一条根本不存在的缝。
# 这个「量法」还在；**只有「下限」那半截被下面那条带换掉了**（见 `CLEAR_BAND_*`）。
#
# **2026-10-16 当天又改：这条单边下限被下面那条「带」顶掉了**（`CLEAR_BAND_*`）。留着它
# 是给 `CLEAR_BAND_ON = False` 那条回头路用的 —— 关掉带就一个字不差地退回这里。
CLEAR_TARGET_PX = 20.0
# **轴偏容差 8 → 40 → 30 → 20 → 25 → 35 像素**（用户 2026-10-16 五次改：先照
# `out/clear_step.jpg` 那一眼的 −32 放到 40，再 30，再收到 20，最后放到 25）。缝那条没跟着动。
# **25 → 35**（2026-10-16 第五次）：`out/run_real_1x3.log` 卡死在「缝 +21 已经进带、轴偏 −30
# 一直不动」，微调磨了 98 次没停。用户看了那一帧（`out/jaw_check.jpg`）判「这缝隙可以了」，
# 选的是「放容差、不动循环」这条路。
AXIS_TOL_PX = 35.0
# ---- 缝那条尺子：**从「只有下限」改成一条带**（2026-10-16 用户定）----
#
# 用户原话：「对准了是抓不住的，必须要把目标放在两个爪子中间，而不是对准」。
#
# 改之前只有下限 `gap >= CLEAR_TARGET_PX`（20 像素）—— 缝**越大越合格**，沿合爪轴这条
# 一维没有终点。微调于是顺着这个方向一路把方块往外推。**已知事实**：`out/run_real_89.log`
# 末态缝 **+46** 像素，门槛 20，判**过**，那一趟是空抓。
#
# 改之后两头都管：
#   · 缝 < `CLEAR_BAND_LO_PX` → 往外推（老行为，写的就是 `CLEAR_TARGET_PX`，没动）；
#   · 缝 > `CLEAR_BAND_HI_PX` → **反过来把方块拉回来**（`need_gap` 这时是负的）。
# 目标取带中值 `_gap_want_px()`。
#
# **两个数都要用户拍板**：`LO` 取的是用户 2026-10-16 在这条尺子上自己定的 20（原样，没动）；
# `HI = 35` 是**我补的占位值**，不是量出来的 —— 唯一的事实是「46 判过、空抓」，所以上限必须
# 明显低于 46，具体多少只能由用户定。**用户改这两个数就改这两行。**
#
# **还有个限制照实记着**：`real_wrist_jaw_shape.json` 里只描了 `fixed_jaw`，
# `moving_open` / `moving_closed` 从来没描过（`_trace_jaw.py` 只是支持描）。所以这里的「缝」
# 一直是**方块 ↔ 固定爪**的净空，动爪合过来时在哪、开多大，画面里没有 —— 「方块在两爪之间」
# 现在是拿「离固定爪留一条确定宽度的缝」代理的，不是直接看出来的。
CLEAR_BAND_LO_PX = 20.0
# **35 → 50 → 70**（用户 2026-10-16：「等这次整个跑完改一下缝隙，50 以内都行」，随后
# 「[20, 70] 改成这个」）。上一趟实测停在 +38~+40 的那几眼，用户看了画面判可以。
CLEAR_BAND_HI_PX = 75.0
# **70 → 75**（用户 2026-10-17：「缝是 20~75 像素」）。这条带上限就是拦门那半截 ——
# 同日用户定的口径是「新版离轴（3D `|p| <= 5mm`）+ 旧版的缝（画面这条带）」，见
# `_clearance_loop` 里 `_off_ok and _gap_ok` 那两行。
# 关掉 = 整条路退回 2026-10-16 之前那条「只有下限 `CLEAR_TARGET_PX`」的判据，一个字不差。
CLEAR_BAND_ON = True
# ---- 3D 判据：**只报数，不拦门**（2026-10-15 又改回来）----
# 它当过一阵门槛（5mm，`out/run_real_49.log` ~ `out/run_real_51.log`）。run 51 证伪了它的
# **修正方向**：下探到底第一眼，画面那两条报「轴偏 +4（过）/ 缝 −3」，同一帧 3D 报
# 「离轴 −12.1mm」，于是照毫米残差挪了两步 —— 挪完画面里方块中心从轴偏 +4 跑到 −123 像素
# （`out/jaw_check.jpg` 就是末态那张），越修越偏。同样是这一台，`out/run_real_48.log` 里
# 报「缝 −2 / 轴偏 +0.2」判过、离线 3D 真值却是离轴 11.5mm —— **两条链量出来的「合爪轴」
# 不是同一条**（3D 那条要过关节角 FK → 手眼标定 → 感知固定偏移 35.8mm）。
# 拦门改用画面那两条：用户 2026-10-15 的原话是「得让那条线能够碰到目标中心点」，
# 那条线（`axis_ref_px` / `axis_dir_px`）本来就在画面里。
# ---- 合爪门槛：**画面里那两条，必须同时满足**（2026-10-15 用户定）----
# 「我现在就需要在爪子轮廓和红色有距离 + 合爪方向线和目标中心对齐，只有满足这两个标准
#  才能合爪」—— 就是 `_jaw_check` 的「缝落在带里」且 `|axis| <= AXIS_TOL_PX`（当时缝那条
#  还是单边 `gap >= CLEAR_TARGET_PX`，2026-10-16 换成了带）。
# 3D 那两条（`_jaw_check_3d`）**照量照打、不拦门**。run 53 那一趟它判「过」（离轴 +2.5、
# 沿轴差 −4.3mm），同一眼的画面判「不过」（轴偏 −117 像素），而合爪是空抓、爪里没东西
# —— 跟画面一致、跟 3D 相反。所以拦门的只能是画面那两条。
CLEAR_3D_TOL_MM = 5.0
# **2026-10-15 用户改口径：拦门的换成 3D 那两条，而且方块中心冻住。**
# 起因：画面那个「方块中心」（`_box_center_px`，可见红区轮廓最上面四个角）会被爪子挡住
# 而乱跳 —— 实测同一趟微调前后挪了 34 像素，而同一对帧的 3D 中心只动 0.9mm。用户的判断
# 是「机械爪对目标图像的动态遮挡，目标的中心点一直在变」，据此定：
#   · 方块中心改用 `percep.locate` 的 3D 拟合，而且**冻住** —— 用下探**之前**那一眼量到的
#     那一个（`_set_clearance` 的 `center` / `guess`），后面每一眼都用它。方块在桌上不动，
#     就没有理由每眼重量一次、把量测噪声喂进判据。
#   · 合爪轴改用 `arm.tips()` 正解（固定爪尖 → 动爪尖那条水平线），也不读红区。
#   · 缝那一维换成沿轴的毫米残差（`s` 对 `+clear`）。
# **照实记着已知风险**：run 48/51/53 那三趟是「现量」的 3D 跟画面打架 —— 48 报离轴 11.5mm
# 而画面判过、51 照毫米残差挪越挪越偏、53 它判过而合爪是空抓。这一版跟那三趟的差别只有
# 一处：**中心不再现量**。成不成由跑出来说，别拿那三趟当这一版的结论。
# **2026-10-17 用户改回 3D：相机是斜的，画面里「对上了」在 3D 里没对上。**
# 用户原话：「夹取方向瞄准后恰恰抓不准，因为相机是斜的，导致图像里射线对准了目标顶面中心，
# 但其实爪尖偏向方块目标后面了」。
# 几何：`_box_center_px` 量的是方块**顶面**中心，合爪轴在方块**中部**高度，两者差一个
# 方块高度。相机正着朝下看时，这两个点同一个水平位置，画面里「中心落在轴线上」＝3D 里也
# 对中；相机一斜，那条图像线反投影出来的是**过相机中心的一个斜面**，顶面中心落在这个斜面
# 上、合爪轴却在旁边 —— 差的就是「高度差 × 斜度」。
# 本轮证据（`out/` 那一趟，记在本文件外的会话里）：下面那条缝的尺子量 **+42 像素判过**，
# 同一眼 3D 报 **沿轴 −20.6mm（该 +11.1，差 −31.8）**，最后爪尖比方块中心多走了 31.8mm。
# 所以拦门的换回 3D 毫米那两条；画面那两条照量照打（还要看「压上了没有」）。
# **已知风险照旧记着**（上面 run 62 那段和下面那段）：3D 那条量的是「感知中心 ↔ FK 轴」，
# 感知链本身那个 `real.percep_offset_mm` 的偏差它量不出来；落点又是照同一个中心算的，
# 所以它只能保证「走到落点上」，保证不了「落点是对的」。这一段成不成由跑出来说。
CLEAR_3D_ENFORCE = True
# **2026-10-15 用户再改口径：微调那条尺子换回画面，方块中心照旧冻住当抓取目标。**
# 起因：这一版拦门（3D 那条）在下探到底第一眼就报「离轴 +0.1mm / 沿轴差 +0.7mm」判过
# （`out/run_real_62.log`），而同一帧画面那条报「缝 −0.9 像素、轴偏 −9.8 像素」。两条
# 不可能都对：落点本来就是照冻住的那个点算出来的，3D 残留等于把落点跟自己比 —— 它量的
# 是自洽，量不到爪子离真方块有多远。画面那条量的是「整圈爪轮廓 ↔ 红区」的相对位置，
# 同一帧、不经过任何标定。用户定：按画面重新算这一步该走多少。
# **冻住的那个中心不动** —— 下探的 `aim`、`clear`、报出去的读数还是它；改的只是
# 「这一步该走多少毫米」，由画面两条误差经 `B` 换算，不再用 3D 残留。
# ---- 微调怎么走：**两条误差分开算、各管一维**（2026-10-15 用户定）----
# 「别限制什么微调次数限制和每一步的步数，你的策略要能按照实际情况来。」
#   · 垂直那条（`n_hat`）：`axis` → 0 —— 「合爪方向线和目标中心对齐」；
#   · 沿轴那条（`axis_dir`）：`gap` → `_gap_want_px()` —— 「爪子轮廓和红色有距离」。
#     （2026-10-16 之前这个目标是 `CLEAR_TARGET_PX`，只有下限、越远越合格；现在带开着时
#     是带中值，缝超出上限还会**反向**把方块拉回两爪之间。见 `_gap_need_px`。）
# **沿轴那一维不追参考点。** run 51/52 量出来：方块中心正落在参考点上的那一刻，`gap` 是
# −2 像素（固定爪挡在方块前面，看得见的红边界本来就贴着爪的轮廓）；要留出 8 像素的缝，
# 方块中心得比参考点再让开约 10 像素。两条一起抓，只有拿「缝」当沿轴的目标才可能同时满足。
# 误差向量 `dp = (−axis)·n_hat + _gap_need_px(gap, gap_exit)·axis_dir`（画面像素），乘
# `CLEAR_GAIN`、用**实测**的 `B`（TCP 走 1mm → 方块中心动多少像素）换成毫米走一步。
# `B` 初值取 `−px_per_m_xy`（**取负**：臂带着相机一起走，画面里的方块反着动），之后每走
# 一步拿「TCP 实际走的毫米」和「方块中心实际动的像素」做一次 Broyden 更新。
# **什么时候停**（都不是次数上限，是量出来的）：两条都过；或连着 `CLEAR_FLAT_STOP` 眼误差
# 不再变小；或这一步已经不足 `CLEAR_MIN_STEP_M`。停不进门槛 → `ok=False`，不合爪。
CLEAR_GAIN = 0.7            # 一步走「还差多少」的几成（1.0 = 一次走到，容易冲过头）
# **「连着几眼误差不再变小就停」这条判停 2026-10-16 用户要求取消。** 它量的是砍过的那份
# 误差（下面 `err = ‖dp‖`）：缝没到 8 像素之前 `seg_axis` 被置零，`err` 就恒等于缝那一项，
# 方块怎么挪都是 8.0 —— `out/run_real_75.log` 三趟走下来 8.0/8.0/8.0/7.9，判「不再收敛」
# 收工，而方块中心其实一路从左往右挪了 56 像素。**量不到的东西不能拿来判停。**
# 写 `None` = 这条关掉（另外两条判停还在：两条都进带里、或这一步不足 `CLEAR_MIN_STEP_M`）。
CLEAR_FLAT_STOP = None      # 原来是 3
# **「这一步不足 0.5mm 就不再走」这条判停 2026-10-16 用户要求取消**（「别判停了」）。
# `out/run_real_86.log` 就是它收的工：缝差 4 像素、照 `B⁻¹` 算出来只需 0.41mm，当场判
# 「不合爪，退回去」—— 臂还差 4 像素就到门槛了，却一步没走就收摊。写 0 = 永不触发。
CLEAR_MIN_STEP_M = 0.0      # 原来是 0.0005
# **缝不够的时候，一步至少走半个边长**（用户 2026-10-16：「每次发现缝不够大的时候至少要走
# 半个边长」「不够就走半个边长」）。0.5 = 半个边长，边长从感知那份清单里取（现在 18mm →
# 一步至少 9mm）。**只套在缝那一段**：对轴那一段有自己的 10 倍/8 倍走法。
CLEAR_GAP_MIN_HALF = 0.5
# **微调每一步就走这一档，不多不少**（用户 2026-10-16：「我们的微调能不能一小步一小步的来，
# 每次都走最小的步长」，随后「这动的也太少了」）。方向照算出来的，**长度就是它**（米）：
# 算出来该走 16mm 也只走这一档；算出来只剩 0.1mm 也走这一档。两段都用（缝 / 轴偏）。
#
# 换掉的是原来那条「缝不够就至少走半个边长」—— 那是个 **9mm 起的下限**，一步跨过整条带子
# 落到对面，实测那一轮 11 眼全在 缝 +16 ↔ +72 之间来回跳（带子 [20, 70]，一次没停进去）。
# 上一版只做上限（大于这一档才截），结果 0.1mm 那种步子照样被 `CLEAR_CONTACT_GAIN` 乘着
# 一路压到 0.02 倍 —— 臂几乎不动，用户判「动的也太少了」。所以这一档现在是**定长**，
# `CLEAR_CONTACT_GAIN` 那条（上一步把缝压进带里以下就缩小步子）已经不起作用了。
#
# **这个数现在只是「起算长度」，不再是最终长度。** 定长那一版实测根本没动（见下面
# `CLEAR_MIN_JOINT_DEG`）—— 2mm 是照「带子 50 像素宽、约 1mm ↔ 5 像素」估的。
CLEAR_STEP_M = 0.002
# **一步到底该多长，由「至少让关节动多少度」定**（用户 2026-10-16：「你应该定最小舵机
# 度数」）。写死 2mm 那一版实测没动：`out/run_real_*.log` 里指令 `[0 0 0 0.7 0 0]` 度，
# 走完 x 只挪 0.2mm，下一眼缝还是原来那个数 —— 逆解出来的增量落在 2/3/4 号的**起步死区**
# 里（`_goto` 的注释量过同一件事）。所以每步先解一遍看最大的自由关节要动几度，不够就把
# 长度乘上去重解。
#
# **2.0 度这个数是量出来的**，不是估的：`out/probe_joint_track.log` 和
# `out/probe_joint_track2.log`（`_probe_joint_track.py`，2 号肩抬 / 3 号肘 × ±2° / ±0.5°
# 各 3 次）—— ±0.5° 那一档「跟到」在 −369% ~ +545% 之间乱跳（实际走 −0.44 ~ +2.73°），
# ±2° 那一档才是 30~136%（都是正的、差不多跟得住）。**2° 是量出来能跟住的最小幅度。**
CLEAR_MIN_JOINT_DEG = 2.0
# 按度数往上乘的上限（倍）。防「解出来几乎不动」时一步跨出去太远。
CLEAR_MIN_DEG_GAIN_MAX = 10.0

# 上面那条下限从 2026-10-16 起**不再生效**（被封顶那条顶掉），留着只当记录。
CLEAR_CONTACT_GAIN = 0.4    # 上一步把缝压回带里以下、还在掉，步子乘这个（先压下来）
# **微调分两段走（2026-10-16 用户定）。** 原来把「方块中心对回合爪轴」和「缝退到门槛外」
# 加在一起一次走，在画面上是反方向的（爪轮廓占 y 285~420，合爪轴 y 388.5 横穿它 —— 把
