# 退干净了再去对轴。
CLEAR_EXIT_EPS_PX = 0.5     # 「整块退出去还要多少像素」小于这个就当退干净了
# **对轴那一段的走法：10 倍冲过去、8 倍退回来**（用户 2026-10-16 定：「微调策略仍然是：
# 先搞出缝隙，再调整轴偏，调整的时候 10 倍放大然后 8 倍返回」）。缝那一段不放大、一步走到；
# 只有 `need_gap` 清掉、进入纯对轴的那一步才套这两个数，净效果 = 2 倍。
CLEAR_AXIS_FAR = 10.0
CLEAR_AXIS_BACK = 8.0
# **净走得多就不绕这一圈**（用户 2026-10-16 追加：「对于乘2后大于15mm的移动就不需要这么干，
# 直接乘2就好」）。净 2 倍已经超过这个毫米数，就一步走到 2 倍；只有小步子才用「冲出去再退
# 回来」—— 那一圈的意义是掰小偏差，步子大了冲出去就是横甩。
CLEAR_AXIS_AMP_MAX_MM = 15.0

# ---- 微调这两段各放哪几个关节（2026-10-16 用户定）----
# 用户原话：「以后纠正轴偏就用 4 号舵机」「感觉纠缝隙不用 4 号，只动 1 和 5 吧」。
#
# 依据是实测的**每个关节让爪尖怎么走**（离线，在跑位那个姿态上每 1° 的位移，mm/度）：
#
#   关节        沿缝      ⊥缝（轴偏）   竖直     爪子自转
#   1 号 肩转   +3.13      +0.07        -0.00     +1.00°
#   2 号 肩抬   -0.03      -1.98        -2.58     +0.02°
#   3 号 肘     -0.06      -3.73        -1.56     +0.02°
#   4 号 腕俯仰 -0.05      -2.82        +0.61     +0.02°
#   5 号 腕转   +0.00      -0.15        +0.03     +1.00°
#
# 1 号是唯一动得了「沿缝」那一维的（3.13mm/度），代价是爪子自己转 1.00°/度 —— 5 号
# 转 1.00°/度正好抵掉，代价是轴偏 0.15mm/度（约每毫米缝 0.05mm 轴偏，5%）。
# 4 号那一转**就是轴偏那一维**（19 个实测姿态上，4 号让爪尖走的方向和几何上的
# 「⊥合爪轴」余弦 **−1.00**，19/19 全都对上），所以纠轴偏只给它。
