# **关掉 = 退回 2026-10-16 之前那条「五个关节一起解」**，一个字不差。
CLEAR_FREE_ON = True
# 关节序号按 `JOINT_ORDER`：0=shoulder_pan 1=shoulder_lift 2=elbow_flex 3=wrist_flex 4=wrist_roll。
# 缝那一段：**只放 1 号**（用户 2026-10-17：「先让 1 号搞出横移量，再纠正角度」）。
#
# 原来是 `(0, 4)` —— 5 号在里面抵掉 1 号每度 1.00° 的自转。用户 2026-10-17 否掉了这个组合：
