# 横移量的只有 1 号舵机**」。实测也支持（`_probe_free_gap.py`，跑位那一刻的姿态，每 1° 的
# 位移）：1 号 2.87mm、5 号 **0.16mm** —— 差 18 倍。5 号放进缝这一段，只会让逆解拿「转腕」
