# 代价照用户的话接受：1 号每度自转 1.00°，走 6.3mm 爪子跟着偏 2° —— 后面再纠。
#
# **2026-10-17 用户按当前工位改口径：「其实在这个角度下 4 号舵机适合造缝隙，
# 1 号舵机适合离轴微调。」** 两段对调。日志对得上：`_tan1` 那一行「1 号能走的方向
# (−0.20, +0.98)，夹角 66°，cos = +0.41」—— 1 号在造缝那一维上只剩四成力，它的
# 主方向恰好是垂直缝的那一维，也就是离轴。
FREE_GAP = (3,)     # ← **这是首选，不是唯一**：4 号在这一步的方向上出不上力时，
                    # `_free_for` 会从 `GAP_FALLBACK_POOL` 补一个关节进来（见下方）
FREE_AXIS = (0,)       # 轴偏那一段：只 1 号（底座转）
# 下高度那一段：**只放 2、3 号，姿态权重设 0**（2026-10-16 用户：「下高度用 2,3 就行
# ……爪子可以斜，但是爪尖只能有 z 动」）。
# 光限制关节不够，还得把姿态权重设 0 —— 离线实测（同一姿态、降 20mm，mm / 度）：
#
#   放开     姿态权重    Δx      Δy      Δz      爪子倾角漂
#   2+3      0         +0.00   +0.00   −20.00   大（随它斜，用户要的就是这个）
#   2+3      0.05      +0.64   +0.18   −19.22   +4.6°
#   2+3+4    0.05      +0.06   +0.02   −19.99   +0.27°
#   全放开   0.05      +0.06   +0.02   −19.99   +0.27°   ← 改之前就是这个
#
# 2+3 这两根轴是**同一个世界轴**（实测夹角 0.0°），所以它俩撑起来的是一张固定竖直面、
# 爪尖在面里只能走一条弧；把姿态那一项放开（权重 0）之后，那条弧正好是竖直直线。
FREE_DESCENT = (1, 2)


def _gap_free():
    """缝那一段放开的关节；`CLEAR_FREE_ON` 关掉就返回 `None`（= 老的五关节一起解）。"""
    return FREE_GAP if CLEAR_FREE_ON else None


def _ax_free():
    """轴偏那一段放开的关节；`CLEAR_FREE_ON` 关掉就返回 `None`。"""
    return FREE_AXIS if CLEAR_FREE_ON else None


# ---- 上面那个关节出不上力的时候，补一个进来（2026-10-17 用户定）----
# 上面那张表是**在一个姿态上**量的。1 号让爪尖走的方向是「过 TCP 那个圆的切向」
# `(−y, +x)` —— 合爪轴和切向差到 90° 时，1 号在这条轴上**一点力都出不上**（3.13 → 0）
# 而 2/3/4 号那一列正好换过来：实测 3 号沿那一维是 3.73mm/度，比 1 号满力时还大。
#
# 用户原话（2026-10-17）：「怎么动 1 号舵机都只是让爪子在圆弧上动作，制造不了横向距离」
# →「不如解放一个舵机加入」。**不去转腕子换一个面夹**（那要多转 90°），改成让逆解多放
# 一个关节。
#
# 挑法还是 `_step_min_deg` 那一套：每个候选关节只让它动 1°、正解出来的爪尖位移投到
# 「这一步该走的方向」上 —— **离线、不动臂、不碰串口**（读一次关节角 66ms 除外）。
GAP_FALLBACK_MIN_MM_DEG = 1.0   # 首选那几个关节沿这一步的方向、每度挪不到这么多毫米，
                                # 就算「出不上力」，补人。实测满力时 1 号是 2.87mm/度、
                                # 3 号是 3.90；出不上力时是 0.00 —— 1.0 落在中间空当里
# **只有「毫米/度」这一个判据不够。** 2026-10-17 那一趟的日志：1 号在要走的那个方向上
# cos 只有 +0.41（`⇢` 那行自己就标了「1 号几乎出不上力」），可 0.41 × 2.87 = 1.18，
# 仍然过了 1.0 的门槛 —— 于是一个关节都没补，一步 0.05°（小于舵机最小 2°），TCP 原地不动。
# 用户 2026-10-17：「1 号舵机起不了作用，怎么解决？」→ 方向余弦也当判据，两条都过才算有力。
GAP_FALLBACK_MIN_COS = 0.5      # 低于这个夹角余弦就是「几乎出不上力」（日志里那句判词用的
                                # 也是 0.5；cos 0.41 → 66°，再大一点就是纯侧推）
GAP_FALLBACK_POOL = (0, 1, 2, 3, 4)   # 1~5 号都是候选（夹爪那一维不在里面）。**权重是
                                      # 「沿这一步的毫米/度」而不是「方向对不对」** ——
                                      # 只比方向的话 2/3/4 号在退化姿态上全都等于 1.00，
                                      # 浮点差 1e-9 就能决定挑谁，挑到的会是 2.89 的 4 号
                                      # 而不是 3.90 的 3 号


def _joint_dir_xy(arm, q_now, j, deg: float = 1.0):
    """只动第 `j` 个关节 `deg` 度，爪尖在平面里往哪走。返回 `(方向单位向量, 毫米/度)`。"""
    q = np.array(q_now, dtype=np.float64, copy=True)
    q[j] = float(q[j]) + np.radians(float(deg))
    a = np.asarray(arm._sim_pose(*arm._fk(q_now))[0], dtype=np.float64)[:2]
    b = np.asarray(arm._sim_pose(*arm._fk(q))[0], dtype=np.float64)[:2]
    d = b - a
    n = float(np.linalg.norm(d))
    if n < 1e-12:
        return None, 0.0
    return d / n, n * 1000.0 / abs(float(deg))


def _free_for(arm, need, base):
    """这一步该走 `need`（底座系平面单位向量）—— `base` 那几个关节出不上力就补人。

    `base` 原样保留（用户要的是「解放一个舵机**加入**」，不是换掉）。判据是
    **沿 `need` 的毫米/度**：`base` 里最好的那个不够 `GAP_FALLBACK_MIN_MM_DEG`，就从
    `GAP_FALLBACK_POOL` 里挑分数最高的加进去。五个关节都没力臂就原样返回，并打一行
    ⚠ 出来 —— 那种工位摆法不是改关节能救的。
    """
    if need is None or not base:
        return base
    need = np.asarray(need, dtype=np.float64).reshape(-1)[:2]
    nrm = float(np.linalg.norm(need))
    if nrm < 1e-12:
        return base
    need = need / nrm
    try:
        q_now = np.array(arm._ticks_to_qpos(arm.read_ticks()), dtype=np.float64)
    except Exception:                                               # noqa: BLE001
        return base
    base = tuple(int(v) for v in base)

    def _score(j: int) -> float:
        """第 `j` 个关节**沿 `need` 每度能挪多少毫米**（带号不要，出力不分正反）。"""
        d, mm = _joint_dir_xy(arm, q_now, j)
        if d is None:
            return 0.0
        return float(mm) * abs(float(d @ need))

    def _cos(j: int) -> float:
        """第 `j` 个关节让爪尖走的方向跟 `need` 的夹角余弦（绝对值）。"""
        d, _mm = _joint_dir_xy(arm, q_now, j)
        return 0.0 if d is None else abs(float(d @ need))

    def _ok(j: int) -> bool:
        """这个关节算不算「有力」：**沿这一维的毫米/度**和**方向余弦**两条都得过。"""
        return (_score(j) >= GAP_FALLBACK_MIN_MM_DEG
                and _cos(j) >= GAP_FALLBACK_MIN_COS)

    best_base = max((_score(j) for j in base), default=0.0)
    if any(_ok(j) for j in base):
        return base
    # 挑人时也是「有力」优先，同档才比毫米/度。
    best_j, best = None, (False, best_base)
    for j in GAP_FALLBACK_POOL:
        if int(j) in base:
            continue
        r = (_ok(int(j)), _score(int(j)))
        if r > best:
            best_j, best = int(j), r
    if best_j is None or not best[0]:
        print(f"       ⚠ 这一维五个关节谁都没力臂（最好 {best[1]:.2f}mm/度、"
              f"cos {max((_cos(j) for j in base), default=0.0):.2f}；"
              f"门槛 {GAP_FALLBACK_MIN_MM_DEG:.1f}mm/度、"
              f"{GAP_FALLBACK_MIN_COS:.2f}）—— 这个摆法改关节救不回来")
        return base
    print(f"       {[j + 1 for j in base]} 号沿这一维只出 {best_base:.2f}mm/度、"
          f"cos {max((_cos(j) for j in base), default=0.0):.2f}（出不上力）"
          f" → 补 {best_j + 1} 号进来（{best[1]:.2f}mm/度）")
    return tuple(sorted(set(base) | {best_j}))

# 横移走完，读回来比微调前那一档低这么多就得单独抬回来（米）。用户 2026-10-16：
# 「横移只要在微调前的高度不下落就行」。
CLEAR_Z_KEEP_M = 0.0005
# **一步横移最多允许带下来多少高度**（米）。用户 2026-10-17：「你补进来的关节还在下
# 高度，也要纳入计算」—— 补进来的 2/3 号在竖直面里走弧，横移和下沉是同一个动作的两
# 个分量，不算进来就会拿高度换横移（上一趟横移完掉了 16.8mm）。`_step_min_deg` 现在
# 把这一次要掉的高度一起报出来，超过这个数就把步长按比例压回来。
CLEAR_STEP_DZ_M = 0.003
# 手动那一路的一次微调挪多远（米）。**只有 `PICK_MANUAL=1` 用得到**（`_set_clearance_manual`），
# 自动那一路的步长由上面那条策略自己算。2026-10-15 用户定为 20mm（先 10mm，判定「挪得不够」）。
NUDGE_STEP_M = 0.020

# ---- 手动那一路：微调这段交给外面一步一步给（2026-10-15 用户定）----
# 起因：自动那一路的次数和步长原来都写死。用户
# 「不把微调次数、每次微调距离写死，你来实时操控」—— 开着 `PICK_MANUAL=1` 跑，量完不
# 自己挪，把这一眼的读数摆到 `out/manual_state.jsonl`，然后等 `out/manual_cmd.json`。
#
# **命令是一串，不是一步。** 一条命令可以带好几步（`moves`），它按序走、每步量一次、
# 每量一次追加一行读数；中途外面又塞了新命令就**把剩下的几步丢掉、按新的来**。这样
# 臂不用每步停下来等操作员那一个来回（人/我读一次数、写一条命令要几十秒，臂停在那儿
# 就是白等）。
#
# 命令里的位移是**底座坐标系的毫米**，跟日志里「反解该动」同一个口径；爪保持张着。
# 给两个数 `[dx, dy]` 就只动横的，给三个数 `[dx, dy, dz]` 连高矮一起动（2026-10-15 加：
# 实测画面里方块上下跟 z 绑得很死，横向那两维推不动它）。基准是**进来那一瞬间的 tcp**，
# 每一步的偏移往上累加 —— 不是「当前实测 + 偏移」，那样臂够不着的那点每步攒一层。
MANUAL_CMD = _ROOT / "out" / "manual_cmd.json"
MANUAL_STATE = _ROOT / "out" / "manual_state.jsonl"
# 手动步数上限。**兜底用**：怕外面忘了收，臂一直带电停在方块上方。
MANUAL_MAX_MOVES = 12
# 等一条命令最多多久（秒）。超了就这一趟不合爪、退回去 —— 不把臂扔在那儿。
MANUAL_WAIT_S = 600.0
# 手动这一步的走位容差（米）。`_goto` 现在是「走完读回来离目标还有多远算到了」，
# 默认 4mm 够不着就再来一趟（一趟就是几秒）。微调这步挪完马上要重量、量的才是准数，
# 差 8mm 就不必再补一趟 —— 这是手动那一路提速主要省下来的时间。
