# ---- 断点续跑（`run_sim.py --resume-pick` / 环境变量 `PICK_RESUME=1`，2026-10-15 用户定）----
# 用户原话：「我的要求是从断点开始跑」。微调停在等你点头那一步时，把**这一眼的状态**写盘
# （`out/pick_checkpoint.json`）；进程被 kill 之后，下一次带 `--resume-pick` 跑就
# **从这一眼接着走** —— 不再重走「回位 → 起手合爪 → 进场 → 看一眼 → 纠位 → 转正 → 下探」。
#
# **断点是臂的姿态，不只是盘上那几个数。** 读写两头都拿六个关节角核对（`_arm_off_checkpoint`）：
# 臂已经离开那个姿态了（回过初始位置、或者人碰过），盘上那份就不认 —— 如实报差多少度、
# 拒绝续跑，而不是硬接着走。
# **只在 `PICK_CONFIRM=1` 那一路写盘**：只有那一路会停在半路，也只有那一路有个「等你点头」
# 这个可以停的位置。自动那一路一眼接一眼地走，没有断点可言。
CHECKPOINT = _ROOT / "out" / "pick_checkpoint.json"
