# ---- 回放开关：把**某一趟真机跑出来的数**原样再走一遍 -------------------------------
#
# **为什么需要它**：这条路上一趟在真机上没走通（`out/run_real_13.log`：进场、纠位、
# 下探三段全 stall）。想在仿真上看「同样的目标点，仿真臂走不走得动」，就得让仿真照着
# **那一趟的坐标**走，而不是拿仿真自己的 `real.pick_xy` 和仿真相机再量一遍 ——
# 那叫重算，不叫回放，两边走的根本不是同一条路。
#
# **只钉三个数**：起搜中心 `guess`、量出来的盒子中心 `center`、朝向 `yaw_deg`。
# 剩下的（进场 = guess+80mm、纠位 = center+80mm、转正法向、下探的 aim/entry/mid、
# 抬升高度）全是这段代码**自己算出来的**，一个都不钉 —— 回放的那条路径就是真机
# 那一趟的路径。`_look` / `_sweep` 整段跳过（不再看一眼）。
#
# 设成 None（默认）时这个文件的行为**一个字不变**。
REPLAY: dict | None = None

# ---- 只走前几段就收工 --------------------------------------------------------------
# 值是一串段名（`state.seg` 里那几个），逗号分隔。走到其中某一段**走完**就返回，
# 后面的一步不走。给「单独看某一段在真机上什么表现」用 —— 三整趟跑下来十几分钟，
# 问题在第一段就出的话，后面两段只是白耗舵机。
#
# 返回的 dict 一定带 `give_up: True`：策略层（`impls/policy_real.py`）见它就不重试了，
# 不然它会「没抓起来，回去再来」把这一趟原样再来两遍。
#
# None（默认）＝一路走到底，行为一个字不变。
STOP_AFTER: str | None = None

# ---- 等点头的时候，顺手干点别的 ----------------------------------------------------
# 一个可调用的对象，`_wait_cmd` **每一轮都调一次**（约每 0.1 秒）。默认 None ＝ 行为
# 一个字不变。
#
# **为什么要有它。** 停在断点上等点头的时候，这个进程整条卡在 `_wait_cmd` 里 —— 面板上
# 的关节、夹爪、TCP 点动全按不动，画面也冻在断点那一帧。人要「即时调整」，就得让等的那
# 一头也把面板的按键做掉（面板的硬件线程就在这儿，串口也在这儿，没有第二个人抢）。
#
# 面板（`panel/skill_driver.py`）把它设成「把面板队列里的命令清一遍 + 刷一拍快照」。
# **它必须快、必须不抛**：抛出去会把技能从等点头里顶出来。
WAIT_TICK = None


def _stop_set() -> set[str]:
    """`STOP_AFTER` 拆成段名的集合。空字符串 / None 都是空集（＝不提前停）。"""
    return {s.strip() for s in str(STOP_AFTER or "").split(",") if s.strip()}


def _stop_here(seg: str, arm, note: str = "") -> dict | None:
    """这一段**走完了**。`STOP_AFTER` 点到它就返回一个收工的 dict，没点到就是 None。

    返回的 dict 一定带 `give_up: True` —— 策略层（`impls/policy_real.py`）见它就不重试，
    不然它会「没抓起来，回去再来」把这一趟原样再来两遍。
    """
    if seg not in _stop_set():
        return None
    print(f"    ⏹ `--stop-after` 点到「{seg}」，到此为止（不重试）")
    return {"ok": False, "why": f"只走到「{seg}」{note}".strip(),
            "stop_after": seg, "give_up": True, "tcp": arm.tcp().tolist()}


def _cmd(arm) -> str:
    """这一步**真正发出去**的位置指令，一行。

    `RealArm` 没有 `last_action`（仿真那支有，记的是最后一次写下去的关节目标）。真机
    发出去的是**末端位移增量**，`arm.vel` 就是它 —— `real/arm.py` 里已经过位置斜率
    限幅、并且已经夹过可达范围的那一维。乘 `POS_SCALE` 换成毫米才看得懂。
    """
    v = getattr(arm, "vel", None)
    if v is None:
        return "指令=?"
    v = np.asarray(v, dtype=np.float64).ravel()[:3] * POS_SCALE * 1000.0
    return ("指令=" + np.array2string(v, precision=3, suppress_small=True,
                                      floatmode="fixed") + "mm")


def _trace(arm):
    """`follow.follow` 的 `verbose` 回调：每 40 步打一行。

    仿真的抬升段挂的就是这个（`skills/pick.py:762`），真机三段动作原来一行都没有。
    挂上它只为一件事：让上一轮那个**没解释的进场 stall**有观测 —— 目标
    `[0.227, 0.068, 0.084]`，实际停在 `[0.166, 0.061, -0.002]`，全程只有 2 号关节
    在动（-38.5° → -18.1°），日志里看不出「发出去的指令到底是什么」。**只加观测，
    不承诺解决。**
    """
    def trace(k, tgt, t, dur):
        if k % 40:
            return
        tgt = np.asarray(tgt, dtype=np.float64)
        print(f"      [{k:4d}] tcp={np.round(arm.tcp(), 3)} "
              f"指定={np.round(tgt, 3)} 进度={t:.1f}/{dur:.1f} "
              f"关节={np.round(arm.angles(), 1)} {_cmd(arm)} "
              f"开合={float(arm.grip_q()):+.3f}")
    return trace


def _h(a) -> np.ndarray:
    """一个三维向量的水平投影，单位化。水平分量太小就返回零向量。"""
    v = np.array([float(a[0]), float(a[1]), 0.0])
    n = float(np.linalg.norm(v))
    return v / n if n > 1e-9 else v


def _align_deg(arm, closing) -> float | None:
    """开合轴（工具 x 轴的水平投影）离目标方向还差多少度。算不出来返回 None。"""
    a, b = _h(arm.tool_x()), _h(closing)
    na, nb = float(np.linalg.norm(a)), float(np.linalg.norm(b))
    if na < 1e-6 or nb < 1e-6:
        return None
    return float(np.degrees(np.arccos(
        float(np.clip(float(a @ b) / (na * nb), -1.0, 1.0)))))


def _fold90(d: float) -> float:
    """角度差折到 [−45, 45]。方块是方的，两条侧面差 90° 等价。"""
    return float((float(d) + 45.0) % 90.0 - 45.0)


def _jaw_axis_deg(cam) -> float | None:
    """合爪轴在**画面里**的角度（度）。没描过轮廓、画幅对不上就返回 None。"""
    try:
        jaw = _jaw_shape(cam)
    except RuntimeError:
        return None
    v = np.asarray(jaw["axis_dir_px"], dtype=np.float64).reshape(-1)[:2]
    return float(np.degrees(np.arctan2(float(v[1]), float(v[0]))))


def _red_rect_deg(cam, percep) -> float | None:
    """红区剪影的最小外接旋转矩形的角度（度）。就地拍一张；量不出来返回 None。

    掩膜那条链跟 `_jaw_check` 逐字一样（同一份 HSV 区间、同一个最小面积、同一个矩形度
    门槛），不然量的是另一块红区。
    """
    if cam is None or percep is None:
        return None
    import cv2                                                  # noqa: PLC0415

    from real.perception import brown_mask, candidates           # noqa: PLC0415

    bgr = cv2.cvtColor(np.asarray(cam.shot()), cv2.COLOR_RGB2BGR)
    mask = brown_mask(bgr, percep.ranges)
    cands = [d for d in candidates(mask, percep.min_area)
             if d["rect_fill"] >= percep.fill_min]
    if not cands:
        return None
    return float(cands[0]["rect"][2])


def _box_deg_px(cam, percep) -> float | None:
    """**画面里**「方块侧面」和「合爪轴」差多少度。量不出来返回 None。

    这条为什么作数：相机和两爪在**同一个刚体**上 —— 合爪轴在画面里的角度跟臂怎么转都
    无关（`assets/camera_calibration/real_wrist_jaw_shape.json` 那几圈轮廓敢写死就是
    这个道理）。所以画面里的这个夹角**就是**世界系里开合轴离方块侧面差多少度，中间
    不过「量 yaw → 算侧面法向 → 正解 tool_x」那一串模型量 —— 那一串哪一环歪了，它都
    不会知道。

    2026-10-17 实测：画面上 27.6°（红区剪影 `ang=−63.43°`，116.7×109.6px，填充 0.895）
    vs `_align_deg` 报的 1.8°。用户先看出来的（「方块在你的画面里面都成了 45° 了」）。
    """
    a = _red_rect_deg(cam, percep)
    ax = _jaw_axis_deg(cam)
    if a is None or ax is None:
        return None
    return _fold90(a - ax)


def _yaw_from_px(sh, center, yaw, cam, percep):
    """拿画面里红区的角度把 `yaw` 纠回来。返回 `(纠过的 yaw, 画面角度, 模型角度)`。

    `estimate_pose` 给的 `yaw` 是模型量：它歪多少，`sh.normal` 算出来的侧面法向就跟着
    歪多少 —— 而转正挑哪一面、下探的落点全挂在它上面。画面这条不经过它。

    比法两边**同一个量法**才说得通：模型这边把八个角点投到画面、取凸包，再用同一个
    `minAreaRect` 量一次，跟红区那个角度对。`yaw` 由粗到细扫一遍取最贴的那个。

    量不出来（没相机 / 没红区 / 投不出来）返回 None —— 调用方按老口径走。
    """
    if cam is None or percep is None:
        return None
    import cv2                                                  # noqa: PLC0415

    a_meas = _red_rect_deg(cam, percep)
    if a_meas is None:
        return None
    ctr = np.asarray(center, dtype=np.float64)

    def _pred(y):
        pts = np.asarray(sh.silhouette_points(ctr, float(y)), dtype=np.float64)
        uv = [q for q in (_project_px(cam, p) for p in pts) if q is not None]
        if len(uv) < 4:
            return None
        hull = cv2.convexHull(np.asarray(uv, dtype=np.float32).reshape(-1, 1, 2))
        return float(cv2.minAreaRect(hull)[2])

    def _cost(y):
        m = _pred(y)
        if m is None:
            return 1e9
        # 90° 一循环，用 4θ 比才不会在折角上跳
        return 1.0 - float(np.cos(np.radians(4.0 * (m - a_meas))))

    best = float(yaw)
    # **步长和跨度都是弧度**（`yaw` 就是弧度）—— 2026-10-17 第一版写成 1.0/45.0，
    # 那是「1 弧度一步、扫 ±45 弧度」，扫了七八圈才回来，返回一个等价于原值的
    # 12.38 rad（打印出来 +709.4°）。
    for step, span in ((np.radians(1.0), np.radians(45.0)),
                       (np.radians(0.1), np.radians(1.0))):
        grid = np.arange(best - span, best + span + 1e-9, step)
        best = float(min(grid, key=_cost))
    pred = _pred(best)
    if pred is None:
        return None
    return best, float(a_meas), float(pred)


def _jaw_axis_model_deg(arm, cam):
    """**模型这边**「合爪轴在画面里的角度」：两个爪尖投到画面，连线取角。

    跟 `_jaw_axis_deg`（`real_wrist_jaw_shape.json` 里描死的那条）对一下 —— 两个都该
    说同一条线。对不上，就说明画面那条尺子拿的不是模型这条轴，`_box_deg_px` 的读数
    不能直接当「世界系里差多少度」用。
    """
    if cam is None or arm is None:
        return None
    try:
        fixed, moving = arm.tips()
    except Exception:                                           # noqa: BLE001
        return None
    a = _project_px(cam, np.asarray(fixed, dtype=np.float64))
    b = _project_px(cam, np.asarray(moving, dtype=np.float64))
    if a is None or b is None:
        return None
    d = np.asarray(b, dtype=np.float64) - np.asarray(a, dtype=np.float64)
    if float(np.linalg.norm(d)) < 1e-6:
        return None
    return float(np.degrees(np.arctan2(float(d[1]), float(d[0]))))


def _ik_free(arm, target_pos, target_quat, qpos0, free, ow=None, iters: int = 40):
    """和 `arm._ik` 解同一个位姿，但**只放 `free` 这几个关节动**，别的钉死。

    做法就是把雅可比里那几个关节的列清零、算出来的 `dq` 也把那几维清零（`arm._ik`
    的注释讲过：`mj_kinematics` 之后必须再来一次 `mj_comPos`，否则整块雅可比是零）。

    迭代次数比 `arm._ik` 的 3 次多：关节一钉死，剩下那几个要走的弧就长了。实测
    （离线，同一姿态）：只放 2+3、`ow=0` 降 20mm，3 次差 0.48mm、12 次差 0.00mm。
    """
    from so101_nexus.kinematics import ee_ik_delta_q, EE_IK_DAMPING   # noqa: PLC0415

    q = np.array(qpos0, dtype=np.float64, copy=True)
    m = np.zeros(6, dtype=bool)
    m[list(free)] = True
    w = float(arm.ow if ow is None else ow)
    for _ in range(int(iters)):
        pos, quat = arm._fk(q)
        jac = np.array(arm._jac(q), dtype=np.float64, copy=True)
        jac[:, ~m] = 0.0
        dq = ee_ik_delta_q(jac, pos, quat,
                           np.asarray(target_pos, dtype=np.float64),
                           np.asarray(target_quat, dtype=np.float64),
                           orientation_weight=w, damping=EE_IK_DAMPING)
        dq[~m] = 0.0
        q = np.clip(q + dq, arm.q_lo, arm.q_hi)
    return q


def _step_min_deg(arm, tgt, free, ow=None):
    """走到 `tgt` 这一步，**该按哪个自由关节的度数定步长**。返回 (度, 关节下标, Δz 米)。

    用 `_goto` 同一个 `_ik_free`（`free=None` 时同一个 `arm._ik`）解一遍，拿解出来的
    关节角减此刻读回来的关节角。**不是自己写的运动学** —— 只是把 `_goto` 要解的那个点
    提前解一次，好知道这一步值不值得走。`free=None` 时排除夹爪那一维（它不由 `tgt` 决定）。

    **2026-10-17 改：挑关节的尺子从「度数最大」换成「真的把 TCP 挪得最远」。**
    原来取 `argmax(|Δq|)`，在 `FREE_GAP=(0, 4)` 上被 **5 号腕转**占住 —— 而 5 号在
    下面那张实测表里对「沿缝」的贡献是 **0.00mm/度**：它转多少，爪尖都不动。于是
    「长度往上乘到某个自由关节动 2°」这条把长度乘在了一个不产生位移的关节上。
    实测（`out/` 面板日志 2026-10-17 那一趟微调）：
        算出来该走 0.28mm —— 这一步走 2.84mm（5 号舵机要动 0.28°，至少要 2.0°），方向不变
        走位（关节空间）第 1 趟：[200.3 29.7 9.8]mm → [203.1 29.9 10.2]mm
                             要动 [0.1 0. 0. 0. 0.3 0.5] 度
        走到 [200.3 29.7 9.8]mm  差 2.9mm     ← 读回来和出发时一模一样，臂一步没动
    离线复现（`_probe_free_gap.py`，同一个 `_ik_free`）：free=(0,4) 时度数几乎不随目标
    长度涨（0.28mm→0.20°、20mm→0.83°），最大的一直是 5 号，而目标 20mm 时 TCP 只挪了
    0.63mm。**换成按位移挑，挑出来的就是真走得动缝的那个关节。**
    """
    q_now = np.array(arm._ticks_to_qpos(arm.read_ticks()), dtype=np.float64)
    tgt = np.asarray(tgt, dtype=np.float64)
    if free is None:
        q_goal = arm._ik(*arm._site_pose(tgt, arm.quat()), q_now, ow=ow)
    else:
        q_goal = _ik_free(arm, *arm._site_pose(tgt, arm.quat()), q_now, free, ow=ow)
    d = np.degrees(np.abs(np.asarray(q_goal, dtype=np.float64) - q_now))
    if free is None:
        d[5] = 0.0                  # 夹爪不受 tgt 支配，不参与「够不够大」的判断
        i = int(np.argmax(d))
        return float(d[i]), i, 0.0
    # **按「只动这一个关节、TCP 挪多远」挑**（也就是实测表里那一列 mm/度乘上 Δq）。
    # 每个自由关节只多一次正解，离线，不碰串口。
    #
    # 用户 2026-10-17：「5 号舵机转爪子只会把爪子带的越来越偏，给你开放 5 号舵机是为了
    # 纠正角度偏的，**真正带来横移量的只有 1 号舵机**」。离线实测（`_probe_free_gap.py`，
    # 跑位那一刻的姿态，每 1° 的位移）：
    #     1 号  2.87mm/度   ← 唯一横移的
    #     5 号  0.16mm/度   ← 只是自转，平移≈0
    # 差 18 倍。而上面那一行原来取 `argmax(|Δq|)` —— **5 号拿 0.28°、1 号只拿 0.1°**
    # （逆解为了让姿态对上，转腕比横移更积极），于是「把长度乘到某个自由关节动 2°」
    # 这条把长度一路乘在一个 0.16mm/度 的关节上：乘到 10 倍上限也只有 0.28°、
    # 爪尖横移≈0，臂原地不动（面板日志 2026-10-17 那一趟：读回来一点没变、差 2.9mm）。
    #
    # 换成按位移挑，方向照 `_goto` 的口径取 `_sim_pose`（和 `tgt` 同一个口径）。
    _base = np.asarray(arm._sim_pose(*arm._fk(q_now))[0], dtype=np.float64)
    _best_mm, _best_deg, _best_i, _best_dz = -1.0, 0.0, int(free[0]), 0.0
    for j in free:
        _q = np.array(q_now, dtype=np.float64, copy=True)
        _q[j] = float(q_goal[j])
        _p = (np.asarray(arm._sim_pose(*arm._fk(_q))[0], dtype=np.float64) - _base)
        # **只按水平位移挑人。** 原来算的是三维长度，可 2/3 号是在竖直面里走弧的，
        # 它们一动大部分位移都在 z 上 —— 拿三维长度当分数，等于把一个「往下压」
        # 的关节当成「横着走」的关节，步长照它定，臂就一边横移一边掉。
        # 用户 2026-10-17：「你补进来的关节还在下高度，也要纳入计算」。
        _mm = float(np.linalg.norm(_p[:2]))
        if _mm > _best_mm:
            _best_mm, _best_deg, _best_i = _mm, float(d[j]), int(j)
            _best_dz = float(_p[2])
    return _best_deg, _best_i, _best_dz


def _goto(arm, goal, *, vmax, grip=-1.0, closing=None, tol=0.004,
          free=None, ow=None, tries: int | None = None) -> str:
    """走位到 `goal`。**关节空间一步到位**，不走 `core/follow.py` 那条笛卡尔的路。

    **为什么换掉笛卡尔那条。** 实测（COM10 从臂，2026-10-14，回初始位置之后走进场点
    [227, 68, 81]mm）：`follow` 每步的位移由 `POS_SCALE` 定死，逆解出来的关节增量落在
    2/3/4 号的起步死区里。把 `LAG_GAIN`/`POS_SLEW` 放开，2 号 1494→1972、3 号
    2409→1931（各转 42°）—— **手臂确实动起来了**，但最后卡在 **4 号顶到 94.4°**
    （上限 95°），还差 41.7mm。再把逆解里姿态误差的权重往下压，4 号松开、退回 66.1°，
    可 2 号 1492→1451、3 号 2411→2410 **几乎不动了** —— 每步增量又落回死区。
    五个值全 stall，一个都没到，而且压低权重会把爪子弄歪：

        ow=0.05  差 41.7mm  4 号 94.4°  爪子朝下 −0.99（垂直）
        ow=0.02  差 40.1mm  4 号 69.1°  爪子朝下 −0.953
        ow=0.01  差 34.3mm  4 号 65.5°  爪子朝下 −0.933
        ow=0.005 差 30.8mm  4 号 65.5°  爪子朝下 −0.924
        ow=0.00  差 26.9mm  4 号 66.1°  爪子朝下 −0.913（歪 24°）

    也就是说「每步挪一小段、看一步走一步」这个形状在真机上不成立。`real/move_to.py`
    开头记着同一件事，还多一条：读一次要 66ms、`follow` 一步问三次，实测 4.5 步/秒。

    **关节空间为什么行。** `real/joint_move.goto_q` 提前把轨迹算好，一路往下写
    **绝对**关节角、**中途不读**，指令单调推进，自然越过死区；收尾连发几步让舵机追平。
    `real/move_to.py`（真机第一步）和 `skills/home_real.py`（回初始位置）一直靠它到位。

    **姿态怎么保。** 目标关节角是「**保持此刻的朝向**、只解位置」得到的
    （`real/move_to.py:82` 同一写法）。此刻工具轴朝下，解完还是朝下 —— 不夹带姿态
    改变，就没有第二个矛盾。

    **默认 `grip=-1.0` = 走的时候把爪子合着。** 原来默认是 `+1.0`（张开）：第 0 段量
    行程两端要 `measure_open()` 张到底，量完就停在张着的位置，接着整个进场、纠位、转正
    都是张着爪走的 —— 而张开的爪有 55.9mm 宽（合到底 30.9mm），一路上蹭桌沿、蹭别的
    件都得算它头上。现在改成合着走，只在快贴到方块那一小段才张开（`run` 的下探那一段）。
    这条路上 `grip` 不再是「每步增量」而是**全程走完后的落点**，所以直接取行程端点：
    `>0` 张到底、`<0` 合到底、`None` 这一段不动它。

    **走不到就放大。** 每趟走完逐关节量「实际走了 ÷ 要求走了」，下一趟按这个比例的倒数
    放大指令（上限 `GAIN_MAX` 倍）。因为舵机在负载下往一个方向只走三到五成，一趟一趟重解
    同一个点补不齐 —— 原来那条「没更近就停」的判据就是被这一点骗了，见 `GAIN_MAX` 和
    下面那段注释。

    `tol`：走完读回来离 `goal` 还有多远算到了。`vmax` / `closing` 是笛卡尔那条留下的
    参数，关节空间有自己的速度（`joint_move.JVEL`），这两个现在不生效 —— 保留是为了
    不改四个调用方的签名。
    """
    from real import joint_move as jm                              # noqa: PLC0415

    goal = np.asarray(goal, dtype=np.float64)
    out = "stall"
    gain = np.ones(6)               # 逐关节的指令放大倍数；第一趟是 1，还没有实测可依
    # **放大可以关掉**（环境变量 `PICK_GAIN_MAX`，用户 2026-10-16：「下一步可不可以不放大」）。
    # 写 1 = 这一趟指令该动多少就动多少，不按实测比例放大。默认还是 `GAIN_MAX`（3）。
    # 关掉的代价：舵机带载只走三到五成，一趟到不了位、要几趟才挪过去；好处是不会猛拽。
    import os                                                   # noqa: PLC0415

    gmax = float(os.environ.get("PICK_GAIN_MAX", "") or GAIN_MAX)
    if gmax <= 1.0:
        print("      （放大关掉了：指令该动多少就动多少）")
    # **「只跑一趟」**（环境变量 `PICK_GOTO_TRIES`，用户 2026-10-16：「能不能就让机械臂只跑
    # 一下，别反复不放大」）。写 1 = 解一次、走一趟、收工，不重解、不补第二趟。
    # 代价：舵机带载欠的那一截没人补，到点会差几毫米（`REAL_GOTO_TRIES` 那一段的来历）。
    # **调用方还能按「这一次走位」单独指定**（`tries=`，用户 2026-10-16：「下探的时候不准
    # 多抖几下，只准一气呵成」「下探后调节轴偏…一步只准动一下」）—— 给 `tries=1` 的调用
    # 就是「解一次、走一趟」，不看环境变量、也不补第二趟。
    tries = (max(1, int(tries)) if tries is not None
             else max(1, int(os.environ.get("PICK_GOTO_TRIES", "") or REAL_GOTO_TRIES)))
    if tries <= 1:
        print("      （只走一趟：解一次走一趟，不重解）")
    if free is not None:
        _nm = ("shoulder_pan", "shoulder_lift", "elbow_flex", "wrist_flex", "wrist_roll")
        print("      （只放 " + "、".join(_nm[i] for i in free) + " 动，别的钉死）")
    for k in range(tries):
        q_now = arm._ticks_to_qpos(arm.read_ticks())
        # **`_ik` 收的是官方 `gripperframe` 口径的位姿，`goal` 是 TCP 口径的，先换算。**
        # 两者差 `TCP_DELTA_BODY` 那 19.9mm。不换算的话解出来的是「另一个点」，手臂老老
        # 实实走过去、也老老实实差在那儿：实测（离线，从初始位置解 [227, 68, 81]mm）
        #     不换算  差 21.7mm    关节 [-17.7 -18.5  20.5  74.1 -108.4  -8.2]
        #     换算过  差  3.4mm    关节 [-17.7 -20.2  14.5  80.  -108.4  -8.2]
        # 换算这条 `RealArm.drive` 一直在用（`real/arm.py:418`）。姿态也要给 TCP 口径的
        # —— `arm.quat()` 是，`arm._fk(q)[1]` 不是（那是 site 口径）。
        if free is None:
            q_goal = arm._ik(*arm._site_pose(goal, arm.quat()), q_now, ow=ow)
        else:
            q_goal = _ik_free(arm, *arm._site_pose(goal, arm.quat()), q_now, free, ow=ow)
        q_goal[5] = (q_now[5] if grip is None
                     else (arm.grip_hi if float(grip) > 0 else arm.grip_lo))
        # **只放大「这一趟要写下去的位移」，不动 `q_goal`。** `q_goal` 还是逆解算出来的那个
        # 点、夹爪那一维照旧取行程端点；放大的只是从此刻走到它的那一段。横向先夹到关节限位
        # 里面，免得放大把某一维推出限位（`goto_q` 不看限位，写下去就是写下去）。
        q_cmd = np.clip(q_now + (q_goal - q_now) * gain, arm.q_lo, arm.q_hi)
        q_cmd[5] = q_goal[5]
        print(f"      走位（关节空间）第 {k + 1} 趟：{np.round(arm.tcp() * 1000, 1)}mm"
              f" → {np.round(goal * 1000, 1)}mm   要动 "
              f"{np.round(np.degrees(np.abs(q_cmd - q_now)), 1)} 度")
        # **中间那几趟不要每次收尾都停 0.76 秒。** `goto_q` 的收尾是「同一个目标角连发
        # `hold` 遍，再静 `settle` 秒」，默认 8 遍 + 0.5 秒。三趟各停一次，看着就是
        # 「走一下、定住、再挪一点、又定住」—— 用户看录像的原话是「一顿一顿」。中间那几趟
        # 只补一个很小的角度，短收尾就够读准下一次的起点；**最后一趟照旧用默认值**，
        # 到点了要让舵机真正静下来再返回。
        last = k == tries - 1
        q_after = jm.goto_q(arm, q_cmd, q_from=q_now,
                            **({} if last else {"settle": 0.15, "hold": 3}))
        err = float(np.linalg.norm(goal - arm.tcp()))
        print(f"        走到 {np.round(arm.tcp() * 1000, 1)}mm  差 {err * 1000:.1f}mm"
              f"  关节 {np.round(arm.angles(), 1)}")
        # **一趟不够。** `goto_q` 收尾只是把同一个目标角连发几遍，舵机在重力负载下欠的
        # 那一截没人补：实测（COM10 从臂，2026-10-14，进场 [227, 68, 81]mm）第一趟走到
        # 差 13.0mm，读回来 3 号 16.4°、4 号 81.3°，而指令是 14.5°、80.0° —— 各欠
        # 1.9°、1.3°。从**走到的**姿态再解一次同一个点，就是让逆解把欠的那 2° 补上，
        # 一趟收敛一点，几趟内进 `tol`。
        out = "reached" if err < tol else "stall"
        if out == "reached":
            break
        # **量这一趟的响应比，给下一趟放大用。** 换掉的是原来那条「这趟没比上趟更近，就不
        # 再解下一趟」的判据。那条判据的来历是真的（run 52 微调第 3 步：4.4 → 7.4 → 10.2mm，
        # 越解越远），可它把因果搞反了 —— **越解越远是因为每趟都只走掉一小半**，不是因为
        # 「再解没用」。run 69 抬高度那一步（`out/run_real_69.log` 第 58~64 行）就是这么死的：
        # 指令要把 z 从 −0.8mm 抬到 +0.8mm，第 1 趟差 4.2mm、第 2 趟差 7.4mm，判据当场判死刑。
        want = q_cmd - q_now
        got = np.asarray(q_after, dtype=np.float64) - q_now
        ratio = np.divide(got, want, out=np.ones(6), where=np.abs(want) > 1e-12)
        # **走反了就不放大。** 响应比 ≤ 0 说明这一趟压根没朝指令方向走（重力、摩擦、
        # 别的关节的机械耦合盖过去了）—— 这时候「跟到几成」这个信息**不存在**，取倒数会
        # 给出负值或者二十倍，夹到上限就成了「你越不听话我放大得越狠」。`out/run_real_70.log`
        # 抬高度那一步（第 59~69 行）就是这么甩起来的：−2.2 → −3.2 → −4.0 → **+1.9**，
        # 最后一趟 3 号被顶到 7.4°、冲过目标 1.9mm。**前三趟走反、第三趟猛冲**，两个毛病
        # 是同一个：放大用在了测量不支持它的那一档上。
        ratio[(ratio <= 0.0) | (np.abs(want) <= np.radians(GAIN_MIN_ASK_DEG))] = 1.0
        # 上限夹到 1.0：走得比指令多（从没见过）不反过来缩，没见过的情形不猜。
        ratio = np.clip(ratio, 1.0 / gmax, 1.0)
        ratio[5] = 1.0                  # 夹爪那一维是行程端点，不是「走不到」，不参与
        gain = 1.0 / ratio
        amp = " ".join(f"{j + 1}号×{gain[j]:.1f}"
                       for j in range(6) if gain[j] > 1.01)
        if amp and not last:            # 已经是最后一趟就没有「下一趟」了，别打下去了
            print(f"        ↻ 下一趟按实测放大：{amp}")
    # **`_settle` 不叫了。** 它原来是给笛卡尔那条路收残余速度用的（`follow` 到点是
    # 「离得够近了」就返回，那一刻手臂还在动）。关节空间这条路返回时舵机已经静了
    # （`goto_q` 自己的 `hold` + `settle`），再守 40 步就是白站 3.5 秒 —— 一次 `_goto`
    # 一步没多走，光站在那儿。`grip` 也已经由 `q_goal[5]` 直接走到行程端点了。
    # `_grip_cmd` 是**增量**那一维的状态（`drive` 攒它、`_close_until_stall` 从它出发），
    # 刚才那几趟没经过 `drive`，从读数把它对回来，免得下一步从错的地方开始攒。
    arm._grip_cmd = float(arm.grip_q())
    return out


def _declared_half(yaw, axis_xy) -> float | None:
    """配置里申报的那些东西，沿开合轴鼓出多少（米）。一件都取不到就 None。

    和 `sh.support` 同一个口径（斜着放的方块比半边长宽），只是把来源从「画面估出来的
    形状」换成「配置 `objects:` 里申报的那一行」。**取所有申报件里最大的那个** ——
    单目标场景里就是那件；万一配置写了好几行，取大也还是危险的那一侧。
    """
    best: float | None = None
    for spec in geom.object_specs():
        try:
            h = float(shapes.from_spec(spec).support(yaw, axis_xy))
        except Exception:                                        # noqa: BLE001
            continue
        best = h if best is None else max(best, h)
    return best


def _vertical(quat, x_des=None) -> tuple[np.ndarray, float]:
    """把一个 TCP 口径的朝向摆正成「工具 z 轴朝下」，开合轴（工具 x）尽量保住。

    返回 (摆正后的四元数, 原朝向离垂直差多少度)。做法：工具 z 钉成 (0,0,−1)，工具 x
    投影到水平面当新的 x，y = z × x。

    给了 `x_des`（要贴着的那条侧面法向）就**连方位角一起纠到它**，不再保留原来那个。
    仿真那支就是这么干的：`skills/pick.py:702` 的下探把 `closing=closing` 传给
    `follow`，整段下探都在往目标法向上拧。真机原来没传，方位角是转正那一刻继承的
    ——`run_real_24` 第 1 趟继承的就是转正剩下的 13.7°，一路带进合爪。
    """
    from scipy.spatial.transform import Rotation                # noqa: PLC0415

    q = np.asarray(quat, dtype=np.float64)
    R = Rotation.from_quat([q[1], q[2], q[3], q[0]]).as_matrix()   # scipy 吃 xyzw
    down = np.array([0.0, 0.0, -1.0])
    off = float(np.degrees(np.arccos(np.clip(float(R[:, 2] @ down), -1.0, 1.0))))
    x = R[:, 0] - float(R[:, 0] @ down) * down
    if float(np.linalg.norm(x)) < 1e-6:        # 开合轴本来竖直：换 y 轴来投
        x = R[:, 1] - float(R[:, 1] @ down) * down
    n = float(np.linalg.norm(x))
    x = x / n if n > 1e-9 else np.array([1.0, 0.0, 0.0])
    if x_des is not None:
        xd = np.asarray(x_des, dtype=np.float64) - float(
            np.asarray(x_des, dtype=np.float64) @ down) * down
        nd = float(np.linalg.norm(xd))
        if nd > 1e-6:
            xd = xd / nd
            if float(xd @ x) < 0.0:            # 开合轴没有正负，取跟现在同侧的那一头
                xd = -xd
            x = xd
    out = Rotation.from_matrix(np.column_stack([x, np.cross(down, x), down])).as_quat()
    return np.array([out[3], out[0], out[1], out[2]]), off


def _descend(arm, xy, z_top, z_bot, *, closing=None, open_at=0.5, step=DESCEND_STEP,
             tol=0.004) -> tuple[str, np.ndarray]:
    """从 `z_top` 垂直降到 `z_bot`：整根柱子上每一点都对准同一个 `xy`、同一个朝向。

    **为什么不是「一边降一边对准」。** 那正是 `core/follow.py` 那条笛卡尔路在做的事，
    它在真机上输了。实测（`out/run_real_18.log`）指令 x 从头到尾都是 0.239，实际 TCP
    从 237 滑到 204 —— 「每一步都纠」纠不动：一步只纠 1.5mm，而 2 号肩在那段时间里
    自己从 −0.8° 沉到 +8.4°。根子不是纠得不勤，是**每一步都在拿新姿态重解一次逆解**：
    同一个位置，种子姿态变一点、六个关节就重新分一遍，4 号被顶到 94.8°（上限 95°），
    多出来的误差只好由肩去扛。

    **这一支先把整列解好、再一口气走完。** 每一点拿**上一个点的解**当种子（相邻两点
    只差 5mm，解不会跳），走的过程中**不读、不解**，所以肩没有「自己沉」的机会。

    **朝向锁的是「竖直 + 目标侧面法向」，不是「此刻的朝向」。** 竖直这一半是实测逼出来的。
    方位角那一半照仿真：`skills/pick.py:702` 把 `closing=closing` 传进 `follow`，整段
    下探都在往目标法向上拧，转正剩下的残差到合爪时已经被抹平。真机原来只锁竖直，
    方位角是转正那一刻继承的（`run_real_24` 第 1 趟继承 13.7°）。`_align`（转正）
    那 200 步是笛卡尔守位，肩会被姿态目标拖着往上抬，而肩一抬工具轴就跟着歪 ——
    同一个纠位姿态把 2 号一路抬上去，正解出来的工具 z 轴朝下分量：

        2号 −11.8° → −0.979（歪 12°）    +10° → −0.985     +30° → −0.867（歪 30°）

    实测（`out/run_real_19.log` 第 1 趟）下探解到底那点 `[−6.9 42.8 −36.3 95.0 −63.2]`，
    4 号钉在 **95.0° 限位**上，正解出来离目标 **33.9mm** —— 手臂照做，走完读回来
    `[−6.4 43.2 −33.9 94.8 ...]` 正解 `[251.6 30.9 −10.1]mm`，跟日志报的一模一样，
    说明舵机没欠账，是**那个点本身就够不着**。拿同一列换六个种子重解，收敛到同一个
    钉限位的解，也说明不是种子的问题，是**锁了一个歪的朝向**。
    钉竖直之后同一列再解：底点 4 号 51.2°、离限位 43.8°、残差 0.01mm。

    开合度沿柱子线性过渡：`open_at` 之前合到底、之后渐变到张到底。放进同一条柱子里是
    为了让样条连续；单独切一刀会在那儿留个跳变。

    和 `_goto` 一样解 `REAL_GOTO_TRIES` 趟：舵机在重力负载下停在指令角之前（实测 3 号
    欠 1.9°、4 号欠 1.3°），从**走到的**姿态重解整列能把这一截补回来一点。
    """
    from real import joint_move as jm                              # noqa: PLC0415

    xy = np.asarray(xy, dtype=np.float64).reshape(2)
    q_before = arm.quat()                  # TCP 口径；`_site_pose` 会换算成官方口径
    quat0, off = _vertical(q_before, closing)
    if closing is not None:
        from scipy.spatial.transform import Rotation            # noqa: PLC0415
        R0 = Rotation.from_quat([q_before[1], q_before[2], q_before[3],
                                 q_before[0]]).as_matrix()
        R1 = Rotation.from_quat([quat0[1], quat0[2], quat0[3],
                                 quat0[0]]).as_matrix()
        a = R0[:, 0] - float(R0[:, 0] @ np.array([0.0, 0.0, -1.0])) * np.array([0.0, 0.0, -1.0])
        b = R1[:, 0] - float(R1[:, 0] @ np.array([0.0, 0.0, -1.0])) * np.array([0.0, 0.0, -1.0])
        na, nb = float(np.linalg.norm(a)), float(np.linalg.norm(b))
        az = (float(np.degrees(np.arccos(np.clip(float(a @ b) / (na * nb), -1.0, 1.0))))
              if na > 1e-6 and nb > 1e-6 else 0.0)
        print(f"      进柱子那一刻的朝向离垂直 {off:.1f}°，方位角比目标侧面法向差 "
              f"{az:.1f}° —— 两个都锁到目标法向上")
    else:
        print(f"      进柱子那一刻的朝向离垂直 {off:.1f}° —— 按「工具 z 轴朝下」锁，"
              f"不锁它")
    goal_bot = np.array([xy[0], xy[1], float(z_bot)])
    g_lo, g_hi = float(arm.grip_lo), float(arm.grip_hi)
    ramp = max(1.0 - float(open_at), 1e-6)      # `open_at` 之后到终点的那一段
    span = abs(float(z_top) - float(z_bot))
    n = max(int(round(span / step)), 1) + 1
    out = "stall"
    for k in range(REAL_GOTO_TRIES):
        # 第一个点是**此刻的**姿态：样条从真身所在的地方起，不是从空中某个点起。
        q0 = arm._ticks_to_qpos(arm.read_ticks())
        q0[5] = g_lo
        q_list = [q0]
        q_seed, hop, worst = q0, 0.0, 0.0
        for i in range(n):
            f = i / (n - 1.0)
            z = float(z_top) + (float(z_bot) - float(z_top)) * f
            goal = np.array([xy[0], xy[1], z])
            q = arm._ik(*arm._site_pose(goal, quat0), q_seed)
            q[5] = (g_lo if f <= open_at
                    else g_lo + (g_hi - g_lo) * min((f - open_at) / ramp, 1.0))
            hop = max(hop, float(np.max(np.abs(np.degrees(q[:5] - q_seed[:5])))))
            # **先看这一列自己解到哪儿了。** 解出来够不着就别走 —— 上一趟就是在这种
            # 列上把臂开过去的（到底那点残差 33.9mm）。
            got = arm._sim_pose(*arm._fk(q))[0]
            worst = max(worst, float(np.linalg.norm(got - goal)))
            q_list.append(q)
            q_seed = q
        print(f"      下探（关节空间）第 {k + 1} 趟：{n} 个点，相邻两点最多差 "
              f"{hop:.1f} 度，逆解自己最大欠 {worst * 1000:.1f}mm；"
              f"到底那点解成 {np.round(np.degrees(q_seed), 1)}")
        if worst > tol:
            print(f"        ✗ 这条列解不到：最大欠 {worst * 1000:.1f}mm，不走")
            return "stall", arm.tcp()
        # 中间那几趟短收尾，最后一趟照旧 —— 理由和 `_goto` 同。
        last = k == REAL_GOTO_TRIES - 1
        jm.goto_path(arm, q_list,
                     **({} if last else {"settle": 0.15, "hold": 3}))
        tcp = arm.tcp()
        err = float(np.linalg.norm(goal_bot - tcp))
        print(f"        走到 {np.round(tcp * 1000, 1)}mm  差 {err * 1000:.1f}mm"
              f"  关节 {np.round(arm.angles(), 1)}")
        out = "reached" if err < tol else "stall"
        if out == "reached":
            break
    arm._grip_cmd = float(arm.grip_q())
    return out, arm.tcp()


def _wrist(cams):
    """腕部相机那一路：名字里带 `wrist` 的那个。"""
    return next((c for n, c in (cams or {}).items() if "wrist" in n), None)


def _view_radius(cams, z_plane: float):
    """腕相机这一刻在 `z_plane` 那个水平面上能看清多大一圈 —— 内切圆半径（米）。

    把画面中心和四条边的中点打回 `z_plane`，取中心到最近那条边的距离。**这是「前后左右
    该挪多远」的尺子**：机位挪 r，原本贴在画面边上的东西正好落到画面正中。算不出来
    返回 None。内参和位姿都现读，写死一个数没意义。

    只读 `mount()` / `size()`，两样 `RealWristCamera` 都有。
    """
    cam = _wrist(cams)
    mount = cam.mount() if cam is not None else None
    if mount is None:
        return None
    w, h = cam.size()
    k = vision.intrinsics(mount["fovy"], w, h)
    cx, cy = k[2], k[3]
    c0 = vision.backproject(mount["pos"], mount["mat"], k, cx, cy, z_plane)
    if c0 is None:
        return None
    rs = []
    for u, v in ((0.0, cy), (w - 1.0, cy), (cx, 0.0), (cx, h - 1.0)):
        p = vision.backproject(mount["pos"], mount["mat"], k, u, v, z_plane)
        if p is not None:
            rs.append(float(np.linalg.norm(p[:2] - c0[:2])))
    return min(rs) if rs else None


def _jaw_shape(cam=None) -> dict:
    """读 `_trace_jaw.py` 描好的爪子轮廓。没有、或者画幅对不上就当场抛。

    **画幅对不上不许凑合**。那几圈是在某一路相机的某个分辨率上点的像素，换一路、
    换分辨率之后再拿它去量「爪子离目标多远」，量的是别的东西。
    """
    import json                                                 # noqa: PLC0415

    # 相机自己能报就听它的。**真机这一路没有这个函数**，走下面那份描好的 JSON；
    # 留这个口子是为了不把「相机自己会算」的那类实现堵死。
    f = getattr(cam, "jaw_shape", None)
    if f is not None:
        return f()
    if not JAW_SHAPE_JSON.exists():
        raise RuntimeError(
            f"没有 {JAW_SHAPE_JSON} —— 机械爪在腕相机画面里的轮廓没描过。跑 "
            "`G:/anaconda/envs/sim2real/python.exe _trace_jaw.py "
            "--img out/jaw_frame.jpg` 描一次。")
    d = json.loads(JAW_SHAPE_JSON.read_text(encoding="utf-8"))
    if cam is not None:
        w, h = (int(v) for v in cam.size())
        if [int(v) for v in d.get("image_size", ())] != [w, h]:
            raise RuntimeError(
                f"{JAW_SHAPE_JSON} 里那三圈是在 {d.get('image_size')} 的画面上描的，"
                f"此刻这一路是 {[w, h]} —— 对不上，重新描一次。")
    return d


def _contour_pts(cnt, step_px: float = 2.0) -> np.ndarray:
    """把轮廓折线按 ≤`step_px` 的间隔重采样成点列（连收口那条边一起）。

    **不能直接拿轮廓顶点去量距离。** `real/perception.py` 那边用的是
    `CHAIN_APPROX_SIMPLE`，一条直边只留两个端点 —— 拿顶点量出来的「离爪子多远」其实只
    量了四个角点，边中间那一截（方块在画面里基本全是直边）全漏掉。
    """
    p = np.asarray(cnt, dtype=np.float64).reshape(-1, 2)
    if len(p) < 2:
        return p
    p = np.vstack([p, p[:1]])
    out = [p[0]]
    for a, b in zip(p, p[1:]):
        n = max(1, int(np.ceil(float(np.linalg.norm(b - a)) / step_px)))
        out.extend(a + (b - a) * (k / n) for k in range(1, n + 1))
    return np.asarray(out, dtype=np.float64)


def _gap_px(poly, pts_uv) -> tuple[float, np.ndarray]:
    """红区轮廓那一串点里**最靠里**的那一点，到某一圈爪子轮廓的**带号**距离（像素）。

    **符号跟 `cv2.pointPolygonTest` 一致**：正 = 红区那一点落在爪子轮廓**里面**（压上了），
    负 = 落在外面（留了缝）。这里是「拿红区上的点去问爪子」，**别记串**。
    `_set_clearance` 用的是取负之后的那个数（「离爪子外面多少像素」，越大越好）。

    **取的是最大值，不是最小值。** 判「有没有接触」要看**最靠里的那一个红点**，所以比的是
    谁更靠里（带号值更大）。取最小值拿到的是**离爪子最远**的那个点，等于一直在看方块另一
    边 —— 2026-10-15 就是这么漏掉的：`out/real_37_preclose_f82.jpg` 上真正最近的红点是
    (1063,414)、离轮廓 0.7 像素（贴上了），这段代码报的是 81 像素「缝很宽」，判据过关、
    微调也没被触发。
    """
    import cv2                                                  # noqa: PLC0415

    best: tuple[float, np.ndarray] | None = None
    for p in pts_uv:
        d = float(cv2.pointPolygonTest(poly, (float(p[0]), float(p[1])), True))
        if best is None or d > best[0]:
            best = (d, np.asarray(p, dtype=np.float64))
    return best if best is not None else (float("nan"), np.zeros(2))


def _exit_px(polys, pts_uv, u) -> float:
    """沿 `u` 把红区整体推开，推多少像素才**一个红点都不剩在爪子轮廓里**。

    返回 0 = 现在就没有红点压在轮廓里。`_gap_px` 量的是「**最近的那一个点**」的距离，
    方块大半压在轮廓里时它给不出「退出去还要多少」：实测（`out/clear_step.json` 第一眼）
    红区最深只压进 0.7 像素，那条尺子就只要求横移 8.7 像素，而按
    `assets/camera_calibration/real_wrist_jaw_shape.json` 的几何，要让整块红区离开
    爪轮廓（占 x 1023~1106）得挪 60~85 像素。用户 2026-10-16 的原话是「把爪子轮廓
    完整移出去」—— 这个函数就是补那一半的尺子。

    `u` 取单位向量（这里是合爪轴方向）。二分：单调沿一个方向平移，块离开轮廓之后
    不会再压回去（轮廓是楔形、没有把方块包住的凹口）。
    """
    import cv2                                                  # noqa: PLC0415

    u = np.asarray(u, dtype=np.float64).reshape(2)
    pts = np.asarray(pts_uv, dtype=np.float64).reshape(-1, 2)
    polys = [np.asarray(p, dtype=np.float32).reshape(-1, 1, 2) for p in polys]
    if pts.size == 0 or not polys:
        return 0.0

    def clean(t: float) -> bool:
        q = pts + float(t) * u
        for poly in polys:
            for p in q:
                if cv2.pointPolygonTest(poly, (float(p[0]), float(p[1])), False) > 0:
                    return False
        return True

    if clean(0.0):
        return 0.0
    lo, hi = 0.0, 256.0
    while hi < 1.0e6 and not clean(hi):
        lo, hi = hi, hi * 2.0
    for _ in range(22):
        mid = 0.5 * (lo + hi)
        if clean(mid):
            hi = mid
        else:
            lo = mid
    return float(hi)


def _box_half_m(percep) -> float:
    """方块**半个边长**（米），给「缝不够时一步至少走半个边长」那条下限用。

    从感知那份清单里取：**优先用「往下真正在用的那一份」**（`percep.spec_used` ——
    2026-10-17 用户定：画面估出来过就用估出来的，估不出来感知那边才退回配置那一行，
    两者它在 `locate` 里并排打出来了）。再按形状取长度：`cube` 用 `side_mm`，`box` 用
    `size_mm` 三个全长里最长的那个，`cylinder` 用 `diameter_mm` / `height_mm` 里大的那个
    （跟 `box` 同一个口径 —— 「取大的那一维」是安全的那个方向）。取不到就退回 18mm。

    **改这里之前先想清楚**：原来这一段明写「不用画面估出来的那一份」，理由是下限只是
    「别挪一眼几乎不动」、估小了也只是步子小一点。但同一份值也喂给 `_place_real` 当
    「方块下底面」算松爪高度，那一处估小了是要命的（松爪时方块已经贴桌面）。所以改成
    跟其余落点算式同一个来源。
    """
    spec = (getattr(percep, "spec_used", None)
            or getattr(percep, "spec", None) or {})
    v = spec.get("side_mm")
    if v is None:
        # `box` 给三个全长；`cylinder` 给直径和高。两种都是「几个长度里取最大的那个」。
        # **2026-10-17 补的圆柱一支**：原来只认 `side_mm` / `size_mm`，圆柱那两行
        # (`diameter_mm` / `height_mm`) 一个都读不到，直接退到 18mm —— 直径 40 的圆柱
        # 会被当成 18mm 的小方块算半个身位。
        sz = spec.get("size_mm")
        if sz is None and spec.get("diameter_mm") is not None:
            sz = [x for x in (spec.get("diameter_mm"), spec.get("height_mm"))
                  if x is not None]
        v = max(float(x) for x in sz) if sz else 18.0
    return 0.5 * float(v) / 1000.0


def _gap_want_px() -> float:
    """沿合爪轴那一步的**目标**（像素）。带开着取带中值；关掉就是老的单边门槛。"""
    if CLEAR_BAND_ON:
        return 0.5 * (CLEAR_BAND_LO_PX + CLEAR_BAND_HI_PX)
    return CLEAR_TARGET_PX


def _gap_ok(gap_px: float) -> bool:
    """这一眼的缝算不算过。带开着要落在 `[LO, HI]` 里；关掉还是老的「≥ 门槛」。"""
    if CLEAR_BAND_ON:
        return bool(CLEAR_BAND_LO_PX <= float(gap_px) <= CLEAR_BAND_HI_PX)
    return bool(float(gap_px) >= CLEAR_TARGET_PX)


def _gap_need_px(gap_px: float, gap_exit_px: float) -> float:
    """沿合爪轴还差多少像素、往哪边（**带号**：正 = 沿合爪轴推出去，负 = 把方块拉回来）。

    **带开着的时候两头都管**（用户 2026-10-16：「必须要把目标放在两个爪子中间」）：
      · 缝 > `CLEAR_BAND_HI_PX` → 方块退出两爪了，返回负值 —— 这是原来那条单边门槛
        漏掉的一半，`out/run_real_89.log` 末态缝 +46 像素就是这么判过、然后空抓的；
      · 缝 < `CLEAR_BAND_LO_PX` → 压上了，返回正值；**还要跟「整块退出去」那条取大的**
        （`_exit_px` 量的是「推开多少像素才一个红点都不剩在爪轮廓里」，压得深时它更大）；
      · 落在带里 → 0，这一维不用动，去对轴。
    """
    g = float(gap_px)
    if not CLEAR_BAND_ON:
        return max(float(gap_exit_px), CLEAR_TARGET_PX - g)
    if g > CLEAR_BAND_HI_PX:
        return _gap_want_px() - g
    if g < CLEAR_BAND_LO_PX:
        return max(float(gap_exit_px), CLEAR_BAND_LO_PX - g)
    return 0.0


def _gap_leaving(need_px: float) -> bool:
    """这一步算不算「缝」那一段（该走沿合爪轴这条、还是去对轴）。

    带开着时**两头都算** —— 退出去和压上来都是「缝」那一段。关掉时还是老口径：只有
    「还差多少推出去」为正才算，负值（方块已经退出去了）掉进对轴那一段。
    """
    if CLEAR_BAND_ON:
        return abs(float(need_px)) > CLEAR_EXIT_EPS_PX
    return float(need_px) > CLEAR_EXIT_EPS_PX


def _gap_axis_px(polys, pts_uv, u) -> float:
    """**沿合爪轴 `u` 看**，爪子轮廓和红区之间还剩多少像素净空。负 = 沿这条轴压在一起。

    `_gap_px` 量的是「红区里最靠里的那一点到爪轮廓的**最近**距离」—— 方向不限。爪子跑到
    方块**上方**（不在合爪轴那一侧）时，最近的那一点是**上边**那一段，它会报一个正的
    「缝」，而沿合爪轴（该留缝的那一侧）其实一点缝都没有。用户 2026-10-16 的原话：
    「爪子根本没到位置，它在图像上部，并没有到方块的右边制造缝隙，你检测的留出的缝隙是在
    上面的缝隙是错误的」。

    所以这里把两个点集都投到 `u` 上，看两段区间**沿这条轴**离多远：
    不相交 = 净空（正），相交 = 压进深度（负）。`u` 取合爪轴方向（`axis_dir_px`）。
    """
    u = np.asarray(u, dtype=np.float64).reshape(2)
    u = u / max(float(np.linalg.norm(u)), 1e-12)
    pts = np.asarray(pts_uv, dtype=np.float64).reshape(-1, 2)
    if pts.size == 0 or not polys:
        return float("nan")
    q = np.concatenate([np.asarray(p, dtype=np.float64).reshape(-1, 2) for p in polys],
                       axis=0)
    r0, r1 = float((pts @ u).min()), float((pts @ u).max())
    j0, j1 = float((q @ u).min()), float((q @ u).max())
    if r1 < j0:
        return j0 - r1
    if j1 < r0:
        return r0 - j1
    return -min(r1 - j0, j1 - r0)


# `_box_center_px` 拿哪个通道分「顶面亮 / 正面暗」。
#   `"v"` = HSV 的亮度（= 每像素 R/G/B 里最大的那个）：**与颜色无关**，绿块蓝块一样用。
#   `"r"` = BGR 的红通道（老口径，2026-10-15 那一版）：只在红块上验过。红块拿它、
#           与非红背景比，对比度比 V 大（V 会把非红背景的其它通道也算进来）。
# **2026-10-17 用户定：默认换成 `"v"`**，理由是「换个颜色的方块还能抓吗」那一问 ——
# R 通道对绿块/蓝块基本是「没有信号」，Otsu 会把噪声劈成两半。**红块那一趟是这个通道
# 换过之后还没在真机上跑过**，要回退把这一行改回 `"r"` 就行，下面两条分支都在。
BOX_CENTER_CHAN = "v"


def _box_center_px(cnt, bgr=None) -> np.ndarray | None:
    """方块**顶面**（用户说的「目标那个面」）中心在画面里那一个像素。

    **不能拿整块的重心。** 相机是斜着往下看的，剪影是「顶面四边形 + 正面那一条下沿」，
    重心被正面整个往下拽（`out/jaw_raw.jpg` 这一帧：重心 (1047,463)，顶面中心 (1050,441)）。

    **不能靠剪影的角去凑。** 2026-10-15 试过「凸包 → 剔共线 → 去掉最下面两个角」：
    · 凸包给 19 个点，而剔共线那个循环的停止条件写的是「剩 4 个」不是「没有共线点了」，
      于是它把顶沿一带的点剔到只剩 4 个就停，接着「去掉 y 最大的两个」去掉的是两个
      **顶面**的角，报 (1051.5, 394.5)；
    · 就算循环改对了，这办法也够不着真值：顶面的前沿左角 T4 **不是剪影的极值点**，
      它落在左边那条直线上，任何「取剪影的角」的规则都看不见它。
    旧版（`approxPolyDP` 按 y 取最上面四个）在这一帧取到的是 T1、T2、**爪左边缘压上顶沿
    的交点**、**爪尖切出来的凹口**，报 (1034,399)，跟真值差 42 像素（`out/run_real_63.log`）。

    **改用亮暗。** （2026-10-15 那版用的是「它自己的颜色」= BGR 的红通道，2026-10-17 换成
    V 通道，换的理由和回退办法见 `BOX_CENTER_CHAN`；下面那两个峰的数字是**红通道**下量的，
    V 通道下峰位会变、结论不变。）顶面朝上受光、正面背光 —— 这一帧红区里 R 通道是两个清清楚楚的
    峰：正面 ≈120（1900 像素）、顶面 ≈180（2000 像素），中间 130~139 只有 300 来个像素的
    谷。顶面 = 红区里亮的那一半，两半的**分界线就是前沿那条棱**（用户量的那条：列 x=1050
    上亮暗交界在 y≈492）。亮块取**凸包** —— 爪尖压出来的凹口被凸包自然补回来 —— 剩下
    3~4 个角就是顶面的角，均值即中心。

    **假设**：盒子顶面和正面亮度分得开（受光方向固定就该如此）。分不干净（亮块太小 /
    简化后不是 3~4 个角）返回 `None`，不猜。
    """
    import cv2                                                  # noqa: PLC0415

    p = np.asarray(cnt, dtype=np.float32).reshape(-1, 1, 2)
    if len(p) < 4 or bgr is None:
        return None
    h, w = bgr.shape[:2]
    full = np.zeros((h, w), np.uint8)
    cv2.drawContours(full, [p.astype(np.int32)], -1, 255, -1)
    area0 = int((full > 0).sum())
    if area0 < 50:
        return None
    # 亮暗分界用 Otsu 现算，不写死阈值 —— 光照变了自己跟着变。
    # 用哪个通道见 `BOX_CENTER_CHAN`：默认 V（HSV 亮度，与颜色无关），换回红通道也在这里。
    if BOX_CENTER_CHAN == "r":
        ch = bgr[:, :, 2]
    else:
        ch = cv2.cvtColor(bgr, cv2.COLOR_BGR2HSV)[:, :, 2]
    t, _ = cv2.threshold(ch[full > 0].reshape(-1, 1), 0, 255,
                         cv2.THRESH_BINARY + cv2.THRESH_OTSU)
    top = np.zeros((h, w), np.uint8)
    top[(full > 0) & (ch >= float(t))] = 255
    # 亮的可能不止一块（反光、桌面上的红别的东西）；取最大那块。
    n, lab, stats, _ = cv2.connectedComponentsWithStats(top, 8)
    if n <= 1:
        return None
    k = 1 + int(np.argmax(stats[1:, cv2.CC_STAT_AREA]))
    if int(stats[k, cv2.CC_STAT_AREA]) < 0.15 * area0:
        return None
    one = np.zeros((h, w), np.uint8)
    one[lab == k] = 255
    cs, _ = cv2.findContours(one, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if not cs:
        return None
    hull = cv2.convexHull(max(cs, key=cv2.contourArea))
    per = float(cv2.arcLength(hull, True))
    if per < 1.0:
        return None
    ap = None
    for f in (0.02, 0.03, 0.045, 0.06):        # 容差逐级放大，直到简化出 3~4 个角
        c = cv2.approxPolyDP(hull, f * per, True).reshape(-1, 2).astype(np.float64)
        if len(c) == 4:
            return c.mean(axis=0)
        if len(c) == 3:
            ap = c
            break
    if ap is None:
        return None
    # 只认出三个角：顶面在画面里是平行四边形，缺的那个 = A + C - B。哪一对是**对角**
    # 不靠顺序定 —— 把三种配法都补一遍，补出来的点**落在红区里**的那一对才是对角
    # （另外两种配法补出来的点会跑到方块外面去）。中心 = 对角的中点。
    best: tuple[float, np.ndarray] | None = None
    for i in range(3):
        a, b, cc = ap[i], ap[(i + 1) % 3], ap[(i + 2) % 3]
        d = a + cc - b
        if cv2.pointPolygonTest(np.asarray(cnt).reshape(-1, 1, 2).astype(np.int32),
                                (float(d[0]), float(d[1])), False) < 0:
            continue
        span = float(np.linalg.norm(a - cc))
        if best is None or span > best[0]:
            best = (span, (a + cc) / 2.0)
    return None if best is None else best[1]


def _put_lines(img, lines, col=(0, 255, 255), bottom: bool = False) -> None:
    """在画幅左上角（`bottom=True` 时左下角）写几行 ASCII，**字号按最长那行现算**。

    `cv2.putText` 不认中文，所以这里只有 ASCII。原来每个拦门的地方都写死 0.85：
    `tries 4   gap +61px (want 20..75 = between jaws)   axis -43px (tol 35)   along +119
    (pixel ruler: reference only, NOT the gate)` 那一行比 1920 还宽，右边的字被切在画外。
    用户 2026-10-17：「字搞的大一点」。

    现算 = 拿最长那行在 1.0 号下的实测宽度抬到「两边各留 16px」为止，再卡在 [0.8, 1.6]。
    行距跟着字号走，行多了不会叠在一起。

    `bottom=True` 是给 `_jaw_check` 用的：它先往 `jaw_check.jpg` 上写一段，`_confirm_step`
    再读同一张图、往**顶上**写自己的几行 —— 两段都在顶上就压在一起了。
    """
    import cv2                                                    # noqa: PLC0415

    if not lines:
        return
    (_tw, _th), _ = cv2.getTextSize(max(lines, key=len), cv2.FONT_HERSHEY_SIMPLEX, 1.0, 2)
    sc = min(1.6, max(0.8, (float(img.shape[1]) - 32.0) / max(float(_tw), 1.0)))
    dy = int(round(float(_th) * sc * 1.5)) + 10
    y0 = int(img.shape[0]) - 24 - dy * (len(lines) - 1) if bottom else 34
    for i, txt in enumerate(lines):
        org = (16, y0 + dy * i)
        cv2.putText(img, txt, org, cv2.FONT_HERSHEY_SIMPLEX, sc, (0, 0, 0), 6, cv2.LINE_AA)
        cv2.putText(img, txt, org, cv2.FONT_HERSHEY_SIMPLEX, sc, col, 2, cv2.LINE_AA)


def _jaw_check(cam, percep, arm, tag: str, axis_only: bool = False) -> dict:
    """合爪前那一眼：红区离**整圈爪子轮廓**多少像素、目标中心离合爪轴多少像素。只读。

    · `gap`：`real/perception.py` 选中的那块红区的轮廓里**最靠里的那一个点**，到描好的爪子
      轮廓（`fixed_jaw` 必有，`moving_closed` 描了就算）的带号距离，取负值 ——
      **正 = 整块红区都在爪子外面（留了缝），负 = 有红像素探进爪子里（接触了）**。
      **哪一圈被探得最狠就报哪一圈** —— 压上去的可能是固定爪，也可能是动爪合过来那一下
      落的地方。
    · `axis`：**方块顶面中心**（`_box_center_px`，不是整块重心）离合爪轴
      （`_trace_jaw.py` 拉的那条线）的带号垂直距离。正负只表示在轴的哪一侧。
    · `along`：同一个重心沿轴的方向走了多远（打印出来给人看，不参与判据）。

    量不出来（没有够格的红区 / 轮廓的文件不在 / 画幅对不上）返回 `{'ok': False,
    'why': ...}` —— 调用方按「这一趟判失败」办，不再像原来那样「量不了也照常合爪」。
    """
    import cv2                                                  # noqa: PLC0415

    from real.perception import brown_mask, candidates           # noqa: PLC0415

    if cam is None:
        return {"ok": False, "why": "没有腕相机这一路"}
    try:
        jaw = _jaw_shape(cam)
    except RuntimeError as e:
        return {"ok": False, "why": str(e)}

    rgb = np.asarray(cam.shot())
    bgr = cv2.cvtColor(rgb, cv2.COLOR_RGB2BGR)
    cv2.imwrite(str(JAW_RAW_IMG), bgr)          # 画之前先留一张干净的，离线复算用
    # 掩膜口径跟感知那条链必须一样（同一份 HSV 区间、同一个最小面积、同一个矩形度门槛），
    # 不然量的是「另一块红区」。
    mask = brown_mask(bgr, percep.ranges)
    cands = [d for d in candidates(mask, percep.min_area)
             if d["rect_fill"] >= percep.fill_min]
    if not cands:
        cv2.imwrite(str(JAW_CHECK_IMG), bgr)
        return {"ok": False, "why": "画面里没有过得去的红区"}

    cnt = cands[0]["contour"]
    pts = _contour_pts(cnt)
    polys = {k: np.asarray(jaw[k], dtype=np.float32).reshape(-1, 1, 2)
             for k in ("fixed_jaw", "moving_open", "moving_closed") if k in jaw}
    if "fixed_jaw" not in polys:
        return {"ok": False, "why": f"{JAW_SHAPE_JSON} 里没有 `fixed_jaw`"}
    raw, near, which = None, None, ""
    for name, poly in polys.items():
        d, q = _gap_px(poly, pts)
        if raw is None or d > raw:          # 哪一圈被探得最狠就报哪一圈
            raw, near, which = d, q, name
    # `_gap_px` 给的是 `pointPolygonTest` 的原值（正 = 红区探进爪子轮廓里）。这里翻成
    # 「红区离爪子轮廓外面多少像素」—— 正 = 留了缝。判据要的是它**落在带里**（见
    # `CLEAR_BAND_*`），只有 `CLEAR_BAND_ON = False` 时才是「越大越好」。
    gap = -float(raw)

    m = cv2.moments(cnt)
    if abs(float(m["m00"])) < 1e-9:
        return {"ok": False, "why": "红区退化成一个点，量不出中心"}
    c_uv = np.array([m["m10"] / m["m00"], m["m01"] / m["m00"]], dtype=np.float64)
    box_uv = _box_center_px(cnt, bgr)
    if box_uv is None:
        return {"ok": False, "why": "红区里亮暗分不开（或亮块太小），量不出方块顶面中心"}
    band_uv = np.concatenate([polys[k].reshape(-1, 2) for k in polys],
                             axis=0).mean(axis=0)
    ref = np.asarray(jaw["axis_ref_px"], dtype=np.float64)
    axis_dir = np.asarray(jaw["axis_dir_px"], dtype=np.float64)
    axis_dir = axis_dir / max(float(np.linalg.norm(axis_dir)), 1e-12)
    n_hat = np.array([-axis_dir[1], axis_dir[0]], dtype=np.float64)
    rel = box_uv - ref
    axis = float(np.dot(rel, n_hat))
    along = float(np.dot(rel, axis_dir))
    # **第二条缝的尺子：整块退出去还要多少像素。** 见 `_exit_px` 的说明 —— `gap` 只看
    # 最近的那一个点，方块大半压在轮廓里时它会说「只差几个像素」。
    gap_exit = _exit_px(list(polys.values()), pts, axis_dir)
    # **拦门的那条缝换成「沿合爪轴的净空」**（用户 2026-10-16 定：量上面那段缝是错的）。
    # 最近距离那条（`gap`）照量照打，只留作参考。
    gap_axis = _gap_axis_px(list(polys.values()), pts, axis_dir)
    gap_near = gap

    # **量缝之前先看合爪轴有没有真的对着方块**（用户 2026-10-17）：「首先得要让夹取方向
    # 在目标像素里面，咱不能离目标太远开始量缝吧」。把红区投到 ⊥合爪轴 那一维上，看
    # 合爪轴自己那条线（偏移 0）在不在方块横跨的那一段里。不在 = 轴根本没穿过它，这时
    # 沿轴量出来的那个数是「离得多远」，不是「缝」—— 这条缝不认，按「量不出来」办。
    _lat = (pts - ref) @ n_hat
    axis_in = bool(float(_lat.min()) <= 0.0 <= float(_lat.max()))
    if not axis_in:
        print(f"    {tag}缝不量：合爪轴没穿过方块（方块横跨 "
              f"{float(_lat.min()):+.0f}~{float(_lat.max()):+.0f} 像素，合爪轴在 0 那一条）"
              f" —— 离得太远，沿轴量出来的不是缝")
        gap_axis = None

    # **`axis_only=True`（下探之后那一趟）缝这条不拦门**（用户 2026-10-17：「下探后的微调
    # 无需调整缝隙……微调如果第一眼就符合就不用调整了」）。判据只剩轴偏这一条，缝照量照打。
    #
    # 原来这里一律 `缝 且 轴偏` 一起判，`ok` 到 `_clearance_loop` 里再被改回来 —— 于是
    # **打出来的那一行说的是错的**。实测 `out/` 那一轮的面板日志（2026-10-17 03:3x）：
    # `下探之后（只修轴偏）轮廓：缝 +10 像素（要落在 [20, 75] 里）  轴偏 +9 像素（容 ≤35）
    # → 不过` —— 轴偏 +9 明明在容内，那一行却报「不过」，就是因为缝在替它拦门。
    gap_ok = bool(gap_axis is not None and _gap_ok(gap_axis))
    ok = bool(abs(axis) <= AXIS_TOL_PX) if axis_only else bool(
        gap_ok and abs(axis) <= AXIS_TOL_PX)
    # **缝这条要落在带里**（2026-10-16 用户定）：低于下限 = 爪面压上方块，高于上限 = 方块
    # 已经退出两爪之间。老口径只有下限，所以退得越远越「合格」—— 那正是空抓的那一半。
    want = (f"要落在 [{CLEAR_BAND_LO_PX:.0f}, {CLEAR_BAND_HI_PX:.0f}] 里＝方块在两爪之间"
            if CLEAR_BAND_ON else f"要 ≥{CLEAR_TARGET_PX:.0f}")
    if axis_only:
        want = f"只报数（这一趟不拦门；拦门的是轴偏 ≤{AXIS_TOL_PX:.0f}）"
    _gap_txt = "—（合爪轴没穿过方块）" if gap_axis is None else f"{gap_axis:+.0f}"
    print(f"    {tag}轮廓：缝 {_gap_txt} 像素（{want}，**沿合爪轴**"
          f"量；最近距离那条 {gap_near:+.0f}、最近的是 {which}；整块退出去还要 {gap_exit:.0f}）"
          f"  轴偏 {axis:+.0f} 像素（容 ≤{AXIS_TOL_PX:.0f}）"
          f"  沿轴 {along:+.0f}  方块中心 ({box_uv[0]:.0f},{box_uv[1]:.0f})"
          f"  → {'过' if ok else '不过'}")

    # 画一张：这一刻的画面 + 描好的轮廓 + 合爪轴 + 红区轮廓 + 读数。
    # **固定文件名，覆盖**。检查没过、或者事后想知道「那一眼看成什么样」，看它。
    #
    # **这一张不画任何「中心」**（用户 2026-10-17）：「其他点比如顶面中心，其他心啥的都不
    # 用标在图上」。原来这里画了三个 —— 绿十字（画面那条尺量的顶面中心）、灰小圆（红区质
    # 心）、白圈（红区轮廓离爪最近那一点）。要看的那个中心只有一个：3D 那条尺子冻住的方块
    # 中心，由 `_mark_frozen` 在这一张上画成白色小三角。图上少三个点，剩下的白三角反而好找。
    col = {"fixed_jaw": (255, 255, 0), "moving_open": (0, 255, 0),
           "moving_closed": (0, 165, 255)}
    for name, poly in polys.items():
        cv2.polylines(bgr, [poly.astype(np.int32)], True, col[name], 3, cv2.LINE_AA)
    far = 0.8 * float(bgr.shape[1])
    cv2.line(bgr, tuple(np.round(ref - far * axis_dir).astype(int)),
             tuple(np.round(ref + far * axis_dir).astype(int)), (255, 0, 255), 2, cv2.LINE_AA)
    cv2.drawContours(bgr, [cnt], -1, (0, 0, 255), 2)
    # **`gap_axis` 可能是 `None`**（合爪轴没穿过方块那一眼，见上面那段）—— 按浮点格式化
    # 会直接抛 `TypeError: unsupported format string passed to NoneType.__format__`，
    # 把整趟技能带走。这一行跟上面那行 `_gap_txt` 一个口径：量不出来就写 `--`。
    _gap_img = "--" if gap_axis is None else format(float(gap_axis), "+.0f")
    txt = (f"{tag}  gap {_gap_img}px "
           f"({'want ' + format(CLEAR_BAND_LO_PX, '.0f') + '..' + format(CLEAR_BAND_HI_PX, '.0f') + ' = between jaws' if CLEAR_BAND_ON else 'want >=' + format(CLEAR_TARGET_PX, '.0f')}, along the jaw axis)"
           f"   axis {axis:+.0f}px (tol {AXIS_TOL_PX:.0f})   {'PASS' if ok else 'FAIL'}")
    # **写在下边**：`_confirm_step` 会读同一张图、往顶上写它那几行（见 `_put_lines`）。
    _put_lines(bgr, [txt], (0, 200, 0) if ok else (0, 0, 255), bottom=True)
    cv2.imwrite(str(JAW_CHECK_IMG), bgr)

    return {"ok": ok, "gap": None if gap_axis is None else float(gap_axis),
            "axis_in": axis_in, "gap_near": float(gap_near),
            "gap_exit": float(gap_exit), "which": which,
            "axis": axis, "along": along,
            "box_uv": box_uv, "c_uv": c_uv, "band_uv": band_uv, "near_uv": near,
            "axis_ref_px": ref, "axis_dir_px": axis_dir}


def _project_px(cam, p_world):
    """世界点投到像素。投不出来（没有腕相机 / 没机位 / 点在相机背后）返回 `None`。

    内参那条岔路跟 `_px_per_mm` **一模一样**（真机那份标定带着 `k`，仿真那份只有 `fovy`）
    —— 两处口径不许各写一份。
    """
    if cam is None:
        return None
    mount = cam.mount()
    if mount is None:
        return None
    w, h = (int(v) for v in cam.size())
    k = mount.get("k")
    if k is None:
        k = vision.intrinsics(float(mount["fovy"]), w, h)
    return vision.project(mount["pos"], mount["mat"], k, np.asarray(p_world, dtype=np.float64))


def _mark_frozen(cam, p_world) -> None:
    """**离轴要对准的那个中心** —— 冻住的 3D 方块中心，投影到画面里画成**白色小三角**。

    它就是 `_jaw_check_3d` 量离轴用的那个点（`p = (center - tcp)·n`，目标 0 = 把方块中心
    摆到合爪轴上）。用户 2026-10-17：「你把离轴要对准的目标中心用小三角形标出来，用白色，
    字搞的大一点，其他点比如顶面中心，其他心啥的都不用标在图上给我看了」。

    所以这张图上**只有这一个点**：青/绿/橙三圈是爪轮廓、品红长线是合爪轴、红描边是红区
    轮廓 —— 都是线段不是「中心」；绿十字／灰小圆／白圈那三个中心已经撤掉（见 `_jaw_check`）。
    投不出来就不画。
    """
    import cv2                                                  # noqa: PLC0415

    uv = _project_px(cam, p_world)
    if uv is None:
        return
    img = cv2.imread(str(JAW_CHECK_IMG))
    if img is None:
        return
    u, v = int(round(float(uv[0]))), int(round(float(uv[1])))
    # 先黑后白：盒子是深棕、桌面也偏暗，只用白的边容易糊掉。
    for col, w in (((0, 0, 0), 6), ((255, 255, 255), 2)):
        cv2.drawMarker(img, (u, v), col, cv2.MARKER_TRIANGLE_UP, 16, w, cv2.LINE_AA)
    for col, w in (((0, 0, 0), 6), ((255, 255, 255), 2)):
        cv2.putText(img, "OFF-AXIS TARGET", (u + 20, v - 16),
                    cv2.FONT_HERSHEY_SIMPLEX, 1.2, col, w, cv2.LINE_AA)
    cv2.imwrite(str(JAW_CHECK_IMG), img)


def _save_look(cams, facts) -> None:
    """把「看一眼」那一帧存下来（带 `real.perception.draw` 那层标注），写 `out/look_see.jpg`。

    只写图，**不动任何判据**。这一眼就是冻结那个 3D 中心的来源（`run` 里进场之后、纠位
    之前那一档），事后要复盘「中心是按哪张图定的」只能看它。
    """
    import cv2                                                  # noqa: PLC0415

    from real.perception import draw                            # noqa: PLC0415

    cam = _wrist(cams)
    if cam is None:
        print("    （存这一眼的画面：没有腕相机这一路）")
        return
    try:
        bgr = cv2.cvtColor(np.asarray(cam.shot()), cv2.COLOR_RGB2BGR)
        LOOK_IMG.parent.mkdir(parents=True, exist_ok=True)
        cv2.imwrite(str(LOOK_IMG), draw(bgr, facts or {}))
    except Exception as e:                                      # noqa: BLE001
        # 存图失败不该把这一趟弄死，但**不许闷掉** —— 把原文打出来。
        print(f"    （存这一眼的画面失败：{type(e).__name__}: {e}）")
        return
    print(f"    这一眼的画面（带标注）-> {LOOK_IMG}")


def _jaw_mm(arm, center, clear, tag: str, *, extra: str = "", cam=None) -> dict:
    """合爪轴（`arm.tips()` 正解）跟**给定的**一个方块中心（3D、底座系）摆到一起。

    返回 `p`（离轴，米）、`ds`（沿轴 − 该在的 `clear`，米）、`delta`（该把 TCP 挪多少，
    水平、米）、`ok`。**这是 2026-10-15 起拦门的那条尺子**（`CLEAR_3D_ENFORCE`）：
    `|p| <= CLEAR_3D_TOL_MM` 且 `|ds| <= CLEAR_3D_TOL_MM`。

    `center` 由调用方给。微调那一支给的是**冻住的那一个**（下探之前那一眼量到的），
    **不再从可见红区轮廓上现取** —— 那个点会被爪子挡住而乱跳（实测同一趟里 34 像素）。
    合爪轴只用关节角正解，跟画面无关，挡不挡都一样。
    """
    f, m = arm.tips()
    u = np.asarray(m, dtype=np.float64) - np.asarray(f, dtype=np.float64)
    u[2] = 0.0
    nu = float(np.linalg.norm(u))
    if nu < 1e-9:
        return {"ok": False, "no_world": True, "why": "两爪尖水平投影重合，量不出合爪轴"}
    u = u / nu
    n = np.array([-u[1], u[0], 0.0], dtype=np.float64)

    center = np.asarray(center, dtype=np.float64).reshape(-1)[:3]
    tcp = np.asarray(arm.tcp(), dtype=np.float64)
    r = center - tcp
    s = float(np.dot(r, u))                     # 沿合爪轴，从固定爪尖算起（目标 +clear）
    p = float(np.dot(r, n))                     # 离轴（目标 0）
    s_want = float(clear)                       # 进嘴那一侧 = +u，**不乘 side**（见下面那条）
    ds = s - s_want
    tol = CLEAR_3D_TOL_MM / 1000.0
    # **3D 这边只拦「离轴」那一维**（用户 2026-10-17：「新版离轴+旧版的缝」）。
    # 沿轴那维照量照打、**不在这里拦** —— 缝的判据换回**旧版画面那条单边下限**
    # （`gap >= CLEAR_TARGET_PX`，无上限），在 `_clearance_loop` 里跟这条并起来判。
    ok = bool(abs(p) <= tol)
    print(f"    {tag} 3D：离轴 {p * 1000:+.1f}mm（容 ≤{CLEAR_3D_TOL_MM:.0f}）  "
          f"沿轴 {s * 1000:+.1f}mm（该 {s_want * 1000:+.1f}，差 {ds * 1000:+.1f}）"
          f"  方块中心 {np.round(center * 1000, 1)}mm{extra}"
          f"  → 离轴这边{'过' if ok else '不过'}"
          + ("" if CLEAR_3D_ENFORCE else "（**只报数，拦门的是画面那两条**）"))
    if cam is not None:
        # 让这一眼用的那个「中心」在图上有个标记 —— 不画的话没人知道它落在盒子哪儿。
        _mark_frozen(cam, center)
    delta = p * n + ds * u
    return {"ok": ok, "s": s, "p": p, "ds": ds, "s_want": s_want, "delta": delta,
            "center": center, "u": u, "n": n, "tcp": tcp}


def _jaw_check_3d(arm, cam, percep, instruction, guess, clear, tag: str) -> dict:
    """下探到底那一刻的 **3D 判据**：方块中心离实测出来的合爪轴、沿轴各差多少毫米。

    三个输入都不是新东西：
      · **合爪轴** —— 读回六个关节角（`arm.tips()` 自己读），取两个爪尖的水平连线当
        `u`（固定爪 → 动爪）、它的水平垂线当 `n`；
      · **方块中心** —— 走线上同一条感知链 `percep.locate`（它内部扣掉
        `real.percep_offset_mm`，所以跟 `arm.tcp()` 在同一个坐标系里）；
      · **该在哪** —— 就是下探那一段已经算好的 `aim`：`(center − tcp)` 沿轴该等于
        `+clear`、离轴该是 0。**不另发明目标点。**

    **沿轴那个目标点就是 `+clear`，不带符号。** `u` 按定义从固定爪尖指向动爪尖，方块该
    待在**嘴里面**、固定爪尖前 `clear`（半边长 + 爪面探出 + 缝）—— 就是 `aim` 那条算式
    `center + side·clear·xt` 挪出来的那一点。**2026-10-15 第一版这里写成 `−side·clear`，
    修正量整个发反了**：这台机器上 `arm.tool_x()` 跟 `u` 反向（`xt·u = −1`），乘上去才等于
    `aim`；不乘就成了「把方块放到固定爪背后」。日志证据：第一眼打「该 −10.8」，而按几何
    该是 `+10.8`，于是 TCP 朝抓取方向走了 5.5mm，实际要朝反方向退 16.1mm。

    `guess` 要的是**已经扣过偏移的**方块中心（上一眼量出来的那个），本函数内部把偏移加
    回去再喂给 `locate` —— `locate` 的种子在扣偏移之前那一侧（`real/perception.py:351-359`），
    拿扣过的直接当种子会差那 35.8mm。

    量不出来（方块被爪挡掉 / 没有够格的棕区）返回 `{'ok': False, 'no_world': True}`，
    调用方不当回事 —— 它只报数。
    """
    if cam is None:
        return {"ok": False, "no_world": True, "why": "没有腕相机这一路"}
    seed = np.asarray(guess, dtype=np.float64).copy() if guess is not None else None
    if seed is not None:
        seed[:2] = seed[:2] + geom.real_percep_offset()
    center, facts = percep.locate(instruction, guess=seed)
    if center is None:
        why = facts.get("no_world_why") or facts.get("why") or "没认出来"
        return {"ok": False, "no_world": True, "why": why, "iou": facts.get("iou")}
    # **每眼现量**的那一版。微调那一支不用它 —— 用 `_jaw_mm` 加冻住的那个中心。
    out = _jaw_mm(arm, center, clear, tag, cam=cam,
                  extra=f"  重合度 {facts.get('iou')}  估的形状 {facts.get('size')}")
    out["facts"] = facts
    return out


def _px_per_mm(cam, center):
    """这一点上「画面像素 / 底座毫米」的**带号** 2×2 矩阵 `J = ∂(u,v)/∂(x,y)`。

    投不出来（没有腕相机 / 没机位 / 点在相机背后）给 `None`。`_solve_delta` 和
    `_set_clearance` 的 `B` 初值都用它 —— 只此一处，别在两处各写一遍内参那条岔路。
    """
    if cam is None:
        return None
    mount = cam.mount()
    if mount is None:
        return None
    # 内参：真机那份标定里带着 `k`，仿真那份只有 `fovy` —— 跟 `_view_radius` 一个口径。
    w, h = (int(v) for v in cam.size())
    k = mount.get("k")
    if k is None:
        k = vision.intrinsics(float(mount["fovy"]), w, h)
    jac = vision.px_per_m_xy(mount, k, np.asarray(center, dtype=np.float64))
    return None if jac is None else np.asarray(jac, dtype=np.float64)


def _solve_delta(cam, center, m):
    """按画面里的偏差反解出「臂该动多少毫米」。返回 `(Δp 像素, δ 毫米)`，算不出来给 `None`。

    `Δp = ref − 方块顶面中心`：把方块顶面中心挪回描轮廓时点的那一点（`axis_ref_px`，
    「方块该被夹住的那个中心」）。沿合爪轴那一段把它拉回理想中心（爪朝画面**右边**退），
    垂直那一段把它拉回轴上。两段都到 0，就是「方块顶面中心正好落在该被夹住的那个中心上」。

    **画面里怎么换到臂上。** 臂一动，爪子跟相机是一起走的 —— 画面里动的只有目标，位移
    ≈ `−J·δ`（`J` = `vision.px_per_m_xy` 在目标那一点上的**带号** 2×2）。反解
    `δ = −J⁻¹·Δp`。**这正是原来那版栽过的地方**：它拿 `px_per_m` 的模长当尺子、方向靠
    `side` 猜，`out/run_real_37.log` 里读数 14 → 16 → 17 一路往外跑，指令和读数方向是反的。

    这个是**解出来的量**，自动那一路只拿它当方向（`_nudge` 用定步长走），手动那一路把它
    当建议值摆进 `out/manual_state.jsonl` 给操作员看。
    """
    jac = _px_per_mm(cam, center)
    if jac is None:
        return None
    try:
        inv = np.linalg.inv(jac)
    except np.linalg.LinAlgError:
        return None
    dp = (np.asarray(m["axis_ref_px"], dtype=np.float64)
          - np.asarray(m["box_uv"], dtype=np.float64))
    if float(np.linalg.norm(dp)) < 1e-6:
        return None
    want = -inv @ dp
    if float(np.linalg.norm(want)) < 1e-9:
        return None
    return dp, want


def _manual_on() -> bool:
    """微调这段是不是交给外面一步步给（环境变量 `PICK_MANUAL=1`）。"""
    import os                                                   # noqa: PLC0415

    return os.environ.get("PICK_MANUAL", "").strip().lower() not in ("", "0", "false", "no")


def _confirm_on() -> bool:
    """**合爪那一步**停下来等点头（环境变量 `PICK_CONFIRM=1`）。"""
    import os                                                   # noqa: PLC0415

    return os.environ.get("PICK_CONFIRM", "").strip().lower() not in ("", "0", "false", "no")


def _confirm_descend_on() -> bool:
    """**只在下探那一关**停下来等点头（环境变量 `PICK_CONFIRM_DESCEND=1`）。

    用户 2026-10-16：「下一轮下探前最后一帧给我看」—— 微调那几十眼不用停（他已经看过策略
    在动），但**下探之前那一帧必须让他看一眼**：那一眼就是「爪子相对方块摆成什么样」的终态，
    下探一落、跟着就合爪，没有第二次机会。`PICK_CONFIRM_STEP=1` 开着的时候这一关照旧停。
    """
    import os                                                   # noqa: PLC0415

    return (os.environ.get("PICK_CONFIRM_DESCEND", "").strip().lower()
            not in ("", "0", "false", "no")) or _confirm_step_on()


def _confirm_step_on() -> bool:
    """**微调每一步**也停下来等点头（环境变量 `PICK_CONFIRM_STEP=1`）。

    **2026-10-15 用户：「每步时间太长了」。** 原来两个闸口共用 `PICK_CONFIRM`，于是微调
    每一步都要走一趟「写 `out/clear_step.json` → 外面每 0.1 秒扫一次 → 写回
    `out/clear_go.json`」；实测每一眼多花几秒，而且没人守着就干等（那一趟白等了 7 分钟）。
    拆开之后：`PICK_CONFIRM=1` 只管合爪那一步（用户定过「一个实验只准合一趟爪」，那一步
    必须有人看过），微调不再停。
    """
    import os                                                   # noqa: PLC0415

    return os.environ.get("PICK_CONFIRM_STEP", "").strip().lower() not in (
        "", "0", "false", "no")


def _resume_on() -> bool:
    """这一趟是不是从断点接着走（环境变量 `PICK_RESUME=1`，`run_sim.py --resume-pick` 设）。"""
    import os                                                   # noqa: PLC0415

    return os.environ.get("PICK_RESUME", "").strip().lower() not in ("", "0", "false", "no")


def _save_checkpoint(rec: dict) -> None:
    """把这一眼的状态写盘。**覆盖写** —— 盘上永远只留最近这一个断点。"""
    import json                                                 # noqa: PLC0415
    import time                                                 # noqa: PLC0415

    rec = {**rec, "version": CHECKPOINT_VERSION,
           "created": time.strftime("%Y-%m-%d %H:%M:%S")}
    CHECKPOINT.parent.mkdir(parents=True, exist_ok=True)
    CHECKPOINT.write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"    ⤓ 断点已写盘：{CHECKPOINT.name}"
          f"（这一刻被 kill 的话，下一次带 `--resume-pick` 就从这一眼接着走）")


def _load_checkpoint() -> dict | None:
    """读盘上那份断点。没有 / 读不出来 / 版本不对，都当没有 —— 宁可从头走一趟。"""
    import json                                                 # noqa: PLC0415

    if not CHECKPOINT.exists():
        return None
    try:
        ck = json.loads(CHECKPOINT.read_text(encoding="utf-8"))
    except Exception as exc:                                    # noqa: BLE001
        print(f"    ! {CHECKPOINT.name} 读不出来（{type(exc).__name__}）—— 当没有断点")
        return None
    got = int(ck.get("version") or 0)
    if got != CHECKPOINT_VERSION:
        print(f"    ! {CHECKPOINT.name} 是版本 {got}，这一版认的是 {CHECKPOINT_VERSION}"
              f" —— 当没有断点，从头走这一趟")
        return None
    return ck


def _drop_checkpoint() -> None:
    """这一趟走完了（合爪了 / 判失败了），盘上那份断点作废。"""
    CHECKPOINT.unlink(missing_ok=True)


def _arm_off_checkpoint(arm, ck: dict) -> float:
    """臂现在离断点那个姿态差多少度（六个关节里离得最远的那个）。读不到就是 999。

    **这是续跑唯一认领不认领的判据**，`skills/home_real.py` 那边跳过回位也用它 ——
    两处不许各写一份，不然「回位跳过了、抓取却不认」会出现。
    """
    try:
        q_now = np.asarray(arm.angles(), dtype=np.float64).reshape(-1)
    except Exception:                                           # noqa: BLE001
        return 999.0
    q_ck = np.asarray(ck.get("angles") or [], dtype=np.float64).reshape(-1)
    if q_ck.size == 0 or q_now.shape != q_ck.shape:
        return 999.0
    return float(np.max(np.abs(q_now - q_ck)))


def _confirm_step(m: dict, dp, seg_axis, seg_gap, step_xy, tgt, gain: float, z0: float,
                  tries: int, *, mm: dict | None = None):
    """把这一步画出来、摆出去、等点头。

    返回 `(放不放行, 外面给的位移或 None)`：
      · `(False, None)` —— 叫停 / 等超时，这一趟不合爪，退回去；
      · `(True, None)` —— 点头了，走算出来的那一步；
      · `(True, (dx, dy))` —— **外面直接给位移**（米，底座坐标系，相对此刻的 TCP），
        这一步按它走、不走算出来的那一步。走完照常重量一眼、回到这个闸口。

    **位移怎么给**（`out/clear_go.json`，三种任选）：
      · `{"go": true}`            —— 走算出来的那一步；
      · `{"move": [dx, dy]}`      —— 毫米，相对此刻 TCP 的位移（z 照旧钉在 `z0`）；
      · `{"tgt": [x, y]}`         —— 毫米，底座系绝对坐标（z 照旧钉在 `z0`）；
      · `{"dz": -5}`              —— 毫米，把**钉住的那一档高度**挪一挪（可跟 `move` 一起给）；
      · `{"abort": true}`         —— 这一趟不合爪，退回去。

    用户 2026-10-16 定：**断点上要能「我说怎么移就怎么移」，不许只能退回重跑。**
    同一天又要「下一点高度看看能不能合上」—— 所以 `dz` 给出来：给了就把 `z0` 也改掉，
    后面每一眼都钉在**新的**那一档（只给一次、后面自动沿用，不然下一眼就弹回去）。

    画的是**当前那一帧**（`out/jaw_check.jpg`，`_jaw_check` 刚写的那张）上面再加箭头，
    都从画面里那个方块中心那一点出发：
      · 绿 = 轴偏那一段（`(−axis)·n_hat`，把方块中心拉回那条线上）；
      · 黄 = 缝那一段（`_gap_need_px(gap, gap_exit)·axis_dir`，把缝送回带里 —— 缝不够就
        把红区推离爪子轮廓，缝超了就把方块**拉回**两爪之间）；
      · 红 = 这一步要走的量。

    **`CLEAR_3D_ENFORCE` 开着的时候**（`mm` 不是 None）：拦门的是 3D 毫米那两条，绿黄两段
    是画面那条尺子的分解 —— **只给人看，不参与**；红箭头画的是这一步落到画面里的等效位移
    （`−jac @ step`）。画面那条量不出来（红区被爪子挡住）时 `dp` 是 None，就不画箭头。
    文字全 ASCII（`cv2.putText` 不认中文）。图写 `out/clear_step.jpg`，读数写
    `out/clear_step.json`，然后等 `out/clear_go.json`。
    """
    import json                                                 # noqa: PLC0415

    import cv2                                                  # noqa: PLC0415

    box = m.get("box_uv")
    box = None if box is None else np.asarray(box, dtype=np.float64)
    img = cv2.imread(str(JAW_CHECK_IMG))
    if img is not None and box is not None:
        p0 = (int(round(float(box[0]))), int(round(float(box[1]))))
        for seg, col, w in ((seg_axis, (0, 200, 0), 4), (seg_gap, (0, 220, 220), 4)):
            if seg is None:
                continue
            p1 = (int(round(float(box[0] + seg[0]))), int(round(float(box[1] + seg[1]))))
            cv2.arrowedLine(img, p0, p1, col, w, cv2.LINE_AA, tipLength=0.25)
        if dp is not None:
            end = (int(round(float(box[0] + dp[0]))), int(round(float(box[1] + dp[1]))))
            cv2.arrowedLine(img, p0, end, (0, 0, 255), 6, cv2.LINE_AA, tipLength=0.25)
            cv2.circle(img, end, 7, (255, 255, 255), 2, cv2.LINE_AA)
    if img is not None:
        # 文字全 ASCII —— `cv2.putText` 不认中文。
        def _q(v, fmt="{:+.0f}"):
            return "?" if v is None else fmt.format(float(v))
        _want = (f"{CLEAR_BAND_LO_PX:.0f}..{CLEAR_BAND_HI_PX:.0f} = between jaws"
                 if CLEAR_BAND_ON else f">={CLEAR_TARGET_PX:.0f}")
        # 每行都短一点 —— `_put_lines` 按最长那行现算字号，压短一行就把整块字顶大一档。
        # 括号里那些常数（`want` / `tol`）原来挤在同一行，把字撑到画幅边上。
        px_line = (f"px (reference only):  gap {_q(m.get('gap'))} (want {_want})"
                   f"   axis {_q(m.get('axis'))} (tol {AXIS_TOL_PX:.0f})"
                   f"   along {_q(m.get('along'))}")
        step_line = (f"arm step ({step_xy[0] * 1000:+.1f}, {step_xy[1] * 1000:+.1f}) mm"
                     f"   gain {gain:.2f}   z pinned {z0 * 1000:+.1f} mm")
        lin = [f"tries {tries}   px and mm both on this frame"] if mm is None else [
            f"tries {tries}   RULER = 3D mm   box center FROZEN (looked before the descent)",
            f"off-axis {mm['p'] * 1000:+.1f} mm (tol {CLEAR_3D_TOL_MM:.0f})"
            f"   along-axis {mm['ds'] * 1000:+.1f} mm (report only)"
            f"   -> {'PASS' if mm['ok'] else 'FAIL'}",
            px_line,
        ]
        if mm is not None and dp is not None:
            step_line += f"   red arrow = that step ({dp[0]:+.0f}, {dp[1]:+.0f}) px"
        lines = lin + [step_line,
                       f"target {np.round(np.asarray(tgt) * 1000, 1)} mm (base frame)"]
        _put_lines(img, lines)
        cv2.imwrite(str(CONFIRM_IMG), img)

    rec = {"tries": tries,
           "ruler": "3d_mm_frozen" if mm is not None else "pixel",
           "gap": None if m.get("gap") is None else round(float(m["gap"]), 1),
           "want_gap": _gap_want_px(),
           "band_px": ([CLEAR_BAND_LO_PX, CLEAR_BAND_HI_PX] if CLEAR_BAND_ON else None),
           "axis": None if m.get("axis") is None else round(float(m["axis"]), 1),
           "tol_axis": AXIS_TOL_PX,
           "along": None if m.get("along") is None else round(float(m["along"]), 1),
           "box_uv": None if box is None else [round(float(v), 1) for v in box],
           "dp_px": None if dp is None else [round(float(dp[0]), 1), round(float(dp[1]), 1)],
           "seg_axis_px": None if seg_axis is None else [round(float(seg_axis[0]), 1),
                                                         round(float(seg_axis[1]), 1)],
           "seg_gap_px": None if seg_gap is None else [round(float(seg_gap[0]), 1),
                                                       round(float(seg_gap[1]), 1)],
           "step_mm": [round(float(step_xy[0]) * 1000, 2), round(float(step_xy[1]) * 1000, 2)],
           "tgt_mm": [round(float(v) * 1000, 1) for v in np.asarray(tgt).reshape(-1)],
           "gain": round(float(gain), 3),
           "z0_mm": round(float(z0) * 1000, 2),
           "img": str(CONFIRM_IMG)}
    if mm is not None:
        # 拦门的那两条，单位毫米。**看图就看这两个数。**
        rec["off_axis_mm"] = round(float(mm["p"]) * 1000, 2)
        rec["along_axis_mm"] = round(float(mm["ds"]) * 1000, 2)
        rec["tol_mm"] = CLEAR_3D_TOL_MM
        rec["frozen_center_mm"] = [round(float(v) * 1000, 1)
                                   for v in np.asarray(mm["center"]).reshape(-1)]
    CONFIRM_STEP.parent.mkdir(parents=True, exist_ok=True)
    CONFIRM_STEP.write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    CONFIRM_GO.unlink(missing_ok=True)
    how = (f'给 {{"go": true}} 走算出来的这一步、{{"move": [dx, dy]}} 或 {{"tgt": [x, y]}}'
           f"（毫米，底座系）直接给位移、{{'abort': true}} 这一趟不合爪")
    if mm is None:
        print(f"    ⏸ 等点头：{CONFIRM_IMG.name} 是当前这一帧（绿=轴偏那一段、黄=缝那一段、"
              f"红=合起来），读数 {CONFIRM_STEP.name}；写 {CONFIRM_GO} {how}"
              f"（最多等 {CONFIRM_WAIT_S / 60:.0f} 分钟）")
    else:
        print(f"    ⏸ 等点头：{CONFIRM_IMG.name} 是当前这一帧（**尺子是 3D 毫米、方块中心"
              f"冻住**：离轴 {mm['p'] * 1000:+.1f}mm、沿轴差 {mm['ds'] * 1000:+.1f}mm，"
              f"两条都容 ≤{CLEAR_3D_TOL_MM:.0f}mm），读数 {CONFIRM_STEP.name}；写 "
              f"{CONFIRM_GO} {how}（最多等 {CONFIRM_WAIT_S / 60:.0f} 分钟）")
    cmd = _wait_cmd(CONFIRM_WAIT_S, CONFIRM_GO)
    if cmd is None:
        print("    ✗ 等点头等超时了 —— 这一趟不合爪，退回去")
        return False, None
    # **闸口叫「别微调了，直接下探」**（用户 2026-10-16：「可不可以结束微调直接下探」）。
    # 微调的进带条件是量出来的，它不进带就永远等不到下探；人看着爪子和方块觉得够正了，
    # 得有一条「收工」的口子。给 `{"descend": true}` 就从这儿跳出微调、照冻住的那个中心
    # 走竖直下探（`_descend_to_grasp`），水平一点不再挪。
    if cmd.get("descend"):
        print("    ✓ 外面叫直接下探 —— 微调到这儿收工，不再挪水平，去走竖直下探那一截")
        return True, ("descend", 0.0, 0.0)
    # **外面直接给位移**（用户 2026-10-16：「断点上我说怎么移就怎么移」）。给了就不走
    # 算出来的那一步 —— 走这个，走完照常重量一眼、再回到这个闸口。
    mv = cmd.get("move") if cmd.get("move") is not None else cmd.get("move_mm")
    dzc = cmd.get("dz")
    dz = None if dzc is None else float(dzc) / 1000.0
    if mv is not None:
        d = np.asarray(mv, dtype=np.float64).reshape(-1)
        if d.size >= 2:
            tail = "" if dz is None else f"、高度 {dz * 1000:+.1f}mm"
            print(f"    ✓ 外面给的位移 ({d[0]:+.1f}, {d[1]:+.1f})mm{tail} —— 按它走（不是算出来的 "
                  f"({step_xy[0] * 1000:+.2f}, {step_xy[1] * 1000:+.2f})mm）")
            return True, (float(d[0]) / 1000.0, float(d[1]) / 1000.0, dz)
        print(f"    ✗ 外面给的位移只有 {d.size} 个数，要两个 —— 这一趟不合爪，退回去")
        return False, None
    if dz is not None:
        # 只给高度：水平不动，把钉住的那一档挪一挪。
        print(f"    ✓ 外面只给了高度 {dz * 1000:+.1f}mm —— 水平不动，按它走")
        return True, (0.0, 0.0, dz)
    tg = cmd.get("tgt") if cmd.get("tgt") is not None else cmd.get("tgt_mm")
    if tg is not None:
        a = np.asarray(tg, dtype=np.float64).reshape(-1)
        if a.size >= 2:
            print(f"    ✓ 外面给的绝对目标 ({a[0]:+.1f}, {a[1]:+.1f})mm —— 按它走")
            return True, ("abs", float(a[0]) / 1000.0, float(a[1]) / 1000.0)
        print(f"    ✗ 外面给的绝对目标只有 {a.size} 个数，要两个 —— 这一趟不合爪，退回去")
        return False, None
    if not cmd.get("go"):
        print(f"    ✗ 外面叫停（{cmd}）—— 这一趟不合爪，退回去")
        return False, None
    print("    ✓ 点头了，走这一步")
    return True, None


def _descend_to_grasp(arm, center):
    """微调进带之后、合爪之前，**再竖直下去一截**（用户 2026-10-16 定）。

    返回 `(走没走成, 走完那一刻的 TCP)`。走不成（等超时 / 外面叫停 / 这一截顶住没到底）
    返回 `(False, ...)`，外面照旧退回悬停点、这一趟判失败 —— **没到底就不合爪**，这是
    原来 `_descend` 那一段就定的规矩（浅处合上去只合在方块顶上，抬起来必掉）。

    **只动 z。** 微调刚把水平那两维调进带里，这一步再碰一下水平就等于白调。
    终点 = 「方块中心 + `GRASP_Z_FINAL_REAL`」，起点读的是**此刻真实的 TCP**（不是微调前
    记的那个 —— 横移完高度会掉，`out/run_real_73.log` 第 62 行掉 0.9mm）。

    `PICK_CONFIRM_STEP=1` 时停下来等点头：图 `out/descend_step.jpg`（当前这一帧 + 两行字）、
    读数 `out/descend_step.json`，等的还是 `out/clear_go.json`：
      · `{"go": true}`    —— 按算出来的这一档往下走；
      · `{"dz": -3}`      —— 毫米，**把这一档再挪一挪**（负 = 再往下），只给一次、后面沿用；
      · `{"abort": true}` —— 不下去，这一趟不合爪。
    """
    import json                                                 # noqa: PLC0415

    import cv2                                                  # noqa: PLC0415

    tcp0 = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
    z_tgt = float(center[2]) + GRASP_Z_FINAL_REAL
    drop = float(tcp0[2]) - z_tgt
    print(f"    微调完了，再竖直下去一截才合爪：从 {tcp0[2] * 1000:+.1f}mm 走到 "
          f"{z_tgt * 1000:+.1f}mm（方块中心 {float(center[2]) * 1000:+.1f}mm "
          f"{GRASP_Z_FINAL_REAL * 1000:+.0f}mm），下 {drop * 1000:.1f}mm，x/y 一点不动")
    if _confirm_descend_on():
        img = cv2.imread(str(JAW_CHECK_IMG))
        if img is not None:
            lines = [f"DESCEND before closing   z {tcp0[2] * 1000:+.1f} -> {z_tgt * 1000:+.1f} mm"
                     f"   (drop {drop * 1000:.1f} mm, x/y frozen)",
                     f"target = box center z {float(center[2]) * 1000:+.1f} mm"
                     f" + {GRASP_Z_FINAL_REAL * 1000:+.0f} mm"]
            _put_lines(img, lines)
            cv2.imwrite(str(CONFIRM_DESCEND_IMG), img)
        rec = {"z_now_mm": round(float(tcp0[2]) * 1000, 2),
               "z_target_mm": round(z_tgt * 1000, 2),
               "drop_mm": round(drop * 1000, 2),
               "center_z_mm": round(float(center[2]) * 1000, 2),
               "final_margin_mm": GRASP_Z_FINAL_REAL * 1000,
               "tcp_mm": [round(float(v) * 1000, 1) for v in tcp0],
               "img": str(CONFIRM_DESCEND_IMG)}
        CONFIRM_DESCEND.parent.mkdir(parents=True, exist_ok=True)
        CONFIRM_DESCEND.write_text(json.dumps(rec, ensure_ascii=False, indent=1),
                                   encoding="utf-8")
        CONFIRM_GO.unlink(missing_ok=True)
        print(f"    ⏸ 等点头：{CONFIRM_DESCEND_IMG.name} 是当前这一帧 + 两行字，读数 "
              f"{CONFIRM_DESCEND.name}；写 {CONFIRM_GO} 给 {{\"go\": true}} 按这一档下、"
              f"{{\"dz\": -3}}（毫米，负 = 再往下）改这一档高度、{{'abort': true}} 不下去"
              f"（最多等 {CONFIRM_WAIT_S / 60:.0f} 分钟）")
        cmd = _wait_cmd(CONFIRM_WAIT_S, CONFIRM_GO)
        if cmd is None:
            print("    ✗ 等点头等超时了 —— 这一趟不合爪，退回去")
            return False, tcp0
        dzc = cmd.get("dz")
        if dzc is not None:
            z_tgt += float(dzc) / 1000.0
            print(f"    ✓ 外面把这一档改成 {z_tgt * 1000:+.1f}mm —— 按它走")
        elif not cmd.get("go"):
            print(f"    ✗ 外面叫停（{cmd}）—— 这一趟不合爪，退回去")
            return False, tcp0
        else:
            print("    ✓ 点头了，往下走")
    if drop <= 0.0:
        print(f"    ⚠ 读到的 TCP 已经在 {tcp0[2] * 1000:+.1f}mm、不比目标 {z_tgt * 1000:+.1f}mm "
              f"高 —— 不再往下走（免得变成往上抬），就这么合爪")
        return True, tcp0
    # **一气呵成**（用户 2026-10-16：「你下探的时候不准多抖几下，只准一气呵成」）：
    # `tries=1` = 解一次、走一趟，不重解、不补第二趟 —— 就是一段连续下降。
    out = _goto(arm, np.array([tcp0[0], tcp0[1], z_tgt], dtype=np.float64),
                vmax=speed_vmax(SLOW), grip=1.0,
                free=(FREE_DESCENT if CLEAR_FREE_ON else None),
                ow=(0.0 if CLEAR_FREE_ON else None), tries=1)
    tcp1 = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
    print(f"    下探一截：{out}  TCP z {tcp0[2] * 1000:+.1f} → {tcp1[2] * 1000:+.1f}mm"
          f"（要 {z_tgt * 1000:+.1f}mm）；水平 ({tcp0[0] * 1000:+.1f}, {tcp0[1] * 1000:+.1f}) → "
          f"({tcp1[0] * 1000:+.1f}, {tcp1[1] * 1000:+.1f})mm")
    # **只验收 z + 横漂上限**（`DESCEND_XY_TOL_MM`，用户 2026-10-16「飘 <20mm 都没事」）：
    # `_goto` 那个 `out` 是三维误差判的，这一段横着飘是放开的，所以不能拿它当判据。
    _dz = abs(float(tcp1[2] - z_tgt))
    _dxy = float(np.hypot(tcp1[0] - tcp0[0], tcp1[1] - tcp0[1]))
    if _dz > DESCEND_Z_TOL_MM / 1000.0 or _dxy > DESCEND_XY_TOL_MM / 1000.0:
        print(f"    ✗ 这一截没到底（{out}；z 差 {_dz * 1000:.1f}mm 判据 "
              f"{DESCEND_Z_TOL_MM:.0f}mm、横漂 {_dxy * 1000:.1f}mm 判据 "
              f"{DESCEND_XY_TOL_MM:.0f}mm）—— 没到底就不合爪"
              f"（浅处合上去只合在方块顶上），退回去")
        return False, tcp1
    print(f"    ✓ 这一截认了（{out}；z 差 {_dz * 1000:.1f}mm、横漂 {_dxy * 1000:.1f}mm "
          f"≤ {DESCEND_XY_TOL_MM:.0f}mm）—— 合爪")
    return True, tcp1


def _confirm_lift(cam, tcp_now, z0: float, tries: int) -> bool:
    """**抬高度那一步也停下来等点头**（用户 2026-10-16 定）。

    横移完舵机在重力下会掉几毫米，原来这里直接自动走一趟竖直抬回去 —— 用户看到的是
    「一串没人看过的动作」，而且实测三次自动抬升读回来一次比一次低（−2.3 → −4.5 → −4.8mm，
    `out/run_real_68.log`）。现在跟 `_confirm_step` 一个口径：**先拍一张当前的整幅画面**
    （不是 `_jaw_check` 那张旧帧）、摆出去、等人点头，才动。图写 `out/clear_lift.jpg`、
    读数写 `out/clear_lift.json`，等的还是 `out/clear_go.json`。

    只在 `PICK_CONFIRM_STEP=1` 下走（跟微调那一步同一个开关）。
    """
    import json                                                 # noqa: PLC0415

    import cv2                                                  # noqa: PLC0415

    z_now = float(np.asarray(tcp_now, dtype=np.float64)[2])
    drop_mm = (float(z0) - z_now) * 1000.0
    img = None
    if cam is not None:
        try:
            img = cv2.cvtColor(np.asarray(cam.shot()), cv2.COLOR_RGB2BGR)
        except Exception as e:                                  # noqa: BLE001
            print(f"    （抬高度这一眼拍不到：{type(e).__name__}: {e}）")
            img = None
    if img is not None:
        # 文字全 ASCII —— `cv2.putText` 不认中文。
        lines = [
            f"LIFT STEP  tries {tries}  (NOT a lateral nudge)",
            f"TCP z now {z_now * 1000:+.1f} mm   floor {z0 * 1000:+.1f} mm"
            f"   dropped {drop_mm:+.1f} mm",
            f"goes straight UP to z = {z0 * 1000:+.1f} mm   xy stays "
            f"({float(tcp_now[0]) * 1000:+.1f}, {float(tcp_now[1]) * 1000:+.1f}) mm",
        ]
        _put_lines(img, lines)
        cv2.imwrite(str(CONFIRM_LIFT_IMG), img)

    rec = {"kind": "lift", "tries": tries,
           "z_now_mm": round(z_now * 1000, 2),
           "z_floor_mm": round(float(z0) * 1000, 2),
           "drop_mm": round(drop_mm, 2),
           "xy_now_mm": [round(float(tcp_now[0]) * 1000, 1),
                         round(float(tcp_now[1]) * 1000, 1)],
           "img": str(CONFIRM_LIFT_IMG)}
    CONFIRM_LIFT.parent.mkdir(parents=True, exist_ok=True)
    CONFIRM_LIFT.write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    CONFIRM_GO.unlink(missing_ok=True)
    print(f"    ⏸ 等点头（**抬高度**）：{CONFIRM_LIFT_IMG.name} 是刚拍的整幅画面，读数 "
          f"{CONFIRM_LIFT.name}（TCP 读到 {z_now * 1000:+.1f}mm、比 {z0 * 1000:+.1f}mm 低 "
          f"{drop_mm:.1f}mm，要走一趟竖直抬回去）；写 {CONFIRM_GO} 给 "
          f'{{"go": true}} 就抬、给 {{"abort": true}} 这一趟不合爪（最多等 '
          f"{CONFIRM_WAIT_S / 60:.0f} 分钟）")
    cmd = _wait_cmd(CONFIRM_WAIT_S, CONFIRM_GO)
    if cmd is None:
        print("    ✗ 等点头等超时了 —— 这一趟不合爪，退回去")
        return False
    if not cmd.get("go"):
        print(f"    ✗ 外面叫停（{cmd}）—— 这一趟不合爪，退回去")
        return False
    print("    ✓ 点头了，抬回去")
    return True


def _confirm_pass(m: dict, mm: dict | None, tag: str, *, ruler: str = "3D mm") -> bool:
    """**判过了也停下来等点头**（只在 `PICK_CONFIRM=1` 下走）。

    原来判过就直接进合爪了。尺子换成 3D 那条之后不能这么走：万一它系统性偏到「过」那一侧，
    爪子会在没人看过一眼的情况下合上 —— 而用户定过「一个实验只准合一趟爪」。这一跳只摆
    当前那一帧和读数，等 `out/clear_go.json` 的 `{"go": true}`。

    `ruler` 是**这一次拦门的是哪条**，只影响印在图上和人看的那行字；`mm` 那一份（3D 读数）
    量不出来时是 None，那就不印它 —— 拦门的那条数不能因为旁支量不出来就丢了。
    """
    import json                                                 # noqa: PLC0415

    import cv2                                                  # noqa: PLC0415

    p = None if not mm else mm.get("p")
    ds = None if not mm else mm.get("ds")
    c3 = None if not mm else mm.get("center")
    g = m.get("gap")
    a = m.get("axis")
    img = cv2.imread(str(JAW_CHECK_IMG))
    if img is not None:
        lines = [f"tries READY TO CLOSE   RULER = {ruler}"]
        if p is not None and ds is not None:
            lines.append(f"off-axis {p * 1000:+.1f} mm (tol {CLEAR_3D_TOL_MM:.0f})"
                         f"   along-axis {ds * 1000:+.1f} mm (report only)")
        lines.append(f"gap {'--' if g is None else format(float(g), '+.1f')}px"
                     f"   axis {'--' if a is None else format(float(a), '+.1f')}px"
                     f"   -> PASS")
        if c3 is not None:
            lines.append(f"frozen center {np.round(np.asarray(c3) * 1000, 1)} mm")
        _put_lines(img, lines, (0, 255, 0))
        cv2.imwrite(str(CONFIRM_IMG), img)

    rec = {"pass": True, "ruler": ruler, "tag": tag,
           "off_axis_mm": None if p is None else round(float(p) * 1000, 2),
           "along_axis_mm": None if ds is None else round(float(ds) * 1000, 2),
           "tol_mm": CLEAR_3D_TOL_MM,
           "frozen_center_mm": None if c3 is None else
                               [round(float(v) * 1000, 1)
                                for v in np.asarray(c3).reshape(-1)],
           "gap_px": None if g is None else round(float(g), 1),
           "axis_px": None if a is None else round(float(a), 1),
           "img": str(CONFIRM_IMG)}
    CONFIRM_STEP.parent.mkdir(parents=True, exist_ok=True)
    CONFIRM_STEP.write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    CONFIRM_GO.unlink(missing_ok=True)
    print(f"    ⏸ 判过了、**先不合**：{CONFIRM_IMG.name} 是当前这一帧（拦门的是 {ruler}；"
          f"缝 {'--' if g is None else format(float(g), '+.1f')} 像素、"
          f"轴偏 {'--' if a is None else format(float(a), '+.1f')} 像素），"
          f"读数 {CONFIRM_STEP.name}；写 {CONFIRM_GO} 给 "
          f'{{"go": true}} 就合爪、给 {{"abort": true}} 这一趟不合（最多等 '
          f"{CONFIRM_WAIT_S / 60:.0f} 分钟）")
    cmd = _wait_cmd(CONFIRM_WAIT_S, CONFIRM_GO)
    if cmd is None:
        print("    ✗ 等点头等超时了 —— 这一趟不合爪，退回去")
        return False
    if not cmd.get("go"):
        print(f"    ✗ 外面叫停（{cmd}）—— 这一趟不合爪，退回去")
        return False
    print("    ✓ 点头了，合爪")
    return True


def _publish(m: dict, arm, cam, center, step: int, tag: str, *, fresh: bool = False) -> None:
    """把这一眼的读数摆出去：往 `out/manual_state.jsonl` 追加一行。

    一行就是一步的全部 —— 判据读数、方块中心、该在的那一点、当前 TCP、以及**反解出来的
    建议位移**（毫米，底座坐标系）。操作员（我/人）读它决定下一步走多少，`read` 一次就
    能看最近几步，不用一步一步问。
    """
    import json                                                 # noqa: PLC0415
    import time                                                 # noqa: PLC0415

    rec = {"t": time.strftime("%H:%M:%S"), "step": int(step), "tag": tag,
           "gap": None if m.get("gap") is None else round(float(m["gap"]), 1),
           "want_gap": _gap_want_px(),
           "band_px": ([CLEAR_BAND_LO_PX, CLEAR_BAND_HI_PX] if CLEAR_BAND_ON else None),
           "which": m.get("which", ""),
           "axis": None if m.get("axis") is None else round(float(m["axis"]), 1),
           "along": None if m.get("along") is None else round(float(m["along"]), 1),
           "tol_axis": AXIS_TOL_PX,
           "ok": bool(m.get("ok")), "why": m.get("why", "")}
    if m.get("box_uv") is not None:
        rec["box_uv"] = [round(float(v), 1) for v in np.asarray(m["box_uv"]).reshape(-1)]
    if m.get("axis_ref_px") is not None:
        rec["ref_px"] = [round(float(v), 1) for v in np.asarray(m["axis_ref_px"]).reshape(-1)]
    if m.get("axis_dir_px") is not None:
        rec["axis_dir"] = [round(float(v), 4) for v in np.asarray(m["axis_dir_px"]).reshape(-1)]
    if getattr(arm, "tcp", None) is not None:
        try:
            rec["tcp_mm"] = [round(float(v) * 1000, 1) for v in np.asarray(arm.tcp()).reshape(-1)]
        except Exception:                                       # noqa: BLE001
            pass
    # 反解建议：同一个算式（`_solve_delta`），自动那一路拿它定方向，这里只是把它摆出来。
    got = _solve_delta(cam, center, m)
    if got is not None:
        rec["suggest_mm"] = [round(float(got[1][0]) * 1000, 1), round(float(got[1][1]) * 1000, 1)]
    MANUAL_STATE.parent.mkdir(parents=True, exist_ok=True)
    with MANUAL_STATE.open("w" if fresh else "a", encoding="utf-8") as f:
        f.write(json.dumps(rec, ensure_ascii=False) + "\n")
    print(f"    ⇢ 读数已摆到 {MANUAL_STATE.name}（第 {step} 步）："
          f"缝 {rec['gap']} / 轴偏 {rec['axis']} / 沿轴 {rec['along']}"
          f" / 建议 {rec.get('suggest_mm')}mm")


def _peek_cmd(path=None):
    """看一眼有没有命令。**文件存在且能解析成 JSON** 才算有 —— 写的那一瞬间文件可能只落了
    一半，解析不了就当还没写好，接着等。`path` 不给就是手动那一路的 `out/manual_cmd.json`；
    逐步点头那一路（`PICK_CONFIRM=1`）传 `CONFIRM_GO`。"""
    import json                                                 # noqa: PLC0415

    path = MANUAL_CMD if path is None else path
    if not path.exists():
        return None
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None


def _take_cmd(path=None):
    """取走一条命令：读到就删掉文件（文件在不在 = 有没有待办）。没有返回 `None`。"""
    cmd = _peek_cmd(path)
    if cmd is None:
        return None
    try:
        (MANUAL_CMD if path is None else path).unlink()
    except OSError:
        pass
    return cmd


def _wait_cmd(timeout: float, path=None):
    """等一条命令，最多 `timeout` 秒。到点还没等到返回 `None`。

    每一轮先调一次 `WAIT_TICK`（默认 None，行为不变）—— 面板靠它在这一头把按键做掉，
    见那个变量的说明。**钩子抛异常不能把等待顶掉**：那一头的活儿（刷快照、关节点动）
    出点小错是常事，等点头本身不能因此中断。
    """
    import time                                                 # noqa: PLC0415

    t0 = time.time()
    while time.time() - t0 < timeout:
        if WAIT_TICK is not None:
            try:
                WAIT_TICK()
            except Exception as exc:                            # noqa: BLE001
                print(f"    ！等点头时的顺手活儿出错（不影响继续等）："
                      f"{type(exc).__name__}: {exc}")
        cmd = _take_cmd(path)
        if cmd is not None:
            return cmd
        time.sleep(0.1)
    return None


def _set_clearance_manual(arm, cam, percep, center, tag: str) -> dict:
    """手动那一路：量完把读数摆出去、等操作员给一串位移，走到进带里或者外面叫停。

    命令（`out/manual_cmd.json`）三样，全是可选的：
        `moves` 一串 `[dx, dy]` 或 `[dx, dy, dz]`（毫米，底座坐标系），按序走、每步量一次；
        `hold` 这一串走完继续等（不给就也继续等 —— 等命令本来就是这儿的常态）；
        `abort` 收工，这一趟不合爪。
    **走的当中外面又塞了新命令**，剩下的几步丢掉、按新的来。这就是「臂不停下来等一个
    来回」的做法：操作员读一次数、想一步要几十秒，臂停在那儿就是白等。

    兜底两条：等一条命令最多 `MANUAL_WAIT_S`，手动步数最多 `MANUAL_MAX_MOVES`。哪条
    到顶都返回 `ok=False`，调用方不合爪、退回去 —— 不把臂带电扔在方块上方。

    **基准是进来那一瞬间的 tcp，不是每一步量回来的 tcp。** 2026-10-15 `out/run_real_46.log`
    记着：每一步都是「当前实测 + 偏移」，臂压根到不了指令那个 z，差的那点每步攒一层，
    三步下来 z 从 +0.2 掉到 −6.4mm —— 下探高度是算出来的，它自己往下爬等于把那个数作废。
    现在 `base` 进循环前取一次，`off` 累加，指令给 `[dx, dy, dz]` 时 z 也跟着动。
    """
    MANUAL_CMD.unlink(missing_ok=True)          # 上一趟剩的命令不算数
    last = _jaw_check(cam, percep, arm, tag)
    base = np.asarray(arm.tcp(), dtype=np.float64)
    off = np.zeros(3)
    moves = 0
    _publish(last, arm, cam, center, 0, tag, fresh=True)
    while True:
        if last.get("ok"):
            print(f"    ✓ 手动微调第 {moves} 步进带里了 —— 照常合爪")
            return {**last, "tries": moves, "manual": True}
        if last.get("gap") is None:
            print(f"    ✗ 量不了：{last.get('why')} —— 这一趟不合爪，退回去")
            return {**last, "ok": False, "tries": moves, "manual": True}
        if moves >= MANUAL_MAX_MOVES:
            print(f"    ✗ 手动走满 {MANUAL_MAX_MOVES} 步还没进带里 —— 这一趟不合爪")
            return {**last, "ok": False, "why": f"手动走满 {MANUAL_MAX_MOVES} 步",
                    "tries": moves, "manual": True}
        print(f"    ⏸ 等命令：读 {MANUAL_CMD}（最多等 {MANUAL_WAIT_S / 60:.0f} 分钟）")
        cmd = _wait_cmd(MANUAL_WAIT_S)
        if cmd is None:
            print("    ✗ 等命令等超时了 —— 这一趟不合爪，退回去")
            return {**last, "ok": False, "why": "等命令超时", "tries": moves, "manual": True}
        if cmd.get("abort"):
            print("    ✗ 外面叫停 —— 这一趟不合爪，退回去")
            return {**last, "ok": False, "why": "外面叫停", "tries": moves, "manual": True}
        for pair in cmd.get("moves", []) or []:
            if moves >= MANUAL_MAX_MOVES:
                break
            d = np.array([float(pair[0]), float(pair[1]),
                          float(pair[2]) if len(pair) > 2 else 0.0]) / 1000.0
            off = off + d
            tgt = base + off
            moves += 1
            print(f"    ➜ 操作员第 {moves} 步：走 ({d[0] * 1000:+.1f}, {d[1] * 1000:+.1f},"
                  f" {d[2] * 1000:+.1f})mm（累计偏移 {np.round(off * 1000, 1)}mm，"
                  f"到 {np.round(tgt * 1000, 1)}mm，爪张着）")
            _goto(arm, tgt, vmax=speed_vmax(SLOW), grip=1.0, tol=MANUAL_GOTO_TOL)
            last = _jaw_check(cam, percep, arm, f"{tag}（手动第 {moves} 步后）")
            _publish(last, arm, cam, center, moves, tag)
            if last.get("ok") or last.get("gap") is None:
                break
            if _peek_cmd() is not None:
                print("    ↻ 有新命令进来了 —— 这一串剩下的不走了，按新的来")
                break

    """照画面里的偏差算一次横向微调，走过去。返回 `{'tgt':…}`；算不出来返回 `{}`。

    **往哪挪（2026-10-15 用户定）。** 瞄的是描轮廓时点的那一点 ——
    `real_wrist_jaw_shape.json` 的 `axis_ref_px`，也就是「方块该被夹住的那个中心」在画面里
    的像素。要的是**方块顶面中心挪回那一点**，`Δp = ref − 方块顶面中心`。

    **不再用「从爪子那坨的中心指向方块」那个方向。** `out/run_real_42.log`：缝 −3 时它给出
    `Δp=(−7, +8)`，y 那一分量把方块在画面里往下带了 119 像素 —— 缝是拉开了（−3 → +31），
    轴偏却从 −7 崩到 −126，方块整个掉出轴外。用户原话：「你挑的方向不对，应该把爪子向画面
    里的右边，而不是朝着收缩的方向，或者你可以计算爪子的夹取方向和目标中心的相对位置，
    看看怎么挪」。

    `Δp = ref − center` 就是这个「相对位置」，一次算出来两段：
      · 沿合爪轴那段 = `−along`：把方块拉回理想中心（本趟是往画面**右**推爪子那一边）；
      · 垂直那段 = `−axis`：把方块拉回轴上。
    两段都到 0，就是「方块顶面中心正好落在该被夹住的那个中心上」。

    **画面里怎么换到臂上。** 臂一动，爪子跟相机是一起走的 —— 画面里动的只有目标，位移
    ≈ `−J·δ`（`J` = `vision.px_per_m_xy` 在目标那一点上的**带号** 2×2）。反解
    `δ = −J⁻¹·Δp`。**这正是原来那版栽过的地方**：它拿 `px_per_m` 的模长当尺子、方向靠
    `side` 猜，`out/run_real_37.log` 里读数 14 → 16 → 17 一路往外跑，指令和读数方向是反的。

    **这个函数只剩手动那一路（`PICK_MANUAL=1`）在用。** 自动那一路（`_set_clearance`）
    2026-10-15 改成「步长由实测响应自己算」之后，定步长那条就只留给操作员给建议值了。
    步长是定的（`NUDGE_STEP_M`，用户 2026-10-15 从 10mm 加到 20mm）：反解出来的 `δ` 只用
    它的**方向**，长度一律按定步长走 —— `out/run_real_40.log` 那一趟反解出 2mm 上下，
    按那个量发下去画面里几乎没动。

    z 不动、爪保持张着（`grip=1.0`）—— 微调只挪位置，不合爪、不算重试。
    """
    # 方块顶面中心要挪回「该被夹住的那个中心」—— 沿轴那一段把方块拉回理想中心（爪朝画面
    # 右边退），垂直那一段把方块拉回轴上。**就这一条算式**，不再叠「从爪子中心指向方块」。
    got = _solve_delta(cam, center, m)
    if got is None:
        return {}
    dp, want = got
    box_uv = np.asarray(m["box_uv"], dtype=np.float64)
    ref = np.asarray(m["axis_ref_px"], dtype=np.float64)
    # **定步长**：方向用反解出来的，长度一律 `NUDGE_STEP_M`（用户 2026-10-15 定 20mm）。
    delta = want * (NUDGE_STEP_M / float(np.linalg.norm(want)))
    tgt = np.asarray(arm.tcp(), dtype=np.float64) + np.array([delta[0], delta[1], 0.0])
    print(f"    方块该在画面里挪 ({dp[0]:+.0f}, {dp[1]:+.0f}) 像素"
          f"（沿轴 {m['along']:+.0f} 归零、轴偏 {m['axis']:+.0f} 归零）"
          f"，即方块中心从 ({box_uv[0]:.0f},{box_uv[1]:.0f}) 挪到 "
          f"({ref[0]:.0f},{ref[1]:.0f})"
          f" → 反解该动 ({want[0] * 1000:+.1f}, {want[1] * 1000:+.1f})mm"
          f"，按定步长走 ({delta[0] * 1000:+.1f}, {delta[1] * 1000:+.1f})mm"
          f"（走到 {np.round(tgt * 1000, 0)}mm，z 不动、爪张着）再量一次")
    return {"tgt": tgt, "dpx": dp, "delta": delta}


def _set_clearance(arm, cams, percep, center, tag: str, *, instruction=None,
                   guess=None, clear=0.0, resume=None, ctx=None,
                   axis_only: bool = False) -> dict:
    """合爪前把爪子摆到「爪子轮廓和红色有距离 **且** 合爪方向线压住方块中心」。
    **挪一眼、量一眼，直到画面里那两条同时过。**

    **两条门槛，都是画面像素**（`_jaw_check`，2026-10-15 用户定：「我现在就需要在爪子轮廓
    和红色有距离 + 合爪方向线和目标中心对齐，只有满足这两个标准才能合爪」）：
      · 缝落在带里（`CLEAR_BAND_LO_PX <= gap <= CLEAR_BAND_HI_PX`；`CLEAR_BAND_ON = False`
        时退回旧的 `gap >= CLEAR_TARGET_PX`）：红区离**整圈**爪子轮廓最近有多远 ——
        「有距离」，而且**不许退过头**（2026-10-16：退过头 = 方块已经在两爪外面，空抓）；
      · `|axis| <= AXIS_TOL_PX`：方块顶面中心到合爪轴那条线的垂距 —— 「线和中心对齐」。
    3D 那一份（`_jaw_check_3d`）照量照打、**不拦门**（它跟画面在这台机器上差十几毫米，
    见文件头 `CLEAR_3D_ENFORCE` 上面那段）。

    怎么走（**次数和步长都不写死**，2026-10-15 用户定「你的策略要能按照实际情况来」）：
      1. 两条误差**分开算、各管一维**（见文件头那段）：`dp = (−axis)·n_hat +
         _gap_need_px(gap, gap_exit)·axis_dir`；
      2. 用 `B`（「TCP 走 1mm → 方块中心动多少像素」）换成毫米，乘 `CLEAR_GAIN`：
         `δ = CLEAR_GAIN · B⁻¹ · dp`，z 不动、爪保持张着；
      3. 走一步再量一眼，拿「TCP 实际走的毫米」和「方块中心实际动的像素」把 `B` 更新一次
         （Broyden），臂比指令走得多、走不动、方向不对都会被学进 `B`。

    **什么时候停**：两条都过；或连着 `CLEAR_FLAT_STOP` 眼误差不再变小；或这一步已经不足
    `CLEAR_MIN_STEP_M`。**都不是次数上限**，是量出来的。停不进门槛返回 `ok=False`，
    调用方不合爪、退回去（2026-10-15 用户定：「一直调不进带里先判失败」）。

    **微调只挪水平两维，高度一律钉在下探那一档**（2026-10-15 用户定：「禁止微调下高度」）。
    `z0` 进循环前取一次，之后每一步的 `tgt` 都用它当 z，**不取每一步读回来的那个** ——
    `out/run_real_54.log`：命令里 z 分量本来就是 0，但起点拿的是「刚读回来、已经掉下去的
    TCP」，而 `_goto` 每趟落点又比指令低 0.5～2.3mm，4 步下来 z 从 0.0 爬到 −7.4mm。
    水平两维仍按读回来的值闭环（那是要修上一步的残差），只有 z 是绝对量。

    **修正的时候不能碰方块**：上一步把缝压回带里以下、而且还在掉，步子乘
    `CLEAR_CONTACT_GAIN` 压下来。

    **逐步点头那一路**（环境变量 `PICK_CONFIRM=1`）走法跟上面**一模一样**，只是每一次
    `_goto` 之前停下来：这一步画进 `out/clear_step.jpg`、读数写 `out/clear_step.json`，
    等 `out/clear_go.json` 点头（`_confirm_step`）。

    **手动那一路**（环境变量 `PICK_MANUAL=1`）不自己挪 —— 交给 `_set_clearance_manual`：
    量完把读数摆到 `out/manual_state.jsonl`、等 `out/manual_cmd.json`，步长和步数都由
    外面一步一步给。

    **断点续跑那一趟**（`resume` 不是 None，见文件头 `CHECKPOINT` 那一段）走法一模一样，
    只是 `z0` / `B` / `gain` / `prev` / 已走次数 / `flat` 全从盘上那份接过来、臂一步不动
    —— 断点就是臂现在这个姿态。那一趟 `PICK_MANUAL` 不再生效（手动那一路不写断点）。

    `ctx` 是「微调过了之后那几段还要用的东西」（`hover` / `closing` / 夹爪行程两端），
    循环里一个数都不用，只是**原样写进断点**，续跑那一趟再读回来。

    `axis_only=True` 是**下探之后那一趟**（用户 2026-10-16：「下探以后再加一个微调，但是
    只能动轴偏方向，其他方向不能动」）：竖直那一截已经走完、两个爪子正夹在方块两侧，
    这时候**只修轴偏**（`|axis| <= AXIS_TOL_PX`），缝那条不当门槛、沿合爪轴那一段一律写 0
    —— 在这个高度上沿合爪轴挪就是拿爪面去怼方块。缝照样量、照样打，只是不拦门。
    """
    try:
        return _clearance_loop(arm, cams, percep, center, tag, instruction=instruction,
                               guess=guess, clear=clear, resume=resume, ctx=ctx,
                               axis_only=axis_only)
    finally:
        # **这一支走完了（合爪了 / 判失败了），盘上那份断点作废。** 从断点接上那一趟
        # 也在这里收尾 —— 接着走完了，就不再需要它。
        _drop_checkpoint()


def _clearance_loop(arm, cams, percep, center, tag, *, instruction=None, guess=None,
                    clear=0.0, resume=None, ctx=None, axis_only: bool = False) -> dict:
    """`_set_clearance` 的正文。说明见它上面（以及文件头 `CHECKPOINT` 那一段）。"""
    cam = _wrist(cams)
    if resume is None and _manual_on():
        return _set_clearance_manual(arm, cam, percep, center, tag)

    seed3d = np.asarray(center if guess is None else guess, dtype=np.float64).reshape(-1)
    # **冻住的那个方块中心**（`CLEAR_3D_ENFORCE` 那条尺子用的就是它）。来源是下探**之前**
    # 那一眼量到的那一个 —— `run` 里 `_measure` 给的 `center`（`guess` 有就用 `guess`，
    # 两个是同一眼的量，`guess` 只是给 `percep.locate` 当种子的那一份）。方块在桌上不动，
    # 这一趟从头到尾都用它，**不再每眼重量一次**。
    frozen3d = seed3d.copy()
    # **下探那一档高度，微调全程钉住**（`_set_clearance_manual` 的 `base` 同一个道理）：
    # 之后每一步都往这个 z 上走，臂掉下去了也拉回来，不让它一层层往下攒。
    z0 = float(np.asarray(arm.tcp(), dtype=np.float64)[2])
    # **半个边长**（米）：缝不够时那一步的下限用（见下面 `CLEAR_GAP_MIN_HALF` 那一段）。
    half_m = _box_half_m(percep)
    B = None                        # 「TCP 走 1mm → 画面里方块中心动多少像素」，实测出来的
    b_src = "投出来"                # `B` 是哪来的 —— 只影响日志里那句「步子 × 谁的响应」
    gain = CLEAR_GAIN
    prev = None                     # 上一眼：误差、`box_uv`、那一刻的 `tcp`、那一刻的 `gap`
    flat = 0
    n = 0
    if resume is not None:
        # ---- 从盘上那一份接上：z0 / B / 步长 / 次数接过来，臂不再重走前几段 ----
        z0 = float(resume["z0"])
        gain = float(resume.get("gain") or CLEAR_GAIN)
        n = int(resume.get("tries") or 0)
        flat = int(resume.get("flat") or 0)
        if resume.get("B") is not None:
            B = np.asarray(resume["B"], dtype=np.float64)
        b_src = "断点那一趟实测的"
        # **`prev` 不恢复。** 它是**上一个进程**那一眼记的 `tcp` / `box_uv`；两个进程之间
        # 臂会因为断电重读、重力塌落挪掉零点几毫米（实测 2026-10-15：z 掉 0.37mm、x 偏
        # 0.53mm），而方块没动 —— Broyden 会把这一段**不是我们指令出来的**位移当成响应学
        # 进去，一步就把 `B` 学坏（实测 [[1484,−5030],[−4521,−1350]] → [[246,−5090],
        # [−884,−1174]]，同一条残差算出来的步子从 1.5mm 变成 8.7mm）。**从这一眼重新起
        # 一个 `prev`**：下一步走完再拿「指令的位移 ↔ 方块动的像素」更新，那才是这一趟的。
        ruler = ("尺子是 3D 毫米（中心用盘上那份、轴走 FK）" if CLEAR_3D_ENFORCE
                 else f"响应矩阵是 {b_src}")
        print(f"    ⤒ 从断点接上：微调第 {n} 次之前那一眼（z 钉在 {z0 * 1000:+.1f}mm、"
              f"步子 {gain:.2f} 倍、{ruler}、已走 {n} 次），"
              f"臂一步不动，直接去量这一眼")
    last: dict = {}
    while True:
        sub = tag if n == 0 else f"{tag}（微调第 {n} 次后）"
        # **只修轴偏那一趟：缝那条不拦门**（用户 2026-10-16：「只能动轴偏方向」、2026-10-17
        # 「下探后的微调无需调整缝隙」）。这一半现在由 `_jaw_check` 自己按 `axis_only` 判 ——
        # 原来是在这里把 `ok` 改回来，于是**打出去的那一行跟拦门的结论对不上**（缝在替轴偏
        # 拦门，轴偏明明在容内却报「不过」），见 `_jaw_check` 里那段。
        last = _jaw_check(cam, percep, arm, sub, axis_only=axis_only)
        if axis_only:
            last["axis_only"] = True
        if CLEAR_3D_ENFORCE:
            # **拦门这条尺子**：3D 毫米。中心是冻住的那一个，合爪轴走 FK —— 两条都不看
            # 红区轮廓，爪子挡在上面也一样准。
            mm = _jaw_mm(arm, frozen3d, clear, sub, extra="（冻住的，不现量）", cam=cam)
            if mm.get("no_world"):
                print(f"    ✗ 量不了：{mm.get('why')} —— 这一趟不合爪，退回去")
                return {**last, **mm, "ok": False, "why": mm.get("why"), "tries": n,
                        "pixel": False}
            # **`axis_only` 那一趟只拿离轴那条拦门**（跟画面那一支同一个口径：这一趟沿轴
            # 不动，沿轴差多少都拦不住、也不该拦）。
            _off_ok = bool(abs(float(mm["p"])) <= CLEAR_3D_TOL_MM / 1000.0)
            # **缝那一半用画面那条带**（用户 2026-10-17：「新版离轴+旧版的缝」、
            # 「缝是 20~75 像素」）：`CLEAR_BAND_LO_PX <= gap <= CLEAR_BAND_HI_PX`。
            # 3D 的「沿轴」那维照量照打、不在这里拦门。
            _gap_px = last.get("gap")
            _gap_ok = bool(_gap_px is not None
                           and CLEAR_BAND_LO_PX <= float(_gap_px) <= CLEAR_BAND_HI_PX)
            mm_ok = bool(_off_ok if axis_only else (_off_ok and _gap_ok))
            if mm_ok:
                if axis_only:
                    print(f"    ✓ 离轴进容里了（离轴 {mm['p'] * 1000:+.1f}mm / 容 "
                          f"{CLEAR_3D_TOL_MM:.0f}mm；这一趟只修轴偏，沿轴差 "
                          f"{mm['ds'] * 1000:+.1f}mm 只报数）—— 合爪")
                else:
                    print(f"    ✓ 离轴和缝都过（离轴 {mm['p'] * 1000:+.1f}mm / 容 "
                          f"{CLEAR_3D_TOL_MM:.0f}mm；缝 {float(_gap_px):+.0f} 像素 / 要落在 "
                          f"[{CLEAR_BAND_LO_PX:.0f}, {CLEAR_BAND_HI_PX:.0f}] 里）—— 合爪")
                # **`ok` 必须显式覆盖**：`last`（画面那条）这一刻多半是 False（红区被爪子
                # 挡着，缝过不了门槛），拦门的换成毫米那条之后它不再代表这一趟的结论。
                if _confirm_on():
                    # **判过了这一跳也写断点。** 停在这里被 kill 的话，臂的姿态就是断点
                    # （用户 2026-10-15 要求：不许有「停下来了、却接不上」的口子）。
                    _save_checkpoint({
                        "why": "合爪前微调判过了、停在等你点头（盘上写的就是这一眼）",
                        "instruction": instruction, "tag": tag, "ctx": ctx,
                        "center": [float(v) for v in np.asarray(center).reshape(-1)],
                        "guess": [float(v) for v in np.asarray(seed3d).reshape(-1)],
                        "clear": float(clear),
                        "angles": [float(v) for v in np.asarray(arm.angles()).reshape(-1)],
                        "tcp": [float(v) for v in np.asarray(mm["tcp"]).reshape(-1)],
                        "z0": float(z0), "gain": float(gain), "tries": int(n),
                        "flat": int(flat), "B": None if B is None else np.asarray(B).tolist(),
                        "prev": None,
                        "look": {"frozen_mm": [float(v) * 1000 for v in frozen3d.reshape(-1)],
                                 "mm_p": float(mm["p"]) * 1000,
                                 "mm_ds": float(mm["ds"]) * 1000,
                                 "tol_mm": CLEAR_3D_TOL_MM},
                    })
                if _confirm_on() and not _confirm_pass(last, mm, sub):
                    return {**last, "ok": False, "why": "合爪前等点头时被叫停", "tries": n,
                            "pixel": False}
                return {**last, "ok": True, "mm": mm, "tries": n, "pixel": False}
        else:
            # 老口径：拦门的是画面像素那两条，3D 那份照量照打、只报数。
            mm = _jaw_check_3d(arm, cam, percep, instruction, seed3d, clear, sub)
            if last.get("ok"):
                if axis_only:
                    print(f"    ✓ 轴偏进带里了（轴偏 {last['axis']:+.0f} 像素 / 容 "
                          f"{AXIS_TOL_PX:.0f}；这一趟只修轴偏，缝 "
                          + ("—（合爪轴没穿过方块）" if last.get("gap") is None
                             else f"{last['gap']:+.0f} 像素")
                          + " 只报数） —— 合爪")
                else:
                    print(f"    ✓ 两条都过（缝 {last['gap']:+.0f} 像素、"
                          f"轴偏 {last['axis']:+.0f} 像素）—— 合爪")
                # **判过了也停下来等点头。** 拦门的换回画面之后，这个口子原来只在 3D 那一支
                # 上；不补的话「画面判过」会直接合爪 —— 而用户定过「一个实验只准合一趟爪」，
                # 合爪这一下必须有人看过这一帧再点头。摆的是**冻住的**那个中心（抓取目标），
                # 不是这一眼现量的那个。
                if _confirm_on() and not _confirm_pass(
                        last, {"center": frozen3d}, sub, ruler="picture (gap/axis)"):
                    return {**last, "ok": False, "why": "合爪前等点头时被叫停", "tries": n,
                            "pixel": True}
                return {**last, "tries": n, "pixel": True}
        if last.get("gap") is None and not CLEAR_3D_ENFORCE:
            print(f"    ✗ 量不了（画面那条）：{last.get('why')} —— 这一趟不合爪，退回去")
            return {**last, "ok": False, "why": last.get("why"), "tries": n, "pixel": True}
        if last.get("gap") is None:
            # 拦门不看它了，红区被挡住量不出来只留一句 —— 这一趟照走毫米那条。
            print(f"    ⚠ 画面那条量不了（{last.get('why')}）—— 这条不拦门，照走毫米那条")

        # ---- 该挪多少 ----
        tcp = np.asarray(arm.tcp(), dtype=np.float64)
        box_uv = (None if last.get("box_uv") is None
                  else np.asarray(last["box_uv"], dtype=np.float64))
        if CLEAR_3D_ENFORCE:
            # **拦门这条尺子**：`p` 是离轴、`ds` 是沿轴，两条都得进容里
            # （`_off_ok and _gap_ok`）。**但一次只走一维、每维走自己的关节**（用户
            # 2026-10-17：「你要分清造缝隙的方向，造缝隙别造错方向」）：
            #   · 缝那一维（沿合爪轴）→ **只放 1 号**（实测 3.13mm/度，唯一造得出缝的）；
            #   · 轴偏那一维（⊥合爪轴）→ **只放 4 号**（实测 −2.82mm/度）。
            # 两维混成一步是走不动的：拿 1 号去走 ⊥缝 那一维（它只有 0.07mm/度），长度
            # 会被一路乘到 10 倍上限，臂横着冲出去 —— 缝没变大、轴偏还更歪。
            _u3 = np.asarray(mm["u"], dtype=np.float64).reshape(-1)[:2]
            _n3 = np.asarray(mm["n"], dtype=np.float64).reshape(-1)[:2]
            # 缝进没进带。拦门的就是画面那条带（`_gap_ok` 在上面算过）。
            _gap_in = bool(_gap_ok)
            if axis_only or _gap_in:
                # 缝已经在带里（或这一趟压根不许碰沿轴）→ **只走离轴那一维，给 4 号**。
                move_m = float(mm["p"]) * _n3
                deep = 0.0                                          # 这一趟不碰沿轴
                axis_phase = True
                _seg_txt = "轴偏（⊥合爪轴 → 1 号）"
            else:
                # 缝没进带 → **只走沿合爪轴那一维，给 1 号**。
                # 幅度取 3D 的 `|ds|`；**「往哪边」以画面为准** —— 缝拦门的是画面那条带，
                # 3D 的沿轴这维照量照打、不拦门。两条尺子的定义都写死了：
                #   · 画面 `_gap_need_px`：**正 = 沿合爪轴推出去**、负 = 把方块拉回来；
                #   · 3D：`u` 从固定爪尖指向动爪尖、方块该待在 +u 侧 `s_want` 处，
                #     所以 **推出去 = 沿 −u 走 = `ds < 0`**。
                # 两条不一致就是「造错方向」：按画面走，并把两边都打出来。
                _mag = abs(float(mm["ds"]))
                if last.get("gap") is None:
                    _push = float(mm["ds"]) < 0.0                   # 画面量不出来，退回 3D 的符号
                else:
                    _push = _gap_need_px(float(last["gap"]),
                                         float(last.get("gap_exit") or 0.0)) > 0.0
                    if _push != (float(mm["ds"]) < 0.0):
                        print(f"    ⚠ 缝的方向两条尺子不一致：画面说"
                              f"{'推出去' if _push else '拉回来'}，3D 沿轴差 "
                              f"{float(mm['ds']) * 1000:+.1f}mm 说"
                              f"{'推出去' if float(mm['ds']) < 0 else '拉回来'}"
                              f" —— 按画面那条走")
                move_m = (-_mag if _push else _mag) * _u3
                deep = float(mm["ds"])                              # 沿轴差（<0 = 进太深）
                axis_phase = False
                _seg_txt = "缝（沿 −u 推出去 → 4 号）" if _push else "缝（沿 +u 拉回来 → 4 号）"
            # **这一步走哪一维、往哪个方向，摆在日志里。** 方向按**实际派上去的那个关节**
            # 现算（`_joint_dir_xy`，只多一次串口读）；原来写死算 1 号的切向 —— 2026-10-17
            # 两段对调之后，那行会一边指着 1 号、一边让 4 号去动，读数跟动作对不上。
            _dir_req = move_m / max(float(np.linalg.norm(move_m)), 1e-12)
            _free_now = _ax_free() if axis_phase else _gap_free()
            _who = int(_free_now[0]) if _free_now else -1
            try:
                _q_now = np.array(arm._ticks_to_qpos(arm.read_ticks()), dtype=np.float64)
                _d0, _mm0 = _joint_dir_xy(arm, _q_now, _who)
            except Exception:                                       # noqa: BLE001
                _d0, _mm0 = None, 0.0
            _cos1 = 0.0 if _d0 is None else float(_dir_req @ _d0)
            print(f"    ⇢ 这一段走「{_seg_txt}」：({_dir_req[0]:+.2f}, {_dir_req[1]:+.2f})，"
                  f"合爪轴 u=({_u3[0]:+.2f}, {_u3[1]:+.2f})")
            if _d0 is not None:
                print(f"       {_who + 1} 号能走的方向 ({_d0[0]:+.2f}, {_d0[1]:+.2f})，"
                      f"夹角 {np.degrees(np.arccos(np.clip(_cos1, -1.0, 1.0))):.0f}°，"
                      f"cos = {_cos1:+.2f}（{_mm0:.2f}mm/度）"
                      + ("  ← 几乎出不上力" if abs(_cos1) < 0.5 else ""))
            err = float(np.linalg.norm(move_m)) * 1000.0            # 毫米
            axis_dir = np.asarray(last.get("axis_dir_px", (1.0, 0.0)), dtype=np.float64)
            n_hat = np.array([-axis_dir[1], axis_dir[0]], dtype=np.float64)
            seg_axis = seg_gap = dp = None
        else:
            # ---- **分两段走：先退干净，再对轴**（2026-10-16 用户定）----
            # 原来两条误差加在一起一次走：垂直那条（`n_hat`）把中心拉回轴上、沿轴那条
            # （`axis_dir`）把缝退到门槛外。**在画面上这两条是反方向的** —— 爪轮廓占
            # y 285~420，合爪轴 y 388.5 横穿它，把方块中心拉回轴上就是把方块往轮廓里塞。
            # 第一眼实测（`out/clear_step.json` 2026-10-16）：轴差 67 像素要求往上冲、
            # 缝只差 9.6 像素要求往左挪，合起来就是「往上冲 67 像素」—— 用户的判词是
            # 「你在左右偏移太少了，你需要把爪子轮廓完整移出去」。
            # 所以：`gap_exit`（整块红区退出去还要多少像素）没清掉之前，**这一趟只走
            # 横向、一点不追轴**；清掉了，才去把中心拉回轴上。
            axis_dir = np.asarray(last["axis_dir_px"], dtype=np.float64)
            n_hat = np.array([-axis_dir[1], axis_dir[0]], dtype=np.float64)
            gap_exit = float(last.get("gap_exit") or 0.0)
            # **缝的目标是一条带，不是「越远越好」**（见 `_gap_need_px`）：缝大于上限时返回
            # **负值**，把方块拉回两爪之间；小于下限才照老的往外推。
            need_gap = _gap_need_px(float(last["gap"]), gap_exit)
            seg_axis = np.zeros(2, dtype=np.float64)
            seg_gap = np.zeros(2, dtype=np.float64)
            if axis_only:
                # **只走轴偏那一维**（用户 2026-10-16「其他方向不能动」）：沿合爪轴那一段
                # 一律写 0，不管缝差多少 —— 下探之后沿这条轴挪就是拿爪面怼方块。
                seg_axis = (-float(last["axis"])) * n_hat
                axis_phase = True
            elif _gap_leaving(need_gap):
                # 带开着的时候「缝超出上限」（`need_gap < 0`）也走这一段 —— 那一步是**把
                # 方块拉回两爪之间**，跟往外推是同一根轴、只是方向相反。
                seg_gap = need_gap * axis_dir
                axis_phase = False
            else:
                seg_axis = (-float(last["axis"])) * n_hat
                axis_phase = True
            dp = seg_axis + seg_gap
            err = float(np.linalg.norm(dp))                         # 像素
            deep = None

        if prev is not None:
            flat = flat + 1 if err >= prev["err"] - 0.5 else 0
            if CLEAR_3D_ENFORCE:
                # 这一步把沿轴压过头了（`ds < 0` 还在往下走）→ 把步子压下来
                if deep < 0.0 and deep < float(prev["ds"]):
                    gain *= CLEAR_CONTACT_GAIN
                    print(f"    ⚠ 上一步把沿轴压过头了（沿轴差 {float(prev['ds']) * 1000:+.1f} → "
                          f"{deep * 1000:+.1f}mm）—— 步子压到 {gain:.2f} 倍")
            else:
                # ---- 实测响应：TCP 实际走的毫米 ↔ 画面里方块中心实际动的像素 ----
                dx = tcp[:2] - prev["tcp"][:2]
                if float(np.linalg.norm(dx)) > 2e-4:
                    dy = box_uv - prev["box_uv"]
                    B = B + np.outer(dy - B @ dx, dx) / float(dx @ dx)  # Broyden
                    b_src = "实测的"
                # 这一步把缝压到**下限以下**、还在掉 → 把步子压下来（爪面在往方块里挤）
                if (last["gap"] < prev["gap"]
                        and last["gap"] < (CLEAR_BAND_LO_PX if CLEAR_BAND_ON
                                           else CLEAR_TARGET_PX)):
                    gain *= CLEAR_CONTACT_GAIN
                    print(f"    ⚠ 上一步把缝压回带里以下了（缝 {prev['gap']:+.0f} → "
                          f"{last['gap']:+.0f} 像素）—— 步子压到 {gain:.2f} 倍")

        if CLEAR_FLAT_STOP is not None and flat >= CLEAR_FLAT_STOP:
            print(f"    ✗ 连着 {flat} 眼误差不再变小（还差 {err:.1f}"
                  f"{'mm' if CLEAR_3D_ENFORCE else ' 像素'}）—— 这一趟不合爪，退回去")
            return {**last, "ok": False, "why": "微调不再收敛", "tries": n,
                    "pixel": not CLEAR_3D_ENFORCE}
        if CLEAR_3D_ENFORCE:
            # **响应矩阵那套不走了**：残差本身就是毫米，`delta` 直接就是该走多少，
            # 不用再拿「TCP 走1mm ↔ 画面动多少像素」换算、也不用 Broyden 学。
            step_xy = move_m * gain
        else:
            if B is None:
                jac = _px_per_mm(cam, center)
                if jac is None:
                    print("    ✗ 投不出像素/毫米（这一步该往哪走算不出来）—— 无法微调，不合爪")
                    return {**last, "ok": False, "why": "投不出像素/米", "tries": n,
                            "pixel": True}
                B = -jac
            try:
                step_xy = np.linalg.solve(B, dp) * gain
            except np.linalg.LinAlgError:
                print("    ✗ 实测出来的响应矩阵是退化的（这一步该往哪走算不出来）—— 不合爪")
                return {**last, "ok": False, "why": "响应矩阵退化", "tries": n, "pixel": True}
        # **一步走多长：由「至少让关节动 `CLEAR_MIN_JOINT_DEG` 度」定**（用户 2026-10-16
        # 「你应该定最小舵机度数」）。方向照算出来的，长度从 `CLEAR_STEP_M` 起算：这么长
        # 就够最小度数就按它走，不够就往长里解，一直解到最大的那个自由关节至少动
        # `CLEAR_MIN_JOINT_DEG` 度（上限 `CLEAR_MIN_DEG_GAIN_MAX` 倍）。
        _nrm0 = float(np.linalg.norm(step_xy))
        # **下面 `_free_for` 补进来的关节要一路带到 `_goto`。** 2026-10-17 那趟日志里
        # 「补 3 号进来（3.78mm/度）」算出来了，可真正走位那一步还是按 `_gap_free()`
        # 只放 1 号 —— 补的人根本没上场。这里先占个位，够不着的地方退回写死的那两组。
        _free_step = None
        if _nrm0 > 1e-9:
            _dir = step_xy / _nrm0
            # **这一维谁走得动就放谁**（`_free_for`）：底座那一维出不上力时补一个关节
            # 进来。写死的那两组（`FREE_GAP` / `FREE_AXIS`）现在是「首选」，不再是唯一。
            _free_step = _free_for(arm, (_dir_req if CLEAR_3D_ENFORCE else None),
                                   _ax_free() if axis_phase else _gap_free())
            _len = min(_nrm0, CLEAR_STEP_M)
            _deg, _j, _dz = 0.0, -1, 0.0
            for _ in range(4):
                _deg, _j, _dz = _step_min_deg(
                    arm, np.array([tcp[0] + _dir[0] * _len,
                                   tcp[1] + _dir[1] * _len, z0], dtype=np.float64),
                    _free_step)
                _next = _len
                if 1e-6 < _deg < CLEAR_MIN_JOINT_DEG:
                    _next = min(_len * (CLEAR_MIN_JOINT_DEG / _deg),
                                _nrm0 * CLEAR_MIN_DEG_GAIN_MAX)
                # **这一挪要掉多少高度，也进同一条算式。** 补进来的 2/3 号是竖直面里
                # 走弧的，横移的同时高度会跟着掉；不把它算进来，步子照横移量定、臂一边
                # 横移一边往下沉（上一趟横移完掉了 16.8mm）。掉得超过 `CLEAR_STEP_DZ_M`
                # 就把长度按比例压回来 —— 宁可这一趟少挪一点，也不拿高度换横移。
                if abs(_dz) > CLEAR_STEP_DZ_M > 0.0:
                    _next = min(_next, _len * (CLEAR_STEP_DZ_M / abs(_dz)))
                # **压缩要真的写回去。** 这个循环原来只会「往长里解」：`_next <= _len`
                # 直接 break，而 break 之前没把 `_len` 换成 `_next` —— 于是新加的压缩
                # 分支算出来 11.23mm、4.55mm 高度，写下去的仍是没压过的那一版
                # （2026-10-17 那趟日志：每步都印「带下来的高度 +4.55mm（上限 3.0）」
                # 却照走 11.23mm）。先处理压缩，再处理放大。
                if _next < _len * 0.99:
                    _len = _next
                    continue
                if _next <= _len * 1.01:        # 够了，或者乘不上去了：这一轮的 _deg 就是它
                    break
                _len = _next
            step_xy = _dir * _len
            print(f"    ⤢ 算出来该走 {_nrm0 * 1000:.2f}mm —— 这一步走 "
                  f"{_len * 1000:.2f}mm（{_j + 1} 号舵机要动 {_deg:.2f}°，"
                  f"至少要 {CLEAR_MIN_JOINT_DEG:.1f}°），带下来的高度 "
                  f"{_dz * 1000:+.2f}mm（每步上限 {CLEAR_STEP_DZ_M * 1000:.1f}mm），"
                  f"方向不变")
        # **闸口开着就别在这儿判死**（用户 2026-10-16：「断点上我说怎么移就怎么移」）。
        # 原来这条在闸口前面：算出来不足 0.5mm 当场判失败退回去，人连一眼都看不到 ——
        # 而这恰恰是最该让人接手的一刻（`out/run_real_73.log` 第 63 行就是这么结束的）。
        # 闸口开着就放它过去，等人在断点上给位移；人给 `go` 就是他自己要这一小步。
        if (float(np.linalg.norm(step_xy)) < CLEAR_MIN_STEP_M
                and not _confirm_step_on()):
            print(f"    ✗ 该走的这一步只剩 {float(np.linalg.norm(step_xy)) * 1000:.2f}mm"
                  f"（还差 {err:.1f}"
                  f"{'mm' if CLEAR_3D_ENFORCE else ' 像素'} 没进带里）—— 这一趟不合爪，退回去")
            return {**last, "ok": False, "why": "这一步不足 0.5mm", "tries": n,
                    "pixel": not CLEAR_3D_ENFORCE}
        if float(np.linalg.norm(step_xy)) < CLEAR_MIN_STEP_M:
            print(f"    ⚠ 算出来的这一步只剩 {float(np.linalg.norm(step_xy)) * 1000:.2f}mm"
                  f"（还差 {err:.1f} 像素 没进带里）—— 闸口开着，等你给位移")
        tgt = np.array([tcp[0] + step_xy[0], tcp[1] + step_xy[1], z0], dtype=np.float64)
        if CLEAR_3D_ENFORCE:
            # 画给人看的那支红箭头：这一步落到画面里等于把方块中心挪这么多像素。
            jac_draw = _px_per_mm(cam, seed3d) if cam is not None else None
            dp = None if jac_draw is None else (-jac_draw) @ step_xy
            print(f"    ➜ 该走 ({step_xy[0] * 1000:+.1f}, {step_xy[1] * 1000:+.1f})mm"
                  f"（离轴还差 {mm['p'] * 1000:+.1f}、沿轴还差 {mm['ds'] * 1000:+.1f}mm，"
                  f"容 ≤{CLEAR_3D_TOL_MM:.0f}；步子 {gain:.2f} 倍 × 冻住的中心 + FK 合爪轴）"
                  f"，到 {np.round(tgt * 1000, 1)}mm"
                  f"（z 钉在 {z0 * 1000:+.1f}、刚刚读回来 {tcp[2] * 1000:+.1f}，爪张着）再量一眼")
        else:
            print(f"    ➜ 该走 ({step_xy[0] * 1000:+.1f}, {step_xy[1] * 1000:+.1f})mm"
                  f"（方块中心在画面里该挪 ({dp[0]:+.0f}, {dp[1]:+.0f}) 像素、还差 {err:.0f}；"
                  f"其中轴偏还差 {last['axis']:+.0f}、缝还差 "
                  f"{_gap_want_px() - float(last['gap']):+.0f}，"
                  f"步子 {gain:.2f} 倍 × {b_src}响应）"
                  f"，到 {np.round(tgt * 1000, 1)}mm"
                  f"（z 钉在 {z0 * 1000:+.1f}、刚刚读回来 {tcp[2] * 1000:+.1f}，爪张着）再量一眼")
        prev = {"err": err, "box_uv": box_uv, "tcp": tcp, "ds": deep,
                "gap": None if last.get("gap") is None else float(last["gap"]), "B": B}
        # 逐步点头那一路（`PICK_CONFIRM_STEP=1`）：走之前把这一步画出来、摆出去、等点头。
        # **只开 `PICK_CONFIRM`（合爪那一步）时，断点照写、但不等人** —— 断点是「停下来
        # 也能接上」的那一半，跟「要不要停」不是一回事（`--resume-pick` 靠它）。
        over_mv = None          # 外面在闸口给的位移（给了就不走轴偏那套放大）
        if _confirm_on() or _confirm_step_on():
            # **断点写在等点头之前。** 进程停在这一刻被 kill（改代码、手滑、换班），盘上
            # 那份就是「这一眼 + 还没走的这一步」的状态，下一次带 `--resume-pick` 从这儿接。
            _save_checkpoint({
                "why": "合爪前微调停在等你点头（盘上写的就是这一眼）",
                # **这一趟是哪种微调**：`False` = 下探之前那趟（两段都走），`True` = 下探
                # 之后那趟（只修轴偏）。续跑要看它，不然会在抓取高度上按两段走一遍。
                "axis_only": bool(axis_only),
                "instruction": instruction, "tag": tag, "ctx": ctx,
                "center": [float(v) for v in np.asarray(center).reshape(-1)],
                "guess": [float(v) for v in np.asarray(seed3d).reshape(-1)],
                "clear": float(clear),
                # **臂的姿态**：续跑认不认领就看这一串（`_arm_off_checkpoint`）。
                "angles": [float(v) for v in np.asarray(arm.angles()).reshape(-1)],
                "tcp": [float(v) for v in tcp.reshape(-1)],
                "z0": float(z0), "gain": float(gain), "tries": int(n), "flat": int(flat),
                # 响应矩阵那套在 3D 那条尺子上不用（`B` 就是 None）；照实写进去，续跑
                # 那一趟也照实读回来。
                "B": None if B is None else np.asarray(B).tolist(),
                "prev": {"err": float(err), "tcp": tcp.tolist(), "ds": deep,
                         "box_uv": None if box_uv is None else box_uv.tolist(),
                         "gap": None if last.get("gap") is None else float(last["gap"])},
                "look": {"gap": None if last.get("gap") is None else float(last["gap"]),
                         "axis": None if last.get("axis") is None else float(last["axis"]),
                         "along": None if last.get("along") is None else float(last["along"]),
                         "box_uv": None if box_uv is None else box_uv.tolist(),
                         "frozen_mm": [float(v) * 1000 for v in frozen3d.reshape(-1)],
                         "mm_p": float(mm["p"]) * 1000, "mm_ds": float(mm["ds"]) * 1000,
                         "tol_mm": CLEAR_3D_TOL_MM,
                         "step_mm": [float(step_xy[0]) * 1000, float(step_xy[1]) * 1000],
                         "tgt_mm": [float(v) * 1000 for v in np.asarray(tgt).reshape(-1)]},
            })
            # `mm` 只在**它拦门的时候**往下传。拦门的换回画面之后，`mm` 是这一眼现量的 3D
            # （不是冻住的那个），印出来会被读成「冻住的那个中心离轴差多少」—— 标签和数
            # 对不上，比不印更坏（`out/run_real_63.log` 第 44 行就是这么错的）。
            if _confirm_step_on():
                ok_step, over = _confirm_step(
                    last, dp, seg_axis, seg_gap, step_xy, tgt, gain, z0, n,
                    mm=mm if CLEAR_3D_ENFORCE else None)
                if not ok_step:
                    return {**last, "ok": False, "why": "微调等点头时没走成", "tries": n,
                            "pixel": not CLEAR_3D_ENFORCE}
                if over is not None:
                    if over[0] == "descend":
                        # **闸口收工**：不再 `_goto`、不再重量一眼，直接把这一趟判过，
                        # 让外面照冻住的那个中心去走竖直下探那一截（`_descend_to_grasp`）。
                        return {**last, "ok": True, "why": "闸口叫直接下探", "tries": n,
                                "pixel": not CLEAR_3D_ENFORCE}
                    # **外面给的位移顶掉算出来的那一步**（用户 2026-10-16）。不给 `dz` 时
                    # z 照旧钉在 `z0`；给了就**连 `z0` 一起改** —— 后面每一眼都钉在新的
                    # 那一档，不然下一眼立刻弹回旧高度，等于没下。
                    tcp_ov = np.asarray(arm.tcp(), dtype=np.float64)
                    dz = over[2] if len(over) > 2 else None
                    if over[0] == "abs":
                        tgt = np.array([over[1], over[2], z0], dtype=np.float64)
                    else:
                        tgt = np.array([tcp_ov[0] + over[0], tcp_ov[1] + over[1], z0],
                                       dtype=np.float64)
                    if dz is not None:
                        tgt[2] = float(tcp_ov[2]) + float(dz)
                        z0 = float(tgt[2])
                        print(f"    钉住的那一档高度改成 {z0 * 1000:+.1f}mm")
                    print(f"    走到 {np.round(tgt * 1000, 1)}mm（外面给的那一步）")
                    over_mv = over
        # ---- 轴偏那一段：**按算出来的 1 倍走，不冲不退**（用户 2026-10-16：「不准多补偿」）----
        # 原来这里是「10 倍冲过去、8 倍退回来」（净 2 倍）。现在默认关掉了：一步只走一下。
        # 要退回 10/8 那条路就设 `PICK_AXIS_AMP=1`。
        import os as _os                                             # noqa: PLC0415

        _amp_on = _os.environ.get("PICK_AXIS_AMP", "").strip().lower() in (
            "1", "true", "yes", "on")
        if axis_phase and over_mv is None and not _amp_on:
            _t = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
            one = np.array([_t[0] + step_xy[0], _t[1] + step_xy[1], z0], dtype=np.float64)
            print(f"    轴偏这一段：1 倍走一下 ({np.round(one * 1000, 1)}mm)")
            # **一步只准动一下，无关的关节一个都不许松**：只解 4 号（`_ax_free()`）、
            # 只走一趟（`tries=1`）、夹爪那一维也照此刻的读数写回去（`grip=None`）。
            _goto(arm, one, vmax=speed_vmax(SLOW), grip=None, free=_ax_free(), tries=1)
        elif axis_phase and over_mv is None:
            tcp_a = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
            net = CLEAR_AXIS_FAR - CLEAR_AXIS_BACK                   # 净 2 倍
            if float(np.linalg.norm(step_xy)) * net * 1000.0 > CLEAR_AXIS_AMP_MAX_MM:
                # 净走 >15mm：不冲不绕，一步走到 2 倍。
                two = np.array([tcp_a[0] + net * step_xy[0],
                                tcp_a[1] + net * step_xy[1], z0], dtype=np.float64)
                print(f"    轴偏这一段：净 {net:.0f} 倍已超过 {CLEAR_AXIS_AMP_MAX_MM:.0f}mm，"
                      f"直接走 {net:.0f} 倍 ({np.round(two * 1000, 1)}mm)")
                _goto(arm, two, vmax=speed_vmax(SLOW), grip=1.0, free=_ax_free())
            else:
                amp = np.array([tcp_a[0] + CLEAR_AXIS_FAR * step_xy[0],
                                tcp_a[1] + CLEAR_AXIS_FAR * step_xy[1], z0], dtype=np.float64)
                print(f"    轴偏这一段：先走 {CLEAR_AXIS_FAR:.0f} 倍 ({np.round(amp * 1000, 1)}mm)")
                _goto(arm, amp, vmax=speed_vmax(SLOW), grip=1.0, free=_ax_free())
                tcp_b = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
                back = np.array([tcp_b[0] - CLEAR_AXIS_BACK * step_xy[0],
                                 tcp_b[1] - CLEAR_AXIS_BACK * step_xy[1], z0], dtype=np.float64)
                print(f"    再退回来 {CLEAR_AXIS_BACK:.0f} 倍 ({np.round(back * 1000, 1)}mm)"
                      f" —— 净 {net:.0f} 倍")
                _goto(arm, back, vmax=speed_vmax(SLOW), grip=1.0, free=_ax_free())
        else:
            # 外面在闸口给的位移**也是微调里的位移**，照旧守着这一段该放哪几个关节（用户
            # 2026-10-16 定的 4 号 / 1+5）。只有连高度（`dz`）一起动的时候才整只臂放开
            # —— 高度那两维不是 1、5 号碰得到的。（`abs` 那条的第三个数是 y 不是 dz，
            # 所以排掉它。）
            _dz_given = (over_mv is not None and len(over_mv) > 2
                         and over_mv[0] != "abs" and over_mv[2] is not None)
            # **轴偏这一段：一步只准动一下**（`tries=1`，不重解、不补第二趟），
            # 夹爪那一维也不碰（`grip=None` = 照此刻读数写回去）。
            _goto(arm, tgt, vmax=speed_vmax(SLOW),
                  grip=(None if axis_phase else 1.0),
                  free=(None if _dz_given
                        else (_free_step if _free_step is not None
                              else (_ax_free() if axis_phase else _gap_free()))),
                  tries=(1 if axis_phase else None))
        # **横移完高度掉了就掉了，不再抬回来**（用户 2026-10-16：「以后不抬高度」）。
        # 原来这里见 `tcp_now[2] < z0` 就走一趟竖直抬回 `z0` —— 那一步从 run 70/71 起不收敛
        # （第一趟无论要抬多少都往下掉约 1.1mm；放大后 3 号顶到 10° 以上就是重摆整条臂，
        # 竖冲 11~16mm、横甩 25~34mm，冲上去又受重力落回来，如此循环）。代偿改成下探时就多留
        # 10mm（`GRASP_Z_MARGIN_REAL`），横向让开时爪尖本来就碰不到方块顶面。
        # 这一档只留观测：掉了多少照打，不动臂。
        tcp_now = np.asarray(arm.tcp(), dtype=np.float64)
        if tcp_now[2] < z0 - CLEAR_Z_KEEP_M:
            print(f"    ⚠ 横移完高度掉了 {(z0 - tcp_now[2]) * 1000:.1f}mm"
                  f"（读到 {tcp_now[2] * 1000:+.1f}mm、该 ≥{z0 * 1000:+.1f}mm）"
                  f" —— 按用户 2026-10-16 的决定不抬回来，就这么走")
        n += 1


def _look(arm, cams, percep, instruction, guess):
    """看一眼：返回 (中心坐标, 朝向弧度, facts)；量不出来 center 是 None。

    直接走感知那条链（`real/perception.py` 的 `locate`）—— 它里面已经是「挑出棕色块
    → 估形状 → 投剪影」全套，在外面重做一遍等于两套口径。`guess` 传下去当搜索种子。
    """
    center, facts = percep.locate(instruction, guess=guess)
    print(f"      找到 {facts.get('found')}  矩形度 {facts.get('rect_fill')}"
          f"  重合度 {facts.get('iou')}")
    if center is None:
        why = facts.get("no_world_why") or facts.get("why") or "没认出来"
        print(f"      ✗ {why}")
        return None, None, facts
    return center, float(np.radians(facts["yaw_deg"])), facts


def _sweep(arm, cams, percep, instruction, state):
    """原地那一眼没认出来时，分两段找。

    **第 1 段 · 前后左右。** 就在现在站的地方铺四个点 —— 前、后、左、右，各挪一格，
    格子边长 = 腕相机当前能看清的那个圆的内切半径（`_view_radius` 现算）。这一段走
    `follow`（TCP + 逆解）：它就是平面平移，没有姿态变化。走完回中心再进第 2 段。

    **第 2 段 · 原地抬个头。** 就一个姿态：回到中心之后，1 号 pan 不动，4 号腕关节
    掰到 `SWEEP_HEAD_FLEX`。角度和姿态本身还是 `G:\\sim2real\\so101-real-harness\\real\\sweep_look.py`
    那张表（`poses(pan_deg=(0,), flex_deg=(SWEEP_HEAD_FLEX,))`），只是把范围收成一点。
    掰下去让光轴离开垂直方向，桌面落点跟着往外推几十厘米 —— 腕相机正下方只看得见约
    0.33m × 0.18m 一块，横移范围只有 ±0.18m，**掰腕子是唯一还能把视野推出这块地板的
    杠杆**。走之前先算好相机在哪、光轴打桌面哪一点（日志里打出来），并过一道安全带
    （TCP 不许比初始点位低 5mm）。这一段走关节空间，因为掰腕子那类姿态**逆解解不出来**
    （`sweep_look.py` 开头记着实测：解出来的构型是肩抬 -98.9°、抓取点丢 90mm，直接撞限位）。

    两段都是**认出目标就停**。返回 (中心坐标, 朝向弧度, facts)；都没认出来就是
    (None, None, 最后一眼的 facts)。
    """
    facts: dict = {}

    # ---- 第 1 段：前后左右 ----
    base = arm.tcp().copy()
    r = _view_radius(cams, float(base[2]))
    if r is None:
        print("    ！算不出画面在目标那个平面上覆盖多大，前后左右这一步跳过")
    else:
        print(f"    前后左右：一格 {r * 1000:.0f}mm（画面内切圆的半径），从"
              f"{np.round(base[:2] * 1000, 0)} 出发，四个方向")
        for i, (du, dv) in enumerate(SWEEP_4, 1):
            cand = base + np.array([du * r, dv * r, 0.0])
            way = SWEEP_WAY[(du, dv)]
            if geom.out_of_reach(cand[:2]):
                print(f"    · {way}（到 {np.round(cand[:2] * 1000, 0)}）"
                      f"出了可达环，够不着，跳过")
                continue
            state.seg = f"前后左右找目标（{i}/{len(SWEEP_4)}）"
            got = _goto(arm, cand, vmax=speed_vmax(SPEED))
            if got == "term":
                print(f"    ！时间上限掐到了（往{way}那一步），前后左右中断")
                return None, None, facts
            if got != "reached":
                print(f"    · 往{way}（到 {np.round(cand[:2] * 1000, 0)}）"
                      f"没走到（{got}），跳过")
                continue
            print(f"    ↻ 往{way}挪了一格，到 {np.round(arm.tcp()[:2] * 1000, 0)}，"
                  f"再看一眼")
            center, yaw, facts = _look(arm, cams, percep, instruction, None)
            if center is not None and yaw is not None:
                return center, yaw, facts
        # **回中心再抬头。** 不回的话第 2 段是从某个偏出去的点起算的，抬头推出去的
        # 视野方向也跟着偏 —— 覆盖哪一片就说不清了。
        if float(np.linalg.norm(arm.tcp()[:2] - base[:2])) > 1e-4:
            print(f"    回中心 {np.round(base[:2] * 1000, 0)} 再进第二段")
            _goto(arm, base, vmax=speed_vmax(SPEED))

    # ---- 第 2 段：原地抬个头 ----
    from real import joint_move as jm                              # noqa: PLC0415
    from real.sweep_look import poses                              # noqa: PLC0415

    # **就一个姿态**：pan 不动，4 号腕关节掰到底。表还是 `sweep_look.py` 那张表，只是
    # 把范围收成一点（`poses` 本来就吃 `pan_deg` / `flex_deg`），不另抄一份。
    grid, dropped = poses(arm, pan_deg=(0.0,), flex_deg=(SWEEP_HEAD_FLEX,))
    if grid is None:
        print("    ！模型里没有 `wrist_cam`，算不出相机朝哪，抬头这一步做不了")
        return None, None, facts
    if not grid:
        print(f"    ！4 号掰到 {SWEEP_HEAD_FLEX:+.0f}° 之后 TCP 比初始点位低，"
              f"被安全带滤掉了，不抬")
        return None, None, facts

    p = grid[0]
    state.seg = "原地抬头拉远"
    aim = "" if p["hit"] is None else (
        f"，光轴落桌面 {p['hit'][0] * 1000:+.0f},{p['hit'][1] * 1000:+.0f}mm")
    print(f"    ↻ 原地抬头：4 号掰到 {p['flex']:+.0f}°{aim}，再看一眼")
    jm.goto_q(arm, p["q"], q_from=arm._ticks_to_qpos(arm.read_ticks()))
    if getattr(arm, "terminated", False):
        print("    ！时间上限掐到了，抬头这一步没看成")
        return None, None, facts
    center, yaw, facts = _look(arm, cams, percep, instruction, None)
    return center, yaw, facts


def _wrist_turn(arm, deg: float) -> float:
    """**只拧 5 号**（wrist_roll）`deg` 度，走关节空间绝对角。返回实际拧了多少度。

    `real/joint_move.goto_q` 提前把整条轨迹算好、一路写绝对角、中途不读 —— 跟
    `_goto` 同一个机制。其它五个关节原样写回去，所以这一步不动位置、只转腕子。
    5 号自己的行程从 MJCF 的 `jnt_range` 读，不另抄一份数。
    """
    from real import joint_move as jm                               # noqa: PLC0415
    from real.arm import JOINT_ORDER                                # noqa: PLC0415

    idx = list(JOINT_ORDER).index("wrist_roll")
    q0 = np.array(arm._ticks_to_qpos(arm.read_ticks()), dtype=np.float64)
    q = q0.copy()
    q[idx] = float(np.clip(q0[idx] + np.radians(float(deg)),
                           arm.q_lo[idx], arm.q_hi[idx]))
    d = float(np.degrees(q[idx] - q0[idx]))
    if abs(d) < 1e-6:
        return 0.0
    jm.goto_q(arm, q, q_from=q0)
    return d


def _align(arm, closing, grip=-1.0, cam=None, percep=None) -> tuple[int, float]:
    """原地把腕子转到开合轴对上盒子侧面。返回 (动了几个动作, 转完还差几度)。

    `grip=-1.0`：转正时爪子合着（同 `_goto`）。

    **2026-10-17 换做法。** 原来走 `follow.hold` 那条笛卡尔闭环：每 10 步把「腕子该朝哪」
    交给逆解，让 `drive` 一边压位置一边压姿态。实测三趟（改判据、改参考点、去掉步数上限）
    **一次都没转过去** —— 每趟都跑满 200 步、读数原地不动，模型和画面两条尺子都说没对上。
    位置被钉住的时候，那条路给不出纯旋转。

    现在直接走**关节空间纯旋转 + 画面闭环**：

      1. 先拧 `ALIGN_PROBE_DEG` 度，看模型那条是涨是落 → 定方向。
      2. 一次拧 |差|，单次不超过 45°（`align_action` 那条也在 45° 附近才稳）。
      3. 重复，直到 |差| ≤ `ALIGN_TOL_DEG`，最多 `ALIGN_MAX_MOVES` 趟。**不设步数上限。**

    画面那条量不出来（没相机 / 没色块）才退回模型那条，老口径一字不改。

    **2026-10-17 第二次改：判据换成模型那条。** 上一趟画面这条报「还差 1.0°」，模型那条
    同一时刻报 85.4°，于是转正一步没拧就放行；下探按 `closing` 锁姿态，5 号要转到
    −157.2°（自己的行程端点）还差 4.3mm，这条列解不出来，一步没走就 stall —— 根本没走到
    微调。差这 85° 不是抖动：`sh.normal` 对长方体取的是**跨度最小那一对**的面（15×29
    这只取短的那一维），画面那条按「矩形两条边差 90° 等价」折掉了这一层，所以「贴着长边」
    和「贴着短边」在它眼里都是 0°。**下探和落点用的就是模型这条**，这里就得跟它一条。
    """
    base = np.asarray(closing, dtype=np.float64).copy()

    def _model() -> float | None:
        v = _align_deg(arm, base)
        return None if v is None else float(v)

    cur = _model()
    if cur is None:
        return _align_model(arm, closing, grip)
    if cur <= ALIGN_TOL_DEG:
        return 0, cur

    # `_align_deg` 是 arccos，只给 0~180，**不带正负** —— 方向当场试探一次再定。
    moves = 0
    sign = 1.0
    probe = _wrist_turn(arm, ALIGN_PROBE_DEG)
    moves += 1
    if abs(probe) < 1e-6:                          # 5 号一开始就在行程头上
        return moves, cur
    nxt = _model()
    if nxt is None:
        return moves, cur
    if nxt > cur + 0.3:                            # 越拧越远 = 方向反了
        sign = -1.0
    best = min(cur, nxt)

    for _ in range(ALIGN_MAX_MOVES):
        cur = _model()
        if cur is None:
            break
        if cur <= ALIGN_TOL_DEG:
            return moves, cur
        got = _wrist_turn(arm, sign * float(np.clip(cur, -45.0, 45.0)))
        moves += 1
        if abs(got) < 1e-6:                        # 5 号顶到行程头
            break
        nxt = _model()
        if nxt is None:
            break
        if nxt > cur + 0.5:                        # 这一步拧反了，下一趟掉头
            sign = -sign
        elif nxt > cur - 0.5:                      # 拧了不动：到头了
            break
        if nxt < best:
            best = nxt
    cur = _model()
    return moves, (float("nan") if cur is None else cur)


def _align_model(arm, closing, grip=-1.0) -> tuple[int, float]:
    """老口径：模型里的 `tool_x` 对着 `closing`，笛卡尔闭环。画面那条量不出来时用。"""
    hold_at = arm.tcp().copy()
    base = np.asarray(closing, dtype=np.float64).copy()

    def _rot(deg: float) -> np.ndarray:
        c, s = np.cos(np.radians(deg)), np.sin(np.radians(deg))
        return np.array([[c, -s, 0.0], [s, c, 0.0], [0.0, 0.0, 1.0]]) @ base

    prev = None
    for k in range(0, ALIGN_MAX_STEPS, ALIGN_CHUNK):
        left = _align_deg(arm, base)
        if left is not None and left <= ALIGN_TOL_DEG:
            return k, left
        prev = left
        tgt = base if prev is None else _rot(float(prev))
        follow.hold(arm, ALIGN_CHUNK, grip=grip, closing=tgt, at=hold_at,
                    pos_slew=POS_SLEW, rot_slew=ALIGN_ROT_SLEW)
    left = _align_deg(arm, base)
    return ALIGN_MAX_STEPS, (float("nan") if left is None else float(left))


def _grip_hold(arm, state) -> float:
    """夹住之后给的那一维指令：恒定合爪一份，再按「被撑开多少」补回来。

    为什么不能给 0 见 `core/params.GRIP_BIAS`；开口为什么有下限见 `GRIP_SLACK`。
    在真机上多一层意思：这一维是**增量**，给 0 等于零刚度，舵机只是停在那个位置
    不出力，盒子靠自重就能滑下去。
    """
    ref = state.grip_ref
    if ref is None:
        return 0.0
    q = float(arm.grip_q())
    if q < ref - GRIP_SLACK:
        return GRIP_BIAS                       # 已经比下限更紧了：松回去，别再往里挤
    return float(np.clip((ref - q) / GRIP_K, -1.0, 0.0)) * GRIP_RATE - GRIP_BIAS


def _close_until_stall(arm, closing, max_steps: int = CLOSE_MAX_STEPS):
    """一小步一小步合爪，压不动了就停。返回 (停因, 事实)。

    仿真那边靠**指垫接触点**判「两边都贴上了、再挤一点就停」。真机没有接触传感，
    只剩夹爪自己的角度：夹爪是位置控制的舵机，嘴里有东西就转不下去，角度会停在某个
    位置上不动 —— 那个「不动了」就是到位置了。

    **但停住这件事本身分不清「夹住盒子」和「自己合到底了」。** 差别只在角度大小上，
    那正是 `grasp_check.classify_ref` 管的事（跟本次实测的空抓基准比）。所以这里只管
    把爪合到停、把角度报出来，**判「夹住没有」交给调用方**，这一段不越权。

    **合爪这一段只让 6 号动（用户 2026-10-16 定）。** 原来每步走的是 `arm.drive`：写一
    个笛卡尔点、六维一起解逆解 —— 也就是说 1~5 号每一步都在被重算一遍，位置会跟着飘。
    既然这一步已经定了「就是合爪」，那 1~5 号就没有理由再动。现在开头量一次 tick，之后
    每一步把它们**原样写回去**（舵机是位置控制，写同一个位置就是钉住），只推进 6 号。
    """
    from real.arm import GRIP_SCALE as _ARM_GRIP_SCALE                   # noqa: PLC0415

    ticks0 = {int(k): int(v) for k, v in arm.read_ticks().items()}
    q0 = float(arm.grip_q())
    arm._grip_cmd = float(np.clip(q0, arm.grip_lo, arm.grip_hi))
    q_prev = None
    stuck = 0
    for step in range(1, int(max_steps) + 1):
        q = float(arm.grip_q())
        stuck = stuck + 1 if (q_prev is not None and q > q_prev - 1e-5) else 0
        q_prev = q
        if stuck > STUCK_TOL:
            return "stall", {"steps": step, "q0": q0, "q": q, "why": "压不动了"}
        # 6 号往前推一小步（和 `drive` 里那一维同一个增量、同一个行程夹），其余五个照
        # 开头量到的那串 tick 写回去 —— 一个字节都不挪。
        arm._grip_cmd = float(np.clip(arm._grip_cmd - GENTLE * _ARM_GRIP_SCALE,
                                      arm.grip_lo, arm.grip_hi))
        _qc = arm._ticks_to_qpos(ticks0)
        _qc[5] = arm._grip_cmd
        _write = dict(ticks0)
        _write[6] = int(arm._qpos_to_ticks(_qc)[6])
        arm.write_ticks(_write)
        if arm.terminated:
            return "term", {"steps": step, "q0": q0, "q": float(arm.grip_q()),
                            "why": "到点收工"}
    return "steps", {"steps": int(max_steps), "q0": q0, "q": float(arm.grip_q()),
                     "why": "合爪步数用完（夹爪一直没停过）"}


def _gripper_deg(arm, ctrl):
    """读 6 号舵机角度，**单读失败就退到 `arm` 那条批量同步读**。返回 `(角度 or None, 走哪条)`。

    **为什么要有这一手**（2026-10-16）：`read_gripper_deg` 走 `get_servo_angle`（单舵机
    `INST_READ`，5 次取中位数），5 次全丢包返回 None。而 `out/run_real_1x2.log` 第 101 行
    就是这个情形：合爪 216 步、压不动了，紧接着单读 5/5 全失败 → `classify_ref` 得
    `no-reading` → 代码当场判「没夹住」、退回悬停点，**抬升那一段一步没走**；用户看画面
    说「没空抓啊，抓起来了啊」。

    同一步里 `arm.grip_q()` 走 `sync_read_positions`（一次批量读 6 个）从没丢过。两条读的
    是同一个寄存器、换算同一条式子（`servo_bridge.deg_from_position`），所以可以互相顶替。
    **不改判据、不改阈值** —— 只是把「读不到」这件事从「判失败」拉回「换个读法再读一次」。
    """
    from servo_bridge import deg_from_position, read_gripper_deg        # noqa: PLC0415

    d = read_gripper_deg(ctrl)
    if d is not None:
        return float(d), "单读"
    ticks = arm.read_ticks()
    pos = ticks.get(6)
    if pos is None:
        return None, "两条都读不到"
    return deg_from_position(pos), "arm 同步读（单读丢了）"


# ---- 抓成之后放到哪儿（用户 2026-10-17）----
# 原话：「抓成功之后把方块放到一个随机位置放下，放的时候爪子离地面要有半个边长的距离」。
#
# **随机只在「拾取工位那一圈」里抽。** 真机上没人知道桌子铺到哪，抽到桌子外面就是摔下去；
# 那一圈是已知能干活的地方（`configs/real.yaml` 的 `pick_xy_mm`，方位 20°、半径 200mm），
# 可达环是 130~260mm。所以方位绕着它摆 ±45°、半径收到 170~240mm —— 两头都离环边留了余量。
PLACE_AFTER_PICK = True         # 抓成就摆一趟。关掉 = 只抬起来、不放（回到原来那个行为）
PLACE_DEG_WIN = 10.0            # 落点方位角相对拾取工位允许偏多少度（2026-10-18 用户：左右 10°）
PLACE_R_MIN_M = 0.170           # 落点半径（米，绕肩轴）
PLACE_R_MAX_M = 0.240
PLACE_AWAY_M = 0.060            # 离原来那个位置至少这么远，免得原地放回去
PLACE_SAMPLE_MAX = 200          # 抽不到合条件的就报失败，**不硬放**
PLACE_Z_TOL_MM = 5.0            # 松爪时最低点比「桌面 + 半个边长」**高**过这么多 = 没落下去 → 不松爪
PLACE_OPEN_STEPS = 120          # 张爪最多走多少步


def _place_xy_real(center) -> tuple[np.ndarray, str]:
    """抽一个落点 `(x, y)`（米，基座系）。返回 `(xy, 一句话说明)`。

    **只在拾取工位那一圈里抽**（见上面那组常数的说明）。两个条件：`geom.out_of_reach`
    说够得着、离原来那个位置 ≥ `PLACE_AWAY_M` —— 原地放回去就不叫「随机位置」了。

    抽 `PLACE_SAMPLE_MAX` 次还没抽到就抛，**不硬放**：调用方如实报失败，方块留在爪里。
    """
    import random                                               # noqa: PLC0415
    import time                                                 # noqa: PLC0415

    base = np.asarray(geom.MARKER_CENTER, dtype=np.float64)
    pick = np.asarray(geom.real_pick_xy(), dtype=np.float64).reshape(-1)[:2]
    base_deg = float(np.degrees(np.arctan2(pick[1] - base[1], pick[0] - base[0])))
    seed = int(time.time() * 1000) % 100000
    rng = random.Random(seed)
    now = np.asarray(center, dtype=np.float64).reshape(-1)[:2]
    for _ in range(PLACE_SAMPLE_MAX):
        deg = base_deg + rng.uniform(-PLACE_DEG_WIN, PLACE_DEG_WIN)
        r = rng.uniform(PLACE_R_MIN_M, PLACE_R_MAX_M)
        xy = np.array([base[0] + r * np.cos(np.radians(deg)),
                       base[1] + r * np.sin(np.radians(deg))], dtype=np.float64)
        if geom.out_of_reach(xy):
            continue
        if float(np.hypot(xy[0] - now[0], xy[1] - now[1])) < PLACE_AWAY_M:
            continue
        return xy, (f"方位 {deg:+.0f}°（工位 {base_deg:+.0f}° ±{PLACE_DEG_WIN:.0f}）、"
                    f"半径 {r * 1000:.0f}mm（{PLACE_R_MIN_M * 1000:.0f}~"
                    f"{PLACE_R_MAX_M * 1000:.0f}），种子 {seed}")
    raise RuntimeError(f"抽了 {PLACE_SAMPLE_MAX} 次没抽到合条件的落点"
                       f"（可达环 130~260mm、离原处 ≥{PLACE_AWAY_M * 1000:.0f}mm）")


def _open_gently(arm, max_steps: int = PLACE_OPEN_STEPS):
    """一小步一小步张爪，张到不动了为止。返回 `(停因, 事实)`。

    `_close_until_stall` 同一个形状，方向反过来（`+ GENTLE`）。**不一步给满**：给满那
    一下会把方块推着滑一段（`skills/place.py` 开头记着这条）。1~5 号照开头量到的那串
    tick 原样写回去 —— 松爪这一步只有 6 号该动。

    张到头（舵机停在行程端点）和「被方块挡住」在这里都是「不动了」，**不需要分开** ——
    松爪这一步不判成败，判成败的是松爪**之前**那个高度。
    """
    from real.arm import GRIP_SCALE as _ARM_GRIP_SCALE          # noqa: PLC0415

    ticks0 = {int(k): int(v) for k, v in arm.read_ticks().items()}
    q0 = float(arm.grip_q())
    arm._grip_cmd = float(np.clip(q0, arm.grip_lo, arm.grip_hi))
    q_prev = None
    stuck = 0
    for step in range(1, int(max_steps) + 1):
        q = float(arm.grip_q())
        stuck = stuck + 1 if (q_prev is not None and q < q_prev + 1e-5) else 0
        q_prev = q
        if stuck > STUCK_TOL:
            return "stall", {"steps": step, "q0": q0, "q": q, "why": "张到头了"}
        arm._grip_cmd = float(np.clip(arm._grip_cmd + GENTLE * _ARM_GRIP_SCALE,
                                      arm.grip_lo, arm.grip_hi))
        _qc = arm._ticks_to_qpos(ticks0)
        _qc[5] = arm._grip_cmd
        _write = dict(ticks0)
        _write[6] = int(arm._qpos_to_ticks(_qc)[6])
        arm.write_ticks(_write)
        if arm.terminated:
            return "term", {"steps": step, "q0": q0, "q": float(arm.grip_q()),
                            "why": "到点收工"}
    return "steps", {"steps": int(max_steps), "q0": q0, "q": float(arm.grip_q()),
                     "why": "张爪步数用完（夹爪一直没停过）"}


def _place_real(arm, percep, center, *, grasp_z, state) -> dict:
    """抓成之后：搬到抽出来的落点、**手里最低那一点离桌面半个边长**的那一刻松爪。

    「最低那一点」两样都算、取低的那个：
      · **两个爪尖** —— 现在读（`arm.tcp()` 报的是固定爪尖，动爪可能更低）；
      · **方块下底面** —— 抓那一刻它离 TCP 多远（`center[2] - 半个边长 - grasp_z`），
        抬起来之后这一段跟着走，所以是个常量，不用现量。

    取低的那个，是因为撞桌子的会是它。取「最低点 ≥ 半个边长」这一条同时满足用户那句
    「爪子离地面要有半个边长的距离」—— 方块比爪尖低时爪子只会更高。

    **没落到那个高度就不松爪**（`skills/place.py` 那条规矩：半空撒手是这整个流程里唯一
    无法挽回的错误）。落过头不算问题：那说明方块已经压在桌面上了，松爪正好。
    """
    half = _box_half_m(percep)
    table = geom.real_table_z()
    c0 = np.asarray(center, dtype=np.float64).reshape(-1)[:3]
    try:
        xy, why_here = _place_xy_real(c0)
    except RuntimeError as exc:
        print(f"    ✗ 摆件：{exc} —— 这一趟不放，方块还在爪里")
        return {"ok": False, "why": str(exc)}

    # 手里最低那一点离 TCP 多远（米，负 = 在 TCP 下面）。
    tips0 = arm.tips()
    tcp0 = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
    rel_tips = float(min(float(tips0[0][2]), float(tips0[1][2])) - float(tcp0[2]))
    rel_box = float((float(c0[2]) - half) - float(grasp_z))
    rel_low = float(min(rel_tips, rel_box))
    z_rel = float(table + half - rel_low)
    which = "爪尖" if rel_tips <= rel_box else "方块底"
    print(f"    摆件：落点 ({xy[0] * 1000:.0f}, {xy[1] * 1000:.0f})mm —— {why_here}")
    print(f"      半个边长 {half * 1000:.1f}mm、桌面 {table * 1000:+.1f}mm；"
          f"手里最低的是{which}（离 TCP {rel_low * 1000:+.1f}mm）"
          f" → 松爪时 TCP 要落在 {z_rel * 1000:+.1f}mm")

    state.seg = "摆件：搬过去"
    out = _goto(arm, np.array([xy[0], xy[1], LIFT_Z], dtype=np.float64),
                vmax=speed_vmax(CARRY), grip=None, tol=0.012)
    tcp1 = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
    print(f"      搬过去：{out}  TCP ({tcp0[0] * 1000:+.1f}, {tcp0[1] * 1000:+.1f})"
          f" → ({tcp1[0] * 1000:+.1f}, {tcp1[1] * 1000:+.1f})mm"
          f"  差落点 {float(np.hypot(tcp1[0] - xy[0], tcp1[1] - xy[1])) * 1000:.1f}mm")

    state.seg = "摆件：落下去"
    down = _goto(arm, np.array([xy[0], xy[1], z_rel], dtype=np.float64),
                 vmax=speed_vmax(SLOW), grip=None, tries=1)
    tcp2 = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
    tips2 = arm.tips()
    low = float(min(min(float(tips2[0][2]), float(tips2[1][2])),
                    float(tcp2[2]) + rel_box))
    clear = float(low - table)
    print(f"      落下去：{down}  TCP z {tcp1[2] * 1000:+.1f} → {tcp2[2] * 1000:+.1f}mm"
          f"（要 {z_rel * 1000:+.1f}）；水平 "
          f"({tcp2[0] * 1000:+.1f}, {tcp2[1] * 1000:+.1f})mm")
    print(f"      最低那一点离桌面 {clear * 1000:.1f}mm（要 ≥ {half * 1000:.1f}mm，"
          f"高过 {(half + PLACE_Z_TOL_MM / 1000.0) * 1000:.1f}mm 算没落下去）")
    if clear > half + PLACE_Z_TOL_MM / 1000.0:
        print(f"    ✗ 摆件：没落到半个边长上（离桌面还 {clear * 1000:.1f}mm）—— "
              f"**不松爪**，方块还在爪里，这一趟没摆成")
        return {"ok": False, "why": f"没落到位（最低点离桌面 {clear * 1000:.1f}mm）",
                "at": [float(xy[0]), float(xy[1])]}

    state.seg = "摆件：松爪"
    stop, info = _open_gently(arm)
    print(f"      松爪：{stop}（{info['why']}，{info['steps']} 步）"
          f"  开合角 {info['q0']:+.3f} → {info['q']:+.3f} rad")
    state.held = None
    state.grip_ref = None
    if arm.terminated:
        return {"ok": False, "why": "松爪中途到点收工", "at": [float(xy[0]), float(xy[1])]}

    state.seg = "摆件：退开"
    _goto(arm, np.array([xy[0], xy[1], LIFT_Z], dtype=np.float64),
          vmax=speed_vmax(SLOW), grip=1.0, tol=0.015)
    print(f"    摆件：放好了 —— 落点 ({xy[0] * 1000:.0f}, {xy[1] * 1000:.0f})mm，"
          f"松爪那一刻最低点离桌面 {clear * 1000:.1f}mm"
          f"（半个边长 {half * 1000:.1f}mm，方块从这一档掉到桌上）")
    return {"ok": True, "at": [float(xy[0]), float(xy[1])],
            "clearance_mm": clear * 1000.0, "half_edge_mm": half * 1000.0,
            "z_release_mm": float(tcp2[2]) * 1000.0}


def _close_and_lift(arm, ctrl, cal, state, index, *, grasp_z, empty_deg, open_deg,
                    center, hover, closing, percep=None) -> dict:
    """微调过了 → 合爪 → 判夹住没有 → 抬升到搬运高度。

    **两条路共用这一份**：一种是这一趟从头走完的（`PickRealSkill.run`），一种是从断点
    接上的（`PickRealSkill._resume_pick`，见文件头 `CHECKPOINT` 那一段）。判据、日志、
    返回的字段一个字不差，差别只在**进来之前那几步**走没走。

    参数全是前面算出来的：`center` 盒子中心、`hover` 悬停点（没夹住时退到这儿）、
    `closing` 合爪轴、`grasp_z` 下探停在哪、`empty_deg`/`open_deg` 这一趟的夹爪行程两端。
    **行程两端带上、不在这儿重量** —— 这时候两个爪子正夹在方块两侧，合一次空爪就是拿
    爪去夹方块。
    """
    from grasp_check import GraspMonitor, classify_ref                   # noqa: PLC0415
    from servo_bridge import read_gripper_deg                            # noqa: PLC0415

    # ---- 6. 合爪：合到压不动，再拿角度判夹住没有 ----
    state.seg = "合爪"
    stop, info = _close_until_stall(arm, closing)
    grip_deg, _src = _gripper_deg(arm, ctrl)
    verdict = classify_ref(grip_deg, empty_deg, cal, open_deg)
    print(f"    合爪：{stop}（{info['why']}，{info['steps']} 步）"
          f"  开合角 {info['q0']:+.3f} → {info['q']:+.3f} rad"
          f"  6 号舵机 {grip_deg if grip_deg is None else f'{grip_deg:.1f}°'}（{_src}）"
          f"  → 判 {verdict}")
    if verdict != "held":
        # **光看角度分不清「夹空了」和「压根没动」—— 两者都停在基准附近。**
        # 分得开的是**开口变没变**：真合爪是「从张开一路合过来」，`q` 离 `q0` 很远；
        # 一动没动说明舵机收到目标位置没出力 —— 最常见是扭矩没使能（`real_home.py`：
        # 使能位断电才清，harness 自己不开）。这一条单独报出来，别让人去怀疑盒子。
        didnt_move = abs(float(info["q"]) - float(info["q0"])) < 1e-6
        # 退回去的那一段顺手把爪张开（`grip=1.0`）—— 现在是半合着的，直接横着退，
        # 指垫会贴着盒子侧面一路刮过去。
        _goto(arm, hover, vmax=speed_vmax(SLOW), grip=1.0)
        why = (f"没夹住：开口从头到尾没变过（{info['q0']:+.3f} → {info['q']:+.3f} rad），"
               f"夹爪没动过（扭矩没使能？）" if didnt_move else
               f"没夹住（6 号舵机 {grip_deg}°，空抓基准 {empty_deg:.1f}°，判 {verdict}）")
        return {"ok": False, "why": why,
                "close": info, "grip_deg": grip_deg, "empty_deg": empty_deg,
                "verdict": verdict}

    state.held = index
    state.grip_ref = float(arm.grip_q())
    print(f"    夹住了：开合角 {state.grip_ref:+.3f} rad，"
          f"按这个开口抬升（`_grip_hold` 守着它）")

    # ---- 7. 抬升：守着自己的开口走，全程盯着角度掉没掉 ----
    state.seg = "抬升到搬运高度"
    mon = GraspMonitor(ctrl, cal, samples=3, empty_deg=empty_deg,
                       open_deg=open_deg)
    mon.mark_peak()

    def guard():
        mon.poll()
        return bool(mon.dropped())

    up = follow.follow(arm, [[center[0], center[1], LIFT_Z]],
                       vmax=speed_vmax(CARRY), amax=acc_amax(),
                       grip=lambda: _grip_hold(arm, state), closing=closing,
                       final_tol=0.012, guard=guard, check_reach=False,
                       verbose=_trace(arm))
    end_deg, _esrc = _gripper_deg(arm, ctrl)
    end_verdict = classify_ref(end_deg, empty_deg, cal, open_deg)
    dropped = bool(mon.dropped())
    z_now = float(arm.tcp()[2])
    print(f"    抬升：{up}  TCP z={z_now:.3f}（该到 {LIFT_Z:.2f}）"
          f"  6 号舵机 起 {mon.peak if mon.peak is None else round(mon.peak, 1)}°"
          f" → 末 {end_deg if end_deg is None else round(end_deg, 1)}°（{_esrc}）"
          f"  判 {end_verdict}  掉落判据 {dropped}")

    # **成没成只看「夹住没有、掉没掉」**（用户 2026-10-16：「这一趟抓成功了呀」）。
    # 原来还搭着 `up == "reached"` —— 抬升没走到 `LIFT_Z` 就把整趟判失败，可那是
    # 「抬到多高」的事，跟「抓没抓住」是两件事。那一趟（`…/bi79lknh7.output` 第 382~388 行）
    # 6 号 46.6°、判 held、掉落判据 False，却被这一条判死。抬升走到哪照旧打在下面。
    ok = bool(end_verdict == "held" and not dropped)
    if ok and up != "reached":
        print(f"    ⚠ 抓着没掉，但抬升只走到 {z_now * 1000:+.0f}mm（该到 "
              f"{LIFT_Z * 1000:+.0f}mm，停因 {up}）—— 这不算这一趟失败")
    out = {"ok": ok, "grasp_z": grasp_z, "grip_deg": end_deg,
           "empty_deg": empty_deg, "start_deg": mon.peak,
           "verdict": end_verdict, "dropped": dropped,
           "lift": up, "tcp_z": z_now}
    if not ok:
        out["why"] = (f"没夹住/掉了（6 号舵机 {end_deg}°，判 {end_verdict}，"
                      f"掉落判据 {dropped}；抬升停因 {up}）")
        return out
    # ---- 抓成了：搬到随机落点放下去（用户 2026-10-17）----
    # **放在这里、不放在 `run` 里**：这一段两条路（从头走 / 从断点接上）共用，
    # 放进去两条就都有；`percep` 是给「半个边长」用的（`_box_half_m`）。
    if PLACE_AFTER_PICK and percep is not None:
        out["place"] = _place_real(arm, percep, center, grasp_z=grasp_z, state=state)
    return out


@register("skill", "pick_real")
class PickRealSkill(Skill):
    """真机上抓那只棕色盒子。判据全在 `grasp_check` 和 `real/perception.py` 里。"""

    name = "pick_real"

    def run(self, arm, cams, state=None, index: int = 0, percep=None,
            instruction=None, **kw) -> dict:
        """抓一次。返回 `{'ok': 成没成, 'why': ..., 'grip_deg': ..., ...}`。

        只往下走一趟，**不重试** —— 抓几次归策略层数（`impls/policy_real.py`），
        里面再自救一把，「抓满 3 次」就数不准了。

        **带 `--resume-pick`（环境变量 `PICK_RESUME=1`）时会先找盘上的断点**（见文件头
        `CHECKPOINT` 那一段）：盘上有、臂也还在那个姿态上，就**从合爪前微调那一跳接着走**
        （`_resume_pick`），不再重走回位 → 起手合爪 → 进场 → 看一眼 → 纠位 → 转正 → 下探。
        """
        from grasp_check import (GraspMonitor, classify_ref, empty_margin,  # noqa: PLC0415
                                 load_thresholds, measure_empty, measure_open)
        from servo_bridge import read_gripper_deg                           # noqa: PLC0415

        cal = load_thresholds()
        ctrl = getattr(arm, "ctrl", None)
        if ctrl is None:
            raise RuntimeError("真机抓取要靠 6 号舵机读数判夹没夹住，"
                               "`arm.ctrl` 现在是 None（串口关了？）")
        if percep is None or not hasattr(percep, "shape"):
            return {"ok": False, "why": "真机抓取要感知给世界坐标（percep）",
                    "give_up": True}
        state = state if state is not None else RoundState()
        sh = percep.shape

        # **合爪前那两道判据要有东西可量。** 三圈爪子轮廓没描过（或者是在别的画幅上
        # 描的）时，`_set_clearance` 一定过不去 —— 那还不如在这儿就收工，别白跑一趟
        # 机械臂动作、白费一次尝试的时间预算。
        try:
            _jaw_shape(_wrist(cams))
        except RuntimeError as e:
            print(f"    ✗ {e}")
            return {"ok": False, "why": str(e), "give_up": True}

        # ---- 0. 断点续跑？----
        # **判在最前面**，因为下面每一步都在动臂：起手那一下 `follow.hold` 合爪、进场、
        # 纠位、转正、下探。断点就是臂现在这个姿态，这几步一步都不能走 —— 尤其是起手
        # 合爪，在这个高度上合上去就是直接去夹方块。
        if _resume_on():
            ck = _load_checkpoint()
            if ck is None:
                print("    ！这一趟带着 `--resume-pick`，但盘上没有断点（或者读不出来）"
                      " —— 从头走这一趟")
            else:
                off = _arm_off_checkpoint(arm, ck)
                if off > RESUME_TOL_DEG:
                    print(f"    ✗ 盘上那份断点是 {ck.get('created')} 写的，但臂已经不在"
                          f"那个姿态上了（最远的关节差 {off:.1f}° > 判据 "
                          f"{RESUME_TOL_DEG:.0f}°）—— 不续跑，如实收工")
                    return {"ok": False, "why": f"臂不在断点姿态上（最远的关节差 {off:.1f}°）",
                            "give_up": True}
                print(f"    ⤒ 盘上有断点（{ck.get('created')} 写的），臂还在那个姿态上"
                      f"（最远的关节差 {off:.1f}°）—— 从合爪前微调那一跳接着走")
                return self._resume_pick(arm, cams, percep, state, index, ctrl, cal, ck)

        # ---- 0. 行程两端：合一次空爪、张一次到底，量出这一趟的两头在哪 ----
        # **这就是自适应的那一步。** 后面所有的「夹住没有」都只看**读数是不是卡在这两头
        # 中间**，不再问「这只盒子该落在哪个角度区间」—— 换盒子、换爪面都不用重标。
        # **两头先拿到，再动臂。** 拿不到就当场收工：不然等于白跑一整趟机械臂动作，
        # 还白耗掉一次尝试的时间预算。
        empty_deg = getattr(arm, "empty_deg", None)
        if empty_deg is None:
            state.seg = "行程两端 → 合一次空爪、再张到底"
            before = read_gripper_deg(ctrl)
            empty_deg = measure_empty(ctrl)
            open_deg = measure_open(ctrl)
            if empty_deg is None or open_deg is None:
                return {"ok": False, "why": "6 号舵机读不到数，行程两端建不起来",
                        "give_up": True}
            arm.empty_deg = empty_deg
            arm.open_deg = open_deg
            print(f"    行程两端：合到底 {empty_deg:.1f}°  /  张到最大 {open_deg:.1f}°"
                  f"（判「夹住」= 读数落在 "
                  f"{empty_deg + empty_margin(cal):.1f}° ~ "
                  f"{open_deg - empty_margin(cal):.1f}° 之间）")
            # **只提醒，不拦。** 合爪前后的角度几乎没变，多半是舵机没出力（扭矩没使能，
            # 见 `real_home.py`），那样后面每一趟都会判「没夹住」。但也有一种正当情况：
            # 爪本来就是合着的。所以这里只把话摆出来，收不收工由人看日志决定。
            if before is not None and abs(empty_deg - before) <= 2.0:
                print(f"    ！合爪指令下去了角度没动（{before:.1f}° → {empty_deg:.1f}°）"
                      f"—— 6 号舵机没出力（扭矩没使能？），或者爪本来就是合着的")
        else:
            open_deg = getattr(arm, "open_deg", None)
            print(f"    行程两端：沿用上一趟实测的 合到底 {empty_deg:.1f}°"
                  f" / 张到最大 "
                  f"{'没记下' if open_deg is None else f'{open_deg:.1f}°'}")

        # ---- 0.5 起步前先把爪子合上 ----
        # `measure_open()` 是张到底量行程的那一下，量完爪子就停在**张着**的位置；
        # 第二次、第三次尝试则是上一趟留下的姿态（合爪到死、或者张开着退回来）。
        # **不能靠 `_goto` 的 `grip=-1.0` 去合**：那只是在 `_grip_cmd` 上按 0.2 rad/步
        # 往回合，全程 1.86 rad 要 ~10 步 —— 而那十步正好是臂从初始位往工位挪的
        # 第一段。`out/run_real_9.log` 第 9~12 行拍到的就是这个（开合 +1.705 → -0.153）。
        # 张开的爪 55.9mm 宽、合到底 30.9mm，宽出来的那 25mm 全蹭在进场那一段上。
        # 这里先用 `drive()` 把它真正合死，臂再动。
        follow.hold(arm, CLOSE_START_STEPS, grip=-1.0, at=arm.tcp(),
                    pos_slew=POS_SLEW, rot_slew=ROT_SLEW)

        table_z = geom.real_table_z()
        # 进场用的起手坐标：**配置里那个「盒子大致摆在哪」**，不是量出来的。这时候
        # 还没看，不知道盒子在不在那儿 —— 后面看一眼量准了会纠回来。
        if REPLAY is not None:
            guess = np.asarray(REPLAY["guess"], dtype=np.float64)
            print(f"    回放：起搜中心用 {np.round(guess * 1000, 0)}mm"
                  f"（不按配置里的 {np.round(geom.real_pick_xy() * 1000, 0)}mm）")
        else:
            guess = np.array([*geom.real_pick_xy(), table_z + float(sh.rest_z)])

        # ---- 0.9 **先站着看一眼**（用户 2026-10-17：「初始位置的视野也要找目标」）----
        # 原来进场点就是配置里那个「盒子大致摆在哪」，走过去才看。实测那一轮（面板日志
        # 2026-10-17 03:27）：**站在初始位置时刷新里看得见盒子**（长方体 16×20×16，
        # 重合度 0.82），走到进场点反倒「找到 False」，接着前后左右四个方向扫、再抬头
        # 拉远，全空，19.3s 收工。
        #
        # 现在改成**先看不走**：初始位置这一帧认得出，就把进场点摆到量出来的那个位置上
        # （`guess` 换掉，下面的进场照旧走 `guess + 80mm`）；认不出就一个字节都不变、
        # 照旧用配置那个数。**这一步不动臂** —— 只是拿当前这一帧算一次，失败也不亏。
        text = instruction or "pick up the brown box"
        if REPLAY is None:
            state.seg = "初始位置先看一眼"
            print("    初始位置先看一眼（不动臂）：")
            c0, y0, f0 = _look(arm, cams, percep, text, guess)
            if c0 is not None and y0 is not None:
                print(f"    ↻ 初始位置看得见：x={c0[0] * 1000:.0f} y={c0[1] * 1000:.0f}"
                      f" z={c0[2] * 1000:.0f}mm yaw {np.degrees(y0):+.1f}°"
                      f" → 进场点改用它（配置里写的是 "
                      f"{np.round(guess[:2] * 1000, 0)}mm）")
                guess = np.array([c0[0], c0[1], guess[2]], dtype=np.float64)
            else:
                print("    · 初始位置没认出来，照旧用配置里那个位置进场")

        # ---- 1. 进场：到大致位置上方 80mm ----
        state.seg = "进场 → 盒子大致位置上方"
        out = _goto(arm, guess + np.array([0.0, 0.0, 0.08]), vmax=speed_vmax(SPEED))
        print(f"    进场：{out}  TCP {np.round(arm.tcp(), 3)}"
              f"（该到 {np.round(guess + [0, 0, 0.08], 3)}）")
        if out == "term":
            return {"ok": False, "why": "到点收工"}
        hit = _stop_here("进场", arm, f"（进场 {out}）")
        if hit is not None:
            return hit

        # ---- 2. 看一眼：画面里那只盒子在基座系哪儿、朝哪 ----
        state.seg = "看一眼 → 量盒子的世界坐标"
        if REPLAY is not None:
            # **回放分支：不看**。中心与朝向用那一趟记下来的值，`_look` / `_sweep`
            # 一步都不走 —— 真机那一趟量出来的就是这两个数。
            center = np.asarray(REPLAY["center"], dtype=np.float64)
            yaw = float(np.radians(REPLAY["yaw_deg"]))
            facts = {"est": None, "shape": f"回放：{REPLAY.get('src', '')}",
                     "size": ""}
            print(f"    回放：不看了，直接用那一趟量出来的"
                  f" x={center[0] * 1000:.0f} y={center[1] * 1000:.0f}"
                  f" z={center[2] * 1000:.0f}mm  yaw {np.degrees(yaw):+.1f}°")
        else:
            center, yaw, facts = _look(arm, cams, percep, text, guess)
        if center is None:
            # **原地不成，先左右看看，再抬头把视野推出去。** 机位一动，画面里那坨色块
            # 的形状、遮挡、边角全变了。上一轮首跑就是卡在这儿（1 个棕色候选、矩形度
            # 0.50 < 门槛 0.78）。两段扫完还没认出来就收工 —— 不再原地重试。
            print("    原地那一眼没认出来，先前后左右，再抬头拉远")
            state.seg = "找目标：前后左右 → 抬头拉远"
            center, yaw, facts = _sweep(arm, cams, percep, text, state)
        if center is None:
            why = facts.get("no_world_why") or facts.get("why") or "没认出来"
            print(f"    ✗ {why}")
            return {"ok": False, "why": f"找不着（{why}）", "give_up": True}
        print(f"    量出来：x={center[0] * 1000:.0f} y={center[1] * 1000:.0f}"
              f" z={center[2] * 1000:.0f}mm  yaw {np.degrees(yaw):+.1f}°"
              f"（起搜中心 {np.round(guess * 1000, 0)}mm，挪了 "
              f"{np.round((center - guess) * 1000, 0)}mm）")
        # **存下这一眼的画面。** 它就是这个 `center` 的来源 —— 后面冻住的那个 3D 中心、
        # 下探的 `aim`、`clear` 全是从它算的。回放分支没有真画面，`_save_look` 自己跳过。
        if REPLAY is None:
            _save_look(cams, facts)
        # 「看一眼」这一段走完了（`_look` 或 `_sweep` 出来都算）。停在这儿的话，臂上
        # 一步是什么姿态就是什么姿态 —— 只报这一眼量到了什么。
        hit = _stop_here("看一眼", arm,
                         f"（量到 x={center[0] * 1000:.0f} y={center[1] * 1000:.0f}"
                         f" z={center[2] * 1000:.0f}mm yaw {np.degrees(yaw):+.1f}°）")
        if hit is not None:
            return hit

        # **形状和尺寸这一眼已经估出来了，往下全用它**（`real/perception.py` 的
        # `estimate_shape` 那一支）：进场高度已经过去了，接下来转正挑哪一面
        # （`sh.normal`）、下探终点都吃这个形状。估不出来才接着用配置里那一行 ——
        # 哪个是哪个感知那边已经并排打出来了，这里只再说一遍往下用的是哪个。
        est = facts.get("est")
        if est is not None:
            sh = shapes.from_spec(est)
        print(f"    往下用这个形状：{facts.get('shape')} {facts.get('size')}"
              f"（{'画面估出来的' if est is not None else '配置里写的'}）")

        # ---- 3. 纠位：挪到**量出来的那个位置**上方，再停稳 ----
        # 进场是照配置那个坐标走的，盒子偏了就不在正上方了。不纠的话下探那一段
        # 就从「只剩纯下降」变成「一边横移一边下降」，横移是贴着盒顶扫过去的。
        state.seg = "挪到盒子正上方"
        hover = center + np.array([0.0, 0.0, 0.08])
        out = _goto(arm, hover, vmax=speed_vmax(SPEED))
        print(f"    纠位：{out}  TCP {np.round(arm.tcp(), 3)}"
              f"（该到 {np.round(hover, 3)}）")
        if out == "term":
            return {"ok": False, "why": "到点收工"}
        hit = _stop_here("挪到盒子正上方", arm, f"（纠位 {out}）")
        if hit is not None:
            return hit

        # ---- 4. 转正：把开合轴转到贴着盒子某一对侧面 ----
        # 挑哪一面由形状自己算（`core.shapes.Box.normal`）：四条侧面法向里**最贴近
        # 现在这条开合轴**的那条 —— 腕子转得最少。盒子摆的 yaw 是随机的，不转正就是
        # 拿指尖去顶棱。
        # **先拿画面把 `yaw` 纠回来**（2026-10-17）。`yaw` 是模型量（俯视剪影拟合），
        # 它歪多少，`sh.normal` 算出来的侧面法向就跟着歪多少 —— 而转正挑哪一面、下探
        # 的落点全挂在它上面。画面这条不经过它：相机和两爪同一个刚体，红区剪影离合爪轴
        # 多少度，就是世界系里离侧面多少度。实测那一眼：画面 27.6°、模型 1.8°。
        fix = _yaw_from_px(sh, center, yaw, _wrist(cams), percep)
        if fix is not None:
            yaw_px, a_meas, a_pred = fix
            print(f"    yaw 按画面纠回来：{np.degrees(yaw):+.1f}° → "
                  f"{np.degrees(yaw_px):+.1f}°（红区剪影 {a_meas:+.1f}°，"
                  f"模型在纠过的 yaw 上投出来 {a_pred:+.1f}°）")
            yaw = yaw_px
        # **三个都该说同一条线。** 模型这边（两爪尖投到画面）和描死的那条（`axis_dir_px`）
        # 对不上，`_box_deg_px` 就不能当「世界系里差多少度」用 —— 先把这条摆出来。
        ax_m = _jaw_axis_model_deg(arm, _wrist(cams))
        ax_t = _jaw_axis_deg(_wrist(cams))
        if ax_m is not None and ax_t is not None:
            print(f"    合爪轴在画面里：模型（两爪尖投出来）{ax_m:+.1f}°，"
                  f"描死的 {ax_t:+.1f}°（差 {_fold90(ax_m - ax_t):+.1f}°）")
        closing = np.asarray(sh.normal(yaw, arm.tool_x()), dtype=np.float64)
        state.seg = "腕子对上方块侧面"
        steps, left = _align(arm, closing, cam=_wrist(cams), percep=percep)
        px_left = _box_deg_px(_wrist(cams), percep)
        m_left = _align_deg(arm, closing)
        print(f"    转正：拧了 {steps} 次 5 号；画面那尺子量还差 "
              + ("量不出来" if px_left is None else f"{px_left:+.1f}°")
              + "，模型那条 "
              + ("量不出来" if m_left is None else f"{m_left:.1f}°")
              + f"（`ALIGN_TOL_DEG` 是 {ALIGN_TOL_DEG:.0f}°）")

        # ---- 5. 下探：一路降到盒子的中心高度 ----
        # **落点不是盒子中心，是「固定爪面贴着盒子那个侧面」的那一点。** 照
        # `pick.py:679-697` 那一段（仿真那一支的落点算式）。`arm.tcp()` 现在是**固定
        # 爪尖**（`real/arm.py` 的 `TCP_DELTA_BODY`），把固定爪尖对到盒子中心就等于让
        # 固定爪插进盒子轮廓里 —— `out/run_real_22.log` 三趟量到的盒子位置 (248,32) /
        # (245,66) / (240,73)，每趟被固定爪从顶面捅着推走几十毫米，合爪时嘴里是空的。
        #
        # 算式：落点 = 盒子中心 + side·(半边长 + 缝)·开合轴。`side` 取固定爪**现在待的
        # 那一侧**（它本来就在某一侧），所以是把固定爪往外摆到贴着盒子那面、缝留在外面。
        # 半边长问形状自己（`sh.support`）：盒子斜着的时候沿法向比半边长宽。
        #
        # 下探终点原来就取中心高度。**2026-10-15 用户改成「中心 + `GRASP_Z_MARGIN_REAL`」**：
        # `out/run_real_36.log` 那一趟爪尖落在估计上表面之下 7mm，横向让开时读数
        # 一动没动、方块跟着走了，用户判定爪尖戳在方块上，先要求再留 10mm、后又加到 15mm
        # （`out/run_real_40.log` 那一趟留着 10mm 时量到爪子轮廓跟红区还是贴上了）。
        # **2026-10-16 加到 25mm**，见 `GRASP_Z_MARGIN_REAL` 那一节。
        xt = _h(arm.tool_x())
        f_tip = np.asarray(arm.tcp(), dtype=np.float64)
        gap = np.asarray(arm.jaw_gap_center(), dtype=np.float64)
        # `side` 取「固定爪相对开口中点在哪一侧」。**不能像 `pick.py` 那样拿
        # `fixed_tip - 盒子中心` 判** —— 那一支里 TCP 和固定爪尖是**两个点**，这个差
        # 就是固定爪横偏的方向；真机上 `tcp()` 报的就是固定爪尖，两者重合，这个差退化
        # 成「悬停点离盒子中心多少毫米」，那是纠位 stall 留下的残差噪声（`run_real_23`
        # 就栽在这儿：三趟 `side` 都是 −1，盒子被撂在两爪外面，合爪合了个空）。
        side = 1.0 if float(np.dot(f_tip - gap, xt)) >= 0.0 else -1.0
        half = float(sh.support(yaw, xt))
        # **画面估出来的半边长不单独用，跟配置里申报的那件比，取大的那个。**
        # 2026-10-15：`out/run_real_29.log` 那一轮，画面把方块估成 15×19×16mm，
        # `support` 给 8.5mm，而配置里申报的是边长 18mm（半边长 9mm，用户核过）——
        # 落点因此只离盒子中心 9.5mm（8.5 + 0 + 1mm 缝），爪尖基本贴着真侧面往下走，
        # 用户看到的就是「固定爪的尖端直接戳上去了」。
        # **估小是危险的那一侧**（爪尖戳上去、把方块推走、合爪时嘴里是空的），
        # 估大只是缝大一点：爪子张到底 55.9mm，让开十几毫米照样夹得住。所以取大。
        dh = _declared_half(yaw, xt)
        if dh is not None and dh > half:
            print(f"    半边长：画面估出 {half * 1000:.1f}mm < 配置申报的 "
                  f"{dh * 1000:.1f}mm —— 按大的那个让开")
            half = dh
        # **位移纠正：缝要从「爪面」量，不是从爪尖量。** 仿真那边是
        # `skills/pick.py:688-694` 的 `pad = arm.fixed_face_reach(xh, side)`，
        # 注释写得明白：「少算这一段，`FIX_CLEAR` 那 1mm 实际只剩 0.25mm」。
        # 这个模型里没有指垫球，所以 `RealArm.fixed_face_reach` 直接量固定指的网格：
        # 在**盒子那一截高度带**里，固定指的料比爪尖还往盒子里探多少。实测
        # （`_probe_jawbox.py`，这个姿态）探 1.0mm —— 也就是说原来那 5mm 缝实际是 4mm。
        rest_z = float(sh.rest_z)
        face = getattr(arm, "fixed_face_reach", None)
        pad = (float(face(xt, side, (float(center[2]) - rest_z,
                                     float(center[2]) + rest_z)))
               if face is not None else 0.0)
        clear = half + pad + FIX_CLEAR_REAL
        # 余量两条取大的：一条从**中心**量（`GRASP_Z_MARGIN_REAL`），一条从**顶面**量
        # （`sh.rest_z + GRASP_Z_OVER_TOP_REAL`）—— 见那两个常数的注释。
        z_margin = max(GRASP_Z_MARGIN_REAL, rest_z + GRASP_Z_OVER_TOP_REAL)
        grasp_z = float(center[2]) + z_margin
        aim = np.array([center[0] + side * clear * xt[0],
                        center[1] + side * clear * xt[1],
                        grasp_z])
        print(f"    落点按固定爪贴面算：固定爪在开合轴 {'+' if side > 0 else '-'} 侧，"
              f"从盒子中心让开 {half * 1000:.1f}mm（半边长）+ "
              f"{pad * 1000:.1f}mm（爪面探出爪尖的部分）"
              f"+ {FIX_CLEAR_REAL * 1000:.0f}mm（缝）"
              f"，开口中点离固定爪尖 {np.linalg.norm(gap - f_tip) * 1000:.1f}mm"
              f"；下探高度 {grasp_z * 1000:.1f}mm（中心 {float(center[2]) * 1000:.1f}"
              f" + 余量 {z_margin * 1000:.1f}mm = max({GRASP_Z_MARGIN_REAL * 1000:.0f}mm,"
              f" 半高 {rest_z * 1000:.1f} + {GRASP_Z_OVER_TOP_REAL * 1000:.0f}mm)）")
        entry = np.array([aim[0], aim[1], float(center[2]) + 0.05])
        #
        # **下探这一段不走笛卡尔那条路。** 那一条是「走一小步、读一次、重解一次」，
        # 实测在真机上一边降一边被带偏（`out/run_real_18.log`：指令 x 恒定 0.239，
        # 实际从 237 滑到 204）。改成先把整列点解好、再一口气走完，见 `_descend`。
        # 代价是这一段不挂 `real/anti_jam.py` 那层守卫了 —— 它是挂在 `follow` 循环里
        # 按步判的，关节空间这条路没有「每步判一次」的位置。顶住了会表现为
        # 「指令下去了、读回来没跟上」，`_descend` 每趟都把两边打出来。
        state.seg = "下探到盒子"
        out, tcp = _descend(arm, aim[:2], entry[2], aim[2], closing=closing,
                            open_at=0.5)
        grasp_z = float(tcp[2])
        print(f"    下探：{out}  TCP z={grasp_z:.3f}（该到 {aim[2]:.3f}）")
        if out != "reached":
            # **最后一趟到不了也不再叫停**（用户 2026-10-18：「下探最后一步还不行就停在那儿
            # 期望后续微调吧，别直接叫停」）。以前这里退回悬停点、整趟判失败；现在停在走到
            # 的地方，把「没到底」交给后面那一截微调继续纠。
            print(f"    ⚠ 下探没到底（{out}，停在 z={grasp_z:.3f}、该到 {aim[2]:.3f}）"
                  f"—— 不叫停，就停在这儿，交给后面的微调")
        hit = _stop_here("下探到盒子", arm, f"（下探 {out}，停在 z={grasp_z:.3f}）")
        if hit is not None:
            return hit
        # 合爪前这一眼是**拦门的判据**，拦门的是画面里那两条（用户 2026-10-15：「我现在就
        # 需要在爪子轮廓和红色有距离 + 合爪方向线和目标中心对齐，只有满足这两个标准才能
        # 合爪」）：缝落在带里 且 `|axis| <= AXIS_TOL_PX`。不过就挪一步、
        # 再量一眼（`_set_clearance`，次数和步长都不写死），挪到进带里为止；挪不进去就
        # 不合爪 —— 退回悬停点，这一趟判失败。
        check = _set_clearance(arm, cams, percep, center, "下探到底（合爪前）",
                               instruction=text, clear=clear,
                               # 微调过了之后那几段还要用的东西，一起写进断点
                               # （`ctx=` 那一段的说明见 `_set_clearance`）。
                               ctx={"hover": [float(v) for v in hover],
                                    "closing": [float(v) for v in closing],
                                    "empty_deg": float(empty_deg),
                                    "open_deg": float(open_deg)})
        if not check.get("ok"):
            _goto(arm, hover, vmax=speed_vmax(SLOW), grip=1.0)
            print(f"    ✗ 合爪前轮廓检查没过（{check.get('why') or '进不了带里'}）："
                  f"这一趟不合爪，退回去")
            return {"ok": False, "why": f"合爪前轮廓检查没过（{check.get('why')}）",
                    "clear": {k: v for k, v in check.items() if k != "near_uv"}}
        # **进带了才往下扎这一截**（用户 2026-10-16：「微调结束后加一个垂直下探，然后再合爪」）。
        # 放在微调后面是有意的：微调全程 z 钉死、只挪水平，扎下去之后就没法再横着调了。
        # 下探终点原来只到「中心 + 25mm」，爪尖停在方块顶面上方 —— `out/run_real_74.log`
        # 就是在这儿空抓的。这一截只降 z，走完才合爪。
        state.seg = "合爪前竖直下探"
        ok_d, tcp_d = _descend_to_grasp(arm, center)
        if not ok_d:
            _goto(arm, hover, vmax=speed_vmax(SLOW), grip=1.0)
            print("    ✗ 合爪前那一截竖直下探没走成：这一趟不合爪，退回去")
            return {"ok": False, "why": "合爪前竖直下探没走成"}
        # **下探之后再修一次轴偏**（用户 2026-10-16：「下探以后再加一个微调，但是只能动
        # 轴偏方向，其他方向不能动」）。竖直那一截把相机跟着带下去了一截，画面里量出来的
        # 轴偏跟在上面那一档量的不是同一个数 —— 所以要在这个高度上再对一次。**只走轴偏
        # 那一维**（`axis_only=True`）：这个高度上沿合爪轴挪就是拿爪面去怼方块。
        state.seg = "下探之后（只修轴偏）"
        ctx2 = {"hover": [float(v) for v in hover],
                "closing": [float(v) for v in closing],
                "empty_deg": float(empty_deg), "open_deg": float(open_deg)}
        check2 = _set_clearance(arm, cams, percep, center, "下探之后（只修轴偏）",
                                instruction=text, clear=clear, ctx=ctx2, axis_only=True)
        if not check2.get("ok"):
            _goto(arm, hover, vmax=speed_vmax(SLOW), grip=1.0)
            print(f"    ✗ 下探之后轴偏没修进带里（{check2.get('why') or '进不了带里'}）："
                  f"这一趟不合爪，退回去")
            return {"ok": False, "why": f"下探之后轴偏没修进带里（{check2.get('why')}）",
                    "clear": {k: v for k, v in check2.items() if k != "near_uv"}}
        tcp_d = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
        return _close_and_lift(arm, ctrl, cal, state, index, grasp_z=float(tcp_d[2]),
                               empty_deg=empty_deg, open_deg=open_deg,
                               center=center, hover=hover, closing=closing,
                               percep=percep)

    def _resume_pick(self, arm, cams, percep, state, index, ctrl, cal, ck: dict) -> dict:
        """从盘上那份断点接着走：进微调循环 → 合爪 → 判 → 抬升。

        **前面那几段一步不动**（`follow.hold` 起手合爪、进场、看一眼、纠位、转正、下探）
        —— 断点就是臂现在这个姿态。
        **夹爪行程两端也不重量**：从盘上那份接过来。这个高度上两个爪子正夹在方块两侧，
        合一次空爪就是拿爪去夹方块（`_close_and_lift` 那段注释同一个道理）。
        """
        ctx = ck.get("ctx") or {}
        empty_deg, open_deg = ctx.get("empty_deg"), ctx.get("open_deg")
        if empty_deg is None or open_deg is None:
            print("    ✗ 盘上那份没记夹爪行程两端 —— 不敢在这个高度上合空爪，不续跑")
            return {"ok": False, "why": "断点里没有夹爪行程两端", "give_up": True}
        arm.empty_deg, arm.open_deg = float(empty_deg), float(open_deg)
        print(f"    行程两端沿用断点那一趟实测的：合到底 {float(empty_deg):.1f}°"
              f" / 张到最大 {float(open_deg):.1f}°（**不再合一次空爪** —— "
              f"这个高度上合上去就夹到方块了）")

        center = np.asarray(ck["center"], dtype=np.float64)
        guess = np.asarray(ck.get("guess") or ck["center"], dtype=np.float64)
        hover = np.asarray(ctx["hover"], dtype=np.float64)
        closing = np.asarray(ctx["closing"], dtype=np.float64)
        text = ck.get("instruction") or "pick up the brown box"
        if bool(ck.get("axis_only")):
            # **断点是在「下探之后那趟只修轴偏」里停的**：竖直那一截上一趟已经走过了
            # （盘上 `axis_only` 记着），这一趟**不再往下扎**，直接接着修轴偏、然后合爪。
            state.seg = "从断点接上 → 下探之后（只修轴偏）"
            check2 = _set_clearance(arm, cams, percep, center,
                                    ck.get("tag") or "下探之后（只修轴偏）",
                                    instruction=text, guess=guess,
                                    clear=float(ck.get("clear") or 0.0),
                                    resume=ck, ctx=ctx, axis_only=True)
            if not check2.get("ok"):
                _goto(arm, hover, vmax=speed_vmax(SLOW), grip=1.0)
                print(f"    ✗ 下探之后轴偏没修进带里（{check2.get('why') or '进不了带里'}）："
                      f"这一趟不合爪，退回去")
                return {"ok": False,
                        "why": f"下探之后轴偏没修进带里（{check2.get('why')}）",
                        "clear": {k: v for k, v in check2.items() if k != "near_uv"}}
            tcp_d = np.asarray(arm.tcp(), dtype=np.float64).reshape(-1)
            return _close_and_lift(arm, ctrl, cal, state, index,
                                   grasp_z=float(tcp_d[2]),
                                   empty_deg=float(empty_deg), open_deg=float(open_deg),
                                   center=center, hover=hover, closing=closing,
                                   percep=percep)
        state.seg = "从断点接上 → 合爪前微调"
        check = _set_clearance(arm, cams, percep, center,
                               ck.get("tag") or "下探到底（合爪前）",
                               instruction=text, guess=guess,
                               clear=float(ck.get("clear") or 0.0), resume=ck, ctx=ctx)
        if not check.get("ok"):
            _goto(arm, hover, vmax=speed_vmax(SLOW), grip=1.0)
            print(f"    ✗ 合爪前轮廓检查没过（{check.get('why') or '进不了带里'}）："
                  f"这一趟不合爪，退回去")
            return {"ok": False, "why": f"合爪前轮廓检查没过（{check.get('why')}）",
                    "clear": {k: v for k, v in check.items() if k != "near_uv"}}
        # 断点接上这条也一样：进带了再往下扎那一截（跟 `run` 那条同一个道理）。
        state.seg = "合爪前竖直下探"
        ok_d, tcp_d = _descend_to_grasp(arm, center)
        if not ok_d:
            _goto(arm, hover, vmax=speed_vmax(SLOW), grip=1.0)
            print("    ✗ 合爪前那一截竖直下探没走成：这一趟不合爪，退回去")
            return {"ok": False, "why": "合爪前竖直下探没走成"}
        return _close_and_lift(arm, ctrl, cal, state, index, grasp_z=float(tcp_d[2]),
                               empty_deg=float(empty_deg), open_deg=float(open_deg),
                               center=center, hover=hover, closing=closing,
                               percep=percep)
